INSERT INTO `ofeedbacks` VALUES (1, 18, 128, 506, '9e7027536815ae64bf390c5395cdc433', 'Faiq Ihsanudin Habibie', '121170048', 'Kelebihan :\r\n(-)\r\n\r\nKekurangan :\r\n- tugas no. 1 tidak tepat, dan penjelasan dasar dx tidak sesuai !!\r\n- tugas no. 2 tidak sesuai yaa!\r\n\r\nMasukan:\r\n- belajar lagi !!\r\n- dasar diagnosis itu terdiri dari apa sajaa?? sebutkan semua nya !', 1, '2026-05-05 01:40:49', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (2, 18, 118, 413, '40c940cda0afb528657553f68565c952', 'Alex Febrian Seninha', '123170011', 'Kelebihan :\r\n\r\nKekurangan : Tugas 1 belum tepat (Inversio uteri?) diagnosis dan dasarnya tidak tepat sehingga Tugas 2 pun tidak tepat\r\n\r\nMasukan: lihat tanda vital dan pf nya keadaan apa yang didapat oleh pasien?', 1, '2026-05-05 01:42:26', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (3, 18, 116, 395, 'b0206601eea24a87abfa960f9a9988d2', 'Yuda Nugraha', '122170194', 'Kelebihan :\r\n\r\nKekurangan :\r\n- tugas no 1 tidak tepat, teliti lagi kasusnya yaaa \r\n- tugas no 2 tidak lengkap dan kurang tepat. \r\n\r\nMasukan:\r\ndiagnosis harus lengkap dan tepat. teliti lagi kasusnya.', 1, '2026-05-05 01:45:32', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (4, 18, 126, 487, 'cc3d37f15b639764fd5052538cc069fb', 'Gastricia Syahla Supriyadi', '122170066', 'Kelebihan :\r\nmenentukan etiologi diagnosis\r\nmenjelaskan beberapa manifestasi klinis\r\n\r\nKekurangan :\r\nBelum mampu menentukan diagnosis kerja\r\nBelum mampu menjelaskan patomekanisme berdasarkan kasus.\r\n\r\nMasukan:', 1, '2026-05-05 01:45:32', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (5, 18, 117, 404, 'dbf0ddb8dfb3f013fc1649fba976cee3', 'Adella Putri Mirela', '123170001', 'Kelebihan :\r\n\r\nKekurangan : no 1\r\n\r\nMasukan: diagnosis kurang lengkap', 1, '2026-05-05 01:45:32', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (6, 18, 115, 386, 'c88af5172f5d847ef7c80ae08e1deb92', 'Wanda Sri Utami', '122170188', 'Kelebihan :\r\n\r\nKekurangan :\r\n1. diagnosis salah\r\n2. tidak lengkap\r\n\r\nMasukan:', 1, '2026-05-05 01:45:33', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (7, 18, 114, 377, 'f2424f9aee6478138ed80afe0823f1f5', 'Abelia Destiyadi', '122170001', 'Kelebihan :\r\n- suara terdengar jelas\r\nKekurangan :\r\n- tidak menuliskan hal yang ingin dijelaskan di papan\r\n- diagnosis tidak sesuai\r\n- dasar diagnosis kurang tepat\r\n- patomekanisme yang dijelaskan kurang tepat\r\nMasukan:\r\nbelajar lagi yaaa..', 1, '2026-05-05 01:45:38', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (8, 18, 112, 359, '2a258f583cd11601b21ffcc07ea5a7c9', 'Dwi Ayu Wulandari', '121170037', 'Feedback:\r\nSoal no. 1. belum bisa menentukan diagnosis dengan benar\r\n              2. Sudah bisa menjelaskan patomekanisme hanya saja belum dikaitkan dengan manifestasi klinis dengan lengkap\r\n\r\n Tetap semangat belajar!', 1, '2026-05-05 01:45:39', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (9, 18, 113, 368, 'c2044ec88f198aeedba08bfd6bd47627', 'Syifa Siti Nurjanah', '122170174', 'Kelebihan : attitude baik\r\n\r\nKekurangan : diagnosis salah, jadi yang lainnya ikut salah semua\r\n\r\nMasukan: belajar lagi kasus2 agar diagnosis tidak salah, di pbl jg kan ada meteri ini harusnya sudah dibahas, klo diagnosis salah dasar diagnosis dll akan salah semua jd belajar lagi yaa', 1, '2026-05-05 01:45:40', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (10, 18, 127, 496, '3e6e09197b45ca61273f7e87b5b56a38', 'Ulul Albab', '121170164', 'Kelebihan :\r\n\r\nKekurangan :\r\ndibaca lagi anamnesis dan pf nya mengarah ke arah apa dari anamensi dan pf nya..\r\ndiagnosis belum tepat.\r\ntanda vitalnya juga sudah pre syok\r\n\r\nMasukan:\r\nbanyak belajar dan baca lagi ya\r\ndifahami soalnya baik2', 1, '2026-05-05 01:45:41', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (11, 18, 119, 423, '9469a0abcd7cf150bf5f27e86dd4b6f2', 'Almanda Regina', '123170015', 'Kelebihan :\r\nada beberapa poin patomekanisme yang cukup relevan\r\n\r\nKekurangan :\r\nDiagnosis tidak tepat dan patopekanisme tidak tepat\r\n\r\nMasukan:\r\njika kamu sudah mendeteksi adanya hipotensi maka kamu harus pertimbangkan ke arah gangguan perfusi/kegawatannya', 1, '2026-05-05 01:45:46', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (12, 18, 122, 451, '4c5d015162312cb959272e8372127595', 'Avghan Denzan Nanzira', '122170023', 'Kelebihan : \r\nsudah paham penegakan diagnosis\r\n\r\nKekurangan : \r\ntugas pertama kurang tepat\r\ntugas kedua kurang tepat dan kurang lengkap, tdk dijelaskan keterlibatan system vascular sistemik \r\n\r\nMasukan:\r\nbelajar lagi manifestasi klinis tiap diagnosis sehingga diagnosis dpt lebih tepat dan lengkap', 1, '2026-05-05 01:45:48', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (13, 18, 123, 461, 'cd8101586210e986223312b55570f487', 'Isnandita Zakia Halimar Fajri', '123170070', 'Kelebihan :\r\n\r\nKekurangan :\r\ntugas 1\r\ntugas nya sebutkan diagnosis kemudian jelaskan dasar diagnosis --> diagnosis nya tidak tepat coba dibaca perlahan skenarionya kalau ujian ya lalu dasar diagnosis kenapa mendiagnosis itu juga tidak dijelaskan, darimana bisa dapat diagnosis itu, anamnesis nya ketemu apa, PF nya dan lain-lain. penjelasannya tidak tepat ya\r\n\r\ntugas 2\r\npatofisiologi yang dijelaskan tidak sesuai dengan yang ada di skenario kasus\r\n\r\nMasukan:\r\n- tugas ujiannya dibaca dengan baik dan teliti ya\r\n- belajar lagi yang baik ya apa itu plasenta previa dan lain lain', 1, '2026-05-05 01:45:52', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (14, 18, 125, 478, '8821c45b45867f38c01b5e64a9a7a4a1', 'Zaki Ihsan Nugroho', '123170194', 'Kelebihan :\r\n\r\nKekurangan :\r\n\r\nMasukan:diagnosis salah , patomekanisme terksait gejala klinis tidak sesuai,\r\npenarikan tali pusat kuat', 1, '2026-05-05 01:45:57', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (15, 18, 121, 442, '41aef77fe469793ba69ddd69f8fd32f1', 'Zahra Julia', '123170190', 'Kelebihan :\r\n- Mahasiswa menjelaskan etiologi dari kasus\r\n\r\nKekurangan :\r\n- Mahasiswa tidak mampu menentukan diagnosis disertai dengan dasar diagnosis: INVERSIO UTERI dikarenakan tarikan tali pusat diganti menjadi RETENSIO PLASENTA diganti menjadi INVERSIO INCRETA\r\n- Mahasiswa tidak menjelaskan lengkap patomekanisme terjadinya manifestasi klinis: robekan dinding uteri\r\n- Menyebutkan TD, RR menurun namun patomekanisme yang disampaikan kurang tepat\r\n\r\nMasukan:\r\n- Pelajari kembali dalam penegakan diagnosis dan dasar diagnosis dari kasus\r\n- Pelajari kembali patofisiologi  Robekan dinding uterus dan volume darah ↓ sehingga menimbulkan manifestasi klinis', 1, '2026-05-05 01:45:58', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (16, 18, 120, 432, 'f206c19790559aac7a74e0ff1fbe2093', 'Pujawati Yulia Sari', '123170133', 'Kelebihan :Sudah memulai dengan percaya diri\r\n\r\nKekurangan : \r\n1. Penjelasan tidak tepat, tidak lengkap dan tidak sistematis. \r\n2. Peserta belum mampu mengenali apa yang menjadi masalah pada skenario. Biasakan melakukan analisis yang menyeluruh terhadap kasus dan apa diagnosis yang sekarang yang menjadi penyebab kondisi menurun pasien skrg. \r\n3. Penjelasan patomekanisme belum tepat. Kenapa ada nyeri hebat? Kenapa ada distensi abd? Dan penjelasan yang lain belum tepat. \r\n\r\nMasukan:Belajar lagi ya Puja', 1, '2026-05-05 01:46:01', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (17, 18, 124, 469, '88da1a44ebcc158417232782ef140178', 'Nazib Mohamad Yassir', '120170142', 'Kelebihan :\r\n\r\nKekurangan :\r\ntidak  berusaha menjelaskan apapun. \r\nMasukan:', 1, '2026-05-05 01:46:10', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (18, 18, 129, 516, 'db927bdea56442d3a35db34452d2f65d', 'Fikri Fauzi Ramdhani', '123170054', 'Kelebihan :\r\nbagus\r\nKekurangan :\r\n\r\nMasukan:', 1, '2026-05-05 01:46:21', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (19, 18, 125, 479, '21e2b727bcb4b3a9e9497d0abb992631', 'Hafizh Achmad Fauzan', '123170062', 'Kelebihan :\r\n\r\nKekurangan :\r\n\r\nMasukan:penjelasan cukup tepat', 1, '2026-05-05 01:59:04', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (20, 18, 115, 387, '943a33e577e174a70e9e601a99c3ed5e', 'Khaerul Himawan', '120170099', 'Kelebihan :\r\n\r\nKekurangan :\r\n1. patomekanisme tidak dapat dijelaskan--> tidak tepat\r\n2. tidak lengkap hanya 1-2 poin\r\nMasukan:', 1, '2026-05-05 02:01:07', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (21, 18, 118, 414, '30098aea026ffc8dbfe1d85f1a7e13e5', '\'amru Syauqi', '123170017', 'Kelebihan : Tugas 1 dan 2\r\n\r\nKekurangan :\r\n\r\nMasukan: screening blm lengkap tp sudah baik', 1, '2026-05-05 02:01:10', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (22, 18, 113, 369, 'df062475c6ac0e94b21fbb4c04ad60e1', 'Torik Dzulkifli Mahpudin', '122170180', 'Kelebihan : tugas 1 \r\n\r\nKekurangan : tugas satu sdh dijawab tapi tidak lengkap n penjelasan kurang tepat, tugas dua tidak terjawab\r\n\r\nMasukan: belajar lagi screening apa saja, bedakan skreening sama pemeriksaan fisik', 1, '2026-05-05 02:01:10', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (23, 18, 121, 443, '5b726fff5475c5a310b72d14038a4726', 'Syalaisha Attaya Frahnaz Tafael', '123170172', 'Kelebihan :\r\n- Menjelaskan beberapa screening BBL sesuai kasus\r\n\r\nKekurangan :\r\n- Tidak mampu menjelaskan patomekanisme risiko: hanya menjelaskan infeksi CMV menyebabkan gawat janin\r\n- Tidak lengkap menjelaskan screening bayi baru lahir sesuai pada kasus: genetik, penglihatan dari  bayi, pendengaran, kadar bilirubin bayi, kardiovaskular, hemolitik\r\n\r\nMasukan:\r\n- Pelajari faktor resiko CMV : proses dari Ibu hamil terpapar CMV - Viremia → Komplikasi\r\n- Pelajari kembali screening bayi baru lahir sesuai dengan kasus dengan tepat dan lengkap', 1, '2026-05-05 02:01:13', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (24, 18, 126, 488, 'a1df4deda77738cfc00b3dbc2b04fad5', 'Haura Hissania Padilah', '123170066', 'Kelebihan :\r\nMampu menentukan etiologi sesuai dengan kasus\r\n\r\nKekurangan :\r\nBelum mampu menjelaskan patofisiologi/mekanisme terjadinya manifestasi klinis dengan tepat sesuai kasus\r\nMahasiswa belum mampu menjelaskan screening bayi baru lahir yang sesuai pada kasus \r\n\r\nMasukan:', 1, '2026-05-05 02:01:13', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (25, 18, 128, 507, '0faa3203e8701b8b1fb2ef6f32cced46', 'Faraditha Putri Salsabila', '123170048', 'Kelebihan :\r\n- menjelaskan tugas no. 1 tapi kurang lengkap untuk resiko nya hanya menyebutkan 3 poin saja \r\n- menjelaskan tugas 2 namun hanya 3-4 point sajaa\r\n\r\nKekurangan :\r\n- tugas no. 1 dilengkapi lagi \r\n- tugas no. 2 disesuaikan screening nya dgn resiko bayinya. \r\n- Igm/ IgG di lakukan ? pada saat kapan jika dilakukan ??\r\n\r\nMasukan:\r\n- belajar lagi yaaa dee ! :))\r\n- lengkapi yg ,masih blm lengkapnya, semangat !', 1, '2026-05-05 02:01:21', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (26, 18, 123, 462, 'a8451f16b03c4337f7a1e360572b4e60', 'Jihan Suci Musyaffa', '123170072', 'Kelebihan :\r\n\r\nKekurangan :\r\ntugas 1\r\npenjelasan patofisiologi sesuai kasus hubungkan dengan manifestasi nya tidak tepat, virus nya kemana, penjelasannya masuk kemudian sistem imum difagosit makrofag, loh ini mah semua infeksi jelas ada keterlibatan sistem imun. penjelasan patofisiologi dari kasus nya mana? tidak ada. belajar lagi yang baik \r\n\r\ntugas 2\r\nskrining bayi baru lahir apa yang harus dilakukan sesuai pada kasus? tidak dijelaskan, kan banyak ya\r\n\r\n\r\nMasukan:\r\n- belajar lagi yang baik ya de, ini kan ujian loh sudah semester 6\r\n- belajar lagi terutama patomekanisme', 1, '2026-05-05 02:01:25', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (27, 18, 112, 360, '7537b3b49dca02c71a3be6aedd020e2d', 'Ainun Azkiya Fitriati', '122170008', 'Feedback:\r\nSoal no. 1. Sudah menjelaskan patomekanisme tapi masih kurang tepat dan terlihat bingung arahnya mau dibawa kemana\r\n              2. tidak menjelaskan screening pada bayi baru lahir\r\n\r\n Tetap semangat belajar!', 1, '2026-05-05 02:01:26', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (28, 18, 116, 396, 'e1cdb216a0bfd191925992381fe803f2', 'Aghi Ghifari Pratama', '123170003', 'Kelebihan :\r\n\r\nKekurangan :\r\ntugas no 2 tidak lengkap \r\n\r\nMasukan:', 1, '2026-05-05 02:01:27', '2026-05-06 07:05:11');
