INSERT INTO `ofeedbacks` VALUES (30, 18, 122, 452, '985041791f473e8608f089b7b555d2ac', 'Tri Rahayu Prihatiningsih', '123170178', 'Kelebihan :\r\nbisa menjelaskan patomekanisme dengan cukup baik namun akan lebih baik (lanjut di kekurangan)\r\n\r\nKekurangan :\r\n- jika patomekanisme yang dijelakan lebih mendalam, mengapa bisa terjadi suatu manifestasi klinis\r\n- tugas kedua kurang lengkap\r\n\r\nMasukan:\r\n- Lebih detail lagi ya dan menyeluruh ya de', 1, '2026-05-05 02:01:27', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (31, 18, 129, 517, 'b8a9a64d13c15a9f6d9666546cda6246', 'Fitri Noviyanti', '123170056', 'Kelebihan :\r\nsudah cukup baik \r\nKekurangan :\r\n\r\nMasukan:', 1, '2026-05-05 02:01:30', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (32, 18, 127, 497, 'e92026a054ff7aeb048603da4edd191a', 'Fahira Sifa Az Zahra', '123170044', 'Kelebihan :\r\n\r\nKekurangan :\r\npenjelasan patomekanisme resiko dan komplikasi masih belum lengkap\r\ntugas nomer 2 screening belum dibahas dan disebutkan dengan benar\r\n\r\nMasukan:\r\nbanyak belajar dan baca lagi ya\r\ndifahami soalnya baik2\r\nsemangat selalu', 1, '2026-05-05 02:01:35', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (33, 18, 124, 470, 'e4d0fccc02ec04c25eb28bb6db65ceff', 'Wafi Fajri Muharram', '123170184', 'Kelebihan :\r\n\r\nKekurangan :\r\npenjelasan mengenai patomekanisme dari resiko tidak tepat\r\nscreening : pemberian nutrisi, imunisasi?? --> apakah ini termasuk screening???\r\nrontgen thoraks? kurang tepat \r\n\r\nMasukan:', 1, '2026-05-05 02:01:37', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (34, 18, 119, 424, 'c07b1ed6a19d1d22fb39a6ce4f84b1ba', 'Andi Mirelle Besse Amirah', '122170017', 'Kelebihan : 1 poin screening benar, namun screening yang lainnya tidak tepat\r\n\r\nKekurangan : patomekanisme tidak tepat karena bukan proses parasitemia\r\n\r\nMasukan:\r\nbelajar lagi yaa patomekanisme nya seperti apa, bedakan virus dan parasit seperti apa, dan ookist itu ada pada agen penyakit apa', 1, '2026-05-05 02:01:38', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (35, 18, 114, 378, '3826d5d0f45fd43cc93afdeb73b95908', 'Dinda Ayu Afriliyani', '122170046', 'Kelebihan :\r\nmenuliskan yang akan dijelaskan di papan tulis\r\nsuara terdengar jelas\r\n\r\nKekurangan :\r\npatomekanisme yamg dijelaskan kurang tepat\r\ntidak menjelaskan komplikasi yang terjadi\r\nusulan screning juga kurang lengkap\r\nMasukan:\r\nBelajar lagi yaa..', 1, '2026-05-05 02:01:49', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (36, 18, 120, 433, 'ec3f4bf1644ec0b50c55b9fb78ad56a3', 'Qonita Qotrunnada Mulyana', '123170135', 'Kelebihan :Sudah memulai dengan percaya diri\r\n\r\nKekurangan : \r\n1. Penjelasan tidak tepat, tidak lengkap dan tidak sistematis. \r\n2. Peserta belum mampu mengenali apa yang menjadi pertanyaan pada skenario. Biasakan memahami apa yang menjadi pertanyaan!\r\n3. Penjelasan patomekanisme resiko belum tepat. Apakah CMV pada ibu ada hubungannya dengan bayi setelah lahir? Caranya? \r\n\r\nMasukan:Belajar lagi ya Qonita', 1, '2026-05-05 02:01:55', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (37, 18, 117, 406, 'ad9d0aa3e6082d3c1f1f3f029b3b7d05', 'Darrell Athhar Dermawan', '123170029', 'Kelebihan :\r\n\r\nKekurangan : no 1\r\n\r\nMasukan: penjelasanya kurang lengkap dan terstruktur.', 1, '2026-05-05 02:14:10', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (38, 18, 129, 518, '92585413a4a388c3769475a5a8989aae', 'Gina Nabila', '123170058', 'Kelebihan :\r\npenjelasannya relevan dengan soal \r\nKekurangan :\r\nsangat kesulitan dalam menjelaskan konsepnya hingga sangat sulit untuk dipahami bahkan oleh penguji sendiri. utk soal no 1 banyak yang lupa\r\nMasukan:\r\nbelajar lagi dan untuk siklus2 lebih dipahami kembali', 1, '2026-05-05 02:16:44', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (39, 18, 115, 388, '35cae6712ca10d1af244407fb776c7f3', 'Fahrudin Qurbani', '122170055', 'Kelebihan :\r\n\r\nKekurangan :\r\n1. tidak komplit\r\n2. tepat namun tidak lengkap dan harus sistematis ya..\r\n\r\nMasukan:', 1, '2026-05-05 02:16:47', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (40, 18, 123, 463, 'd2ca8e1645737a9242c2f671581a540a', 'Christy Lintang Destiara', '123170028', 'Kelebihan :\r\ntugas 1 : cukup baik\r\ntugas 2 : baik\r\n\r\nKekurangan :\r\n\r\nMasukan:\r\n- belajar lagi yang baik ya', 1, '2026-05-05 02:16:47', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (41, 18, 112, 361, '4a785d12eef876493131abc7a1adf341', 'Dwita Ameliya Rahman Sapoetri', '123170037', 'Feedback:\r\nSoal no. 1. sudah menjelaskan dengan tepat hanya sedikit kurang lengkap\r\n              2. sudah tepat\r\n\r\n Tetap semangat belajar!', 1, '2026-05-05 02:16:48', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (42, 18, 121, 444, 'ca11894f1e4ec27dd7db0c11ab66a7d9', 'Tia Angelista', '123170176', 'Kelebihan :\r\n- Mampu menjelaskan sirkulasi fetomaternal \r\n\r\nKekurangan :\r\n- Tidak mampu menjelaskan tumbuh kembang fetus sesuai usia kehamilan, penjelasan perkembangan fetus di uk 20mg namun tidak sesuai dan tidak lengkap\r\n- Disebutkan pada uk 20mg jari-jari sudah mulai terpisah, perkembangan eksoderm menjadi kulit, dsb\r\n\r\nMasukan:\r\n- Pelajari kembali mengenai tumbuh kembang fetus sesuai USIA KEHAMILAN secara tepat dan lengkap meliputi: Berat dan panjang, Perkembangan organ, Perkembangan fungsi organ\r\n- Pelajari sirkulasi fetomaternal secara sistematis', 1, '2026-05-05 02:16:49', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (43, 18, 118, 415, '651369b1f2c0c3f352dc119ac325df5c', 'Bintang Pamungkas', '122170032', 'Kelebihan :\r\n\r\nKekurangan : Tugas 1 belum tepat bahasnya kmn mn tiba2 bahas ikterus neonatorum kan yang d minta tahapan tumbah pd UK 20 minggu. Tugas 2 juga tidak tepat namanya \"sirkulasi\" itu seperti lingkaran tdk terputus itu yg seharusnya d jelaskan\r\n\r\nMasukan: untuk tugas 1 pisahkan mana yg masuk tumbuh dan mana yang berkembang', 1, '2026-05-05 02:16:49', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (44, 18, 127, 498, 'cc5cefd1f76bb8426e62765d5de5ee01', 'Fakhri Fawwaz Syabani', '123170046', 'Kelebihan :\r\npenjelasan sirkulasi cukup baik\r\n\r\nKekurangan :\r\npenjelasan tumbuh kembangnya masih belum lengkap terkait perkembangan organ dan pertumbuhannya\r\n\r\nMasukan:\r\nbanyak belajar dan baca lagi ya\r\nsemangat selalu', 1, '2026-05-05 02:16:50', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (45, 18, 114, 379, '0b8a0edfa737b52d35ce1c86a24f9fd7', 'Maysi Adzizah', '123170089', 'Kelebihan :\r\nmenuliskan yang dijelaskan di papan\r\nsuara terdengar cukup jelas\r\nsirkulasi fetomaternal yang dijelakan cukup baik\r\nKekurangan :\r\ntumbuh kembang fetus tidak dijelaskan sesuai usia kasus\r\ntumbuh kembang fetus disebutkan tidak lengkap\r\nMasukan:\r\nbelajar lagi yaaa..', 1, '2026-05-05 02:16:50', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (46, 18, 128, 508, '76c0e5ff12d4b201dd2f6933c5c3771c', 'Fihra Shoffa Ismawanti', '123170052', 'Kelebihan :\r\n- menjelaskan tugas 2 tp tidak lengkap \r\n\r\nKekurangan :\r\n- penjelasan tugas 1 kurang tepat\r\n- penjelasan tugas 2 kurang lengkap dan ada siklus yg tidak sesuai ! \r\n\r\nMasukan:\r\n- belajar lagi yaaa de !!\r\n- semangatt ! :))', 1, '2026-05-05 02:16:54', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (47, 18, 119, 425, '991f39f2737335294e6cc452d9965c19', 'Muhammad Alma Syakri Faiz Sabirin', '122170116', 'Kelebihan :\r\n\r\nKekurangan :\r\njawaban no 1 dan 2 tidak tepat\r\n\r\nMasukan:\r\nbelajar lagi yaa', 1, '2026-05-05 02:16:55', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (48, 18, 124, 471, '74b975a1bc382324a65178b8e0a5529a', 'Yufian Hamdu', '123170188', 'Kelebihan :\r\nmampu menjelaskan sirkulasi fetomaternal dengan baik \r\n\r\nKekurangan :\r\npenjelasan tumbuh kembang fetus, kurang tepat di kisaran berat badan janinnya. \r\n\r\nMasukan:', 1, '2026-05-05 02:16:56', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (49, 18, 116, 397, 'f1045e2b02c5dba8597e6f2ab9b38154', 'Ariza Adhwa Azzikra', '123170023', 'Kelebihan :\r\n\r\nKekurangan :\r\n- tugas no 2 sudah baik tetapi kurang lengkap. \r\n- tugas no 1 tdk lengkap \r\n\r\nMasukan:', 1, '2026-05-05 02:17:03', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (50, 18, 113, 370, '8da7d0929aa541fcfc0c13eef8c52313', 'Eva Meutia', '123170041', 'Kelebihan : attitude\r\n\r\nKekurangan : Tugas 1 tidak tepat, tugas 2 kurang tepat penjelasan banyak yg terbalik n tidak lengkap\r\n\r\nMasukan: belajar lagi secara lengkap', 1, '2026-05-05 02:17:08', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (51, 18, 126, 489, '16fee61883567701b9b3632d66149966', 'Hening Ageng Maes', '123170068', 'Kelebihan :\r\nmenjelaskan perkiraan BB janin\r\n\r\n\r\nKekurangan :\r\nMahasiswa belum mampu menjelaskan tumbuh kembang fetus sesuai usia kehamilan secara tepat dan lengkap\r\nMahasiswa belum mampu menjelaskan sirkulasi fetomaternal secara tepat, lengkap, dan sistematis.\r\n\r\n\r\nMasukan:\r\nPelajari kembali apa saja yang dinilai mengenai perkembangan janin sesuai usia kehamilan (aspek apa saja yang dinilai)\r\nPelajari kembali siklus fetomartenal, secara detail', 1, '2026-05-05 02:17:08', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (52, 18, 122, 453, '093e17806913802f9860460b82e69e8b', 'Vallentino', '123170180', 'Kelebihan :\r\nbisa menjelaskan tugas 2  namun akan lebih baik (lanjut di kekurangan)\r\n\r\nKekurangan :\r\n- jika lebih detail lagi pada tugas 2, melewati arteri apa saja.\r\n- tugas nomor 1 kurang lengkap, dan kurang tepat\r\n\r\nMasukan:\r\n- Lebih detail lagi ya de belajarnya', 1, '2026-05-05 02:17:17', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (53, 18, 120, 434, '90cbe79c1748effbec6054de5da60420', 'Raihaan Indra Kusumah', '123170139', 'elebihan :Sudah memulai dengan percaya diri\r\n\r\nKekurangan : \r\n1. Penjelasan belum tepat dan lengkap\r\n2. Peserta belum mampu mengenali apa yang menjadi masalah pada skenario. Biasakan fokus pada pertanyaan yang dimaksud, yakni janin usia 20 minggu. \r\n3. Penjelasan sirkulasi belum tepat dan lengkap. \r\n\r\nMasukan:Belajar lagi ya Raihaan...', 1, '2026-05-05 02:17:23', '2026-05-06 07:05:11');
