INSERT INTO `ofeedbacks` VALUES (57, 18, 112, 362, '849e43443844897dbf3032af23cf8dbf', 'Erlangga Dwi Febrian', '123170039', 'Feedback:\r\nSoal no. 1. Sudah menjelaskan patomekanisme dengan tepat, hanya saja risiko yg mungkin dialami oleh bayi belum lengkap\r\n              2. Sudah tepat, hanya sedikit kurang lengkap\r\n\r\n Tetap semangat belajar!', 1, '2026-05-05 02:32:26', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (58, 18, 127, 499, '6b40c553cfab1dd3eb4cfa1925366f20', 'Dwi Vita Aulia', '123170036', 'Kelebihan :\r\n\r\nKekurangan :\r\npenjelasan untuk tugas 1 dan 2 masih belum lengkap..\r\n\r\nMasukan:\r\nbanyak belajar dan baca lagi ya\r\nsemangat selalu', 1, '2026-05-05 02:32:28', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (59, 18, 116, 398, '01cd52b3ddbcadfb8e8a72168e730a1d', 'Choirunnisa Bella Alifiyanti', '123170027', 'Kelebihan :\r\n\r\nKekurangan :\r\ntugas 1 dan tugas 2 tdk lengkap dan tepat \r\n\r\nMasukan:\r\nBaca lagi yaa tugasnya dan dipahami pertanyaannya', 1, '2026-05-05 02:32:32', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (60, 18, 117, 407, 'c7fdbc1022ee1badc998cf6a2ee626e5', 'Dendy Andrian Firdaus', '123170031', 'Kelebihan :\r\n\r\nKekurangan : 2\r\n\r\nMasukan: penjelasanya kurang lengkap dan terstruktur', 1, '2026-05-05 02:32:35', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (61, 18, 128, 509, '70ff8a65346312cd9a8b5a0c297fb232', 'Evan Adiyatma', '123170042', 'Kelebihan :\r\n- menyebutkan tugas 2 namun hanya beberapa point yg benar\r\n\r\nKekurangan :\r\n- penjelasan tugas 1, kurang tepat yaa! \r\n\r\nMasukan:\r\n- baca lagi tugas nya dan pahami maksud tugasnya yaa de !\r\n- belajar lagi yaaa de :) semangattt !!', 1, '2026-05-05 02:32:36', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (62, 18, 120, 435, '9c7639a96a590f0b64285e44b6c6e783', 'Oom Lasidah', '123170131', 'elebihan :Sudah memulai dengan percaya diri\r\n\r\nKekurangan : \r\n1. Penjelasan ada yang belum lengkap\r\n2. Penjelasan patomekanisme risiko pada bayi di kasus belum lengkap\r\n3. Penjelasan kriteria bayi risti sudah cukup baik, hanya saja masih ada yang belum disebut.\r\n\r\nMasukan:Belajar lagi ya Oom.', 1, '2026-05-05 02:32:37', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (63, 18, 121, 445, '869b781d0f97352a1407ceed7ac7087a', 'Alzena Salma Harmani', '123170016', 'Kelebihan :\r\n- Menjelaskan patomekanisme risiko yang mungkin terjadi pada bayi tersebut: infeksi maternal\r\n- Menjelaskan kriteria yang termasuk bayi risiko tinggi: UK <37mgu atau >42mgu, BB <1kg atau 4kg, komplikasi maternal, APGAR, lethargi neonatal\r\n\r\nKekurangan :\r\n- Tidak mampu menjelaskan patomekanisme risiko lebih lanjut dan secara lengkap yang mungkin terjadi pada bayi tersebut\r\n- Kriteria yang termasuk bayi risiko tinggi tidak lengkap\r\n\r\nMasukan:\r\n- Pelajari kembali patomekanisme risiko yang mungkin terjadi pada bayi sesuai kasus tersebut, diawali dari infeksi asenden genital hingga munculnya kelainan/ komplikasi yg mgkn terjadi\r\n- Pelajari kriteria bayi risiko tinggi secara lengkap', 1, '2026-05-05 02:32:40', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (64, 18, 115, 389, 'b8ebdf35adc9585f5f316d36e418708c', 'Angelica Yuliani Agian', '123170019', 'Kelebihan :\r\n\r\nKekurangan :\r\n1. patomekanisme resiko bukan manifes\r\n2,\r\nMasukan:\r\nperhatikan soal\r\naterm jadi risiko? spesifik jika menjelaskan jangan dijelaskan semua', 1, '2026-05-05 02:32:43', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (65, 18, 123, 464, 'f929208926210e10714ff7e06e2ba3ce', 'Dimas Syehwanul Arifin', '123170034', 'Kelebihan :\r\n\r\nKekurangan :\r\ntugas 1\r\ntugas nya jelas diminta jelaskan patomekanisme risiko , mana penjelasnnya tidak ada. kan diminta sesuai kasus jadi ga ada mungkin-mungkin lagi, jelaskan sesuai dengan kasus. penjelasan yang dijelaskan kurang sesuai, hanya asfiksia \r\n\r\ntugas 2\r\nkriteria bayi risti lalu bisa menimbulkan apa de jelaskan ya. baru 6 ya\r\n\r\nMasukan:\r\n- belajar lagi yang baik ya untuk ujiannya', 1, '2026-05-05 02:32:47', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (66, 18, 119, 426, 'f67556bd4e7847675c4d20048e76c1f3', 'Fatuh Hanin Nasywa', '123170051', 'Kelebihan :\r\nno 2. menjawab 3 kriteria\r\nKekurangan :\r\njawaban no 1 beberapa ada yang relevan, tetapi masih banyak yang belum tersampaikan\r\n\r\nMasukan:\r\nmohon dibaca dengan teliti pertanyaannya sehingga jawaban yang disampaikan bisa tepat sasaran', 1, '2026-05-05 02:32:49', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (67, 18, 126, 490, 'b0c75b5c464017021540fc889492f42b', 'Alik Dwi Rencani', '123170012', 'Kelebihan :\r\nMahasiswa menjelaskan 2 kriteria yang termasuk bayi risiko tinggi \r\n\r\nKekurangan :\r\nMahasiswa belum mampu menjelaskan patomekanisme risiko yang mungki terjadi pada bayi secara tepat, \r\n\r\nMasukan:', 1, '2026-05-05 02:32:50', '2026-05-06 07:05:11');
