INSERT INTO `ofeedbacks` VALUES (74, 18, 114, 381, 'e8feac2c99f9e227ba86a0c5087095fa', 'Widi\'ah', '123170185', 'Kelebihan :\r\nmenuliskan apa yang akan dijelaskan di papan tulis\r\nsuara terdengar cukup jelas\r\nKekurangan :\r\nmekanisme breast enggorgement kurang lengkap, manifestasi klinis juga dijelaskan kurang lengkap\r\nfisiologis masa nifas kurang lengkap dijelaskan kemudian dilengkapi di akhir-akhir\r\nMasukan:\r\ncukup baik', 1, '2026-05-05 02:47:29', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (75, 18, 113, 372, '5edb1339070e2db8dd2c348c95fe1d2e', 'Zaki Abdul Fayedh', '123170193', 'Kelebihan : pemahaman materi cukup baik\r\n\r\nKekurangan : tugas 1 dan 2 kurang lengkap\r\n\r\nMasukan : pemahaman materi sdh cukup baik tp penjelasannya kurang lengkap dan menjelaskan harus sesuai dg pertanyaan, jangan menjelaskan hal2 lain dulu sebelum jawaban dari pertanyaannya terjawab semua agar nilainya maksimal', 1, '2026-05-05 02:48:05', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (76, 18, 112, 363, 'dbaecbffe990e40c62f81985d7b2070e', 'Muhammaad Pasha Ibrahim', '123170099', 'Feedback:\r\nSoal no. 1. sudah menjelaskan secara tepat mekanisme terjadinya breast engorgement, hanya sedikit kurang lengkap\r\n              2. sudah dapat menentukan perubahan fisiologis masa nifas dengan tepat, namun kurang lengkap\r\n\r\n Tetap semangat belajar!', 1, '2026-05-05 02:48:06', '2026-05-06 07:05:11');
