INSERT INTO `ofeedbacks` VALUES (84, 18, 123, 465, '7165e6b51533a4e6bae9983679a8b138', 'Mutiara Nurhapipah', '123170112', 'Kelebihan :\r\n\r\nKekurangan :\r\ntugas 1 \r\ndiminta untuk menjelaskan mekanisme terjadinya kasus tersebut, kira-kira itu apa? nah dijelaskan secara jelas kenapa bisa terjadi? apakah pegaruh hormonnya? hormon apa? mempengaruhi apa?. penjelasnnya tadi belum menjawal tugasnya\r\n\r\ntugas 2\r\nperubahan fisiologis pada masa nifas, diminta menjelaskan perubahan fisiologis pada masa nifas de. pada masa nifas terjadi apa saja secara fisiologis nya? ini juga belum menjawab pertaannya\r\n\r\nMasukan:\r\n- skenario nya dibaca dengan baik dan teliti \r\n- belajar lagi yang baik, kan ini ujian loh de sudah semester 6 loh', 1, '2026-05-05 02:48:22', '2026-05-06 07:05:11');
