INSERT INTO `ofeedbacks` VALUES (90, 18, 121, 446, '66ac1e73ae398b7e53d4c5860c17e8ce', 'Angel Prisila', '123170018', 'Kelebihan :\r\n- Penentuan kelainan pada kasus\r\n\r\nKekurangan :\r\n- Kurang tepat menjelaskan mekanisme terjadinya keluhan pada kasus\r\n- Patomekanisme dan faktor resiko yang kurang sesuai dengan kasus\r\n- Tidak tepat menjelaskan perubahan fisiologis pada masa nifas\r\n\r\nMasukan:\r\n- Pelajari kembali mengenai mekanisme terjadinya breast engorgement hingga manifestasi klinis yang muncul\r\n- Perubahan fisiologis masa nifas meliputi area jalan lahir, tahapan involusi uterus. lochia, tempat penempelan plasenta, perubahan pada traktus urinarius, peritoneum hingga dinding perut', 1, '2026-05-05 02:49:07', '2026-05-06 07:05:11');
