INSERT INTO `ofeedbacks` VALUES (96, 18, 126, 492, 'bd642f2bccfdce508f8a57c528466c64', 'Ramadiy Rafi\'uddin', '123170142', 'Kelebihan :\r\n\r\nKekurangan :\r\nMahasiswa belum  mampu menjelaskan mekanisme yang menginduksi proses pada kasus tersebut\r\nMahasiswa belum mampu menjelaskan penjelasan komponen yang ada pada  partograf\r\n\r\nMasukan:', 1, '2026-05-05 03:03:46', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (97, 18, 114, 382, '4b16ebc863cefdcbe0276b85d66f55ed', 'Zahra Sinta Dewi', '123170191', 'Kelebihan :\r\nsuara terdengar jelas meskipun agak lirih\r\nKekurangan :\r\nmekanisme yang menginduksi dijelaskan dengan tidak tepat, tidak menjelaskan penurunan fungsi plasenta, dll\r\nkomponen partograf kondisi janin dijelaskan lengkap, kondisi ibu hanya menjelaskan tekanan darah dan suhu tubuh. kemajuan persalinan juga tidak lengkap\r\nMasukan:\r\nbelajar lagi yaaa', 1, '2026-05-05 03:03:47', '2026-05-06 07:05:11');
