INSERT INTO `ofeedbacks` VALUES (99, 18, 119, 428, '69628c7f35c23b1e6f9fe9281a2ac92f', 'Mauliano Hastien', '123170087', 'Kelebihan :\r\nno 1 dijawab cukup relevan, namun blm lengkap\r\nno 2 terdapat minimal 1 poin untuk mewakili komponen\r\nKekurangan :\r\n\r\nMasukan:', 1, '2026-05-05 03:03:56', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (100, 18, 128, 511, 'd9f96a4b15033416de1d22c361039d6a', 'Muhamad Alfarel Chandra Pratama', '123170094', 'Kelebihan :\r\n- menyebutkan tugas 2 \r\n\r\nKekurangan :\r\n- tugas 2 : untuk masing2 point nya : ada yg kurang disebutkan nya. lengkapi yaa!!\r\n- tugas 1 : kurang lengkap yaa de. \r\n\r\nMasukan:\r\n- lengkapi lagi dan belajar lagi yaa de !! \r\n - baca baik2 tugasnya yaa dan pahami apa yg dimaksud soalnya yaaa', 1, '2026-05-05 03:03:56', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (101, 18, 122, 456, '49ae4a38808ff5be02c815ffd44a5fb8', 'Muhammad Fikri Rizal Aryanto', '123170104', 'Kelebihan :\r\nmenjelaskan tugas no 2 dengan baik\r\n\r\nKekurangan :\r\nno 1 kurang lengkap \r\n\r\nMasukan:\r\nbelajar lagi yaa de', 1, '2026-05-05 03:03:58', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (102, 18, 121, 447, 'e97f497216efff053e78d808206a7526', 'Muhammad Alfi Syahrin', '123170100', 'Kelebihan :\r\n- Persalinan dimulai dengan timbulnya his dan keluarnya lendir yang disertai darah\r\n- Menjelaskan komponen dari partograf walaupun kurang lengkap \r\n\r\nKekurangan :\r\n- Menjelaskan mekanisme yang menginduksi proses pada kasus: kontraksi kehamilan pada kala I, mules karena bayi menekan uterus dan serviks (?) mengeluarkan oksitosin dan prostaglandin\r\n- Menjelaskan kala (?) buat apa\r\n- Menyebutkan tanda kehamilan normal (?) buat apa\r\nmenjelas\r\n- Menjelaskan komponen dari partograf untuk menilai kemajuan persalinan : DJJ, his, pembukaan, penipisan serviks, penurunan kepala (Hodge), ibu : TD, suhu, RR, nadi\r\n\r\nMasukan:\r\n- Yang ditanyakan mengenai apa yang menginduksi kejadian pada kasus, sehingga seharusnya diawali dari penurunan fungsi plasenta sehingga terjadi penurunan scr mendadak kadar progesteron dan estrogen\r\n- Sebaiknya dalam menjelaskan komponen dari partograf spy lebih memudahkan dan sistematis maka dikelompokkan berdasarkan Kondisi Janin, Kemajuan Persalinan, Kondisi Ibu', 1, '2026-05-05 03:04:12', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (103, 18, 123, 466, '6b0eae96785f2eeec415928dc40bc0c2', 'Nabil Muhammad Faiq Abiyyu', '123170114', 'Kelebihan :\r\n\r\nKekurangan :\r\ntugas 1 :\r\ntugasnya diminta untuk menjelaskan bagaimana mekanisme proses yang terjadi pada kasus, prosesnya ya. bagaimana keterlibatan plasenta? bagaimana hormon-hormonnya kemudian menyebabkan apa? apa yang tejadi pada ganglion nya. apa yang terjadi pada otot-otot uterus nya. Penjelasan yang dijelaskan masih kurang\r\n\r\ntugas 2\r\nkomponen partograf ada apa saja itu yang dijelaskan. setiap berapa lama di cek nya\r\n\r\nMasukan:\r\n- belajar lagi yang baik dan benar\r\n- saat ujian usahakan fokus pada tugas ujiannya', 1, '2026-05-05 03:04:14', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (104, 18, 125, 483, '54b43135ed37b24c2cce8e8f99e6785f', 'M. Alfi Hasan Humaedi', '123170082', 'Kelebihan :\r\n\r\nKekurangan :\r\n\r\nMasukan:tepat', 1, '2026-05-05 03:04:14', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (105, 18, 120, 437, '3ff4d2bec0a2e0a8ef47848117139f4c', 'Muhammad Zidan Putra Al-fachri', '123170109', 'Kelebihan :Sudah memulai dengan percaya diri\r\n\r\nKekurangan : \r\n1. Penjelasan tidak tepat, tidak lengkap dan tidak sistematis. \r\n2. Peserta belum mampu mengenali apa yang menjadi pertanyaan pada skenario. Biasakan membaca soal dengan baik, sehingga bisa faham apa yang harus dijawab nantinya. \r\n3. Penjelasan partograf tidak sistematis, tdk lengkap, tidak tepat. HArusnya dimulai dari penjelasan 3 komponen besarnya dahulu, baru masing2 dijelaskan poin2nya. \r\n\r\nMasukan:Belajar lagi ya Zidan...', 1, '2026-05-05 03:04:21', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (106, 18, 113, 373, 'a9a9731ec49d51c00cd7bf2efa4b5bf4', 'Zian Fadilah', '123170195', 'Kelebihan : pemahaman materi baik\r\n\r\nKekurangan : pemahaman soal gak baik jd jawaban salah \r\n\r\nMasukan: pemahaman materi baik tapi soal harus dipahami apa yang ditanya yg dijawab, jangan menjelaskan kemana2 jangan menjelaskan yang tidak diminta disoal krn meskipun penjelasannya panjang n tepat klo isinya tidak menjawab apa yg ditanyakan disoal nilainya gak bagus', 1, '2026-05-05 03:04:23', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (107, 18, 118, 418, 'b8de1c1abfcb9f7006fa66ebc826322e', 'Marina Pasma Helsinki', '123170085', 'Kelebihan :\r\n\r\nKekurangan : tugas 1 dan 2 tidak lengkap\r\n\r\nMasukan:', 1, '2026-05-05 03:04:26', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (108, 18, 127, 501, '5c0d955068a5ebd0d01df572da139d96', 'Maulana Galih Shandika', '123170086', 'Kelebihan :\r\npenjelasan cukup baik untuk mekanisme persalinan\r\n\r\nKekurangan :\r\nmasih kurang lengkap sedikit apa lagi yang dinilai dari ibu\r\n\r\nMasukan:\r\nbanyak belajar dan baca lagi ya\r\ndifahami soalnya baik2\r\nsemangat selalu', 1, '2026-05-05 03:04:44', '2026-05-06 07:05:11');
