INSERT INTO `ofeedbacks` VALUES (110, 18, 121, 448, '7f3305acd0b222dab5808ee88b1d0b6e', 'Muhammad Arya Sejati', '123170102', 'Kelebihan :\r\n- Diagnosis : Inkompatibilitas ABO \r\n- Penentuan dasar diagnosis : Ikterus, lemas, penurunan refleks hisap, PF, hasil lab, golongan darah ibu dan anak\r\n- Menjelaskan antigen dan antibodi dari golongan darah\r\n- Patofisiologi: dari faktor resiko, antibodi menyerang, aglutinasi, hemolisis, peningkatan bilirubin\r\n- Manifestasi klinis yang muncul\r\n\r\nKekurangan :\r\n-\r\n\r\nMasukan:\r\n- Pertahankan, sudah baik', 1, '2026-05-05 03:15:23', '2026-05-06 07:05:11');
