INSERT INTO `ofeedbacks` VALUES (113, 18, 122, 457, 'c6e7b2ae598685f5c52346f6a545caee', 'Rafi Putra Prasetyo', '123170138', 'Kelebihan :\r\ntugas 1 sdh dijelaskan dengan sistematis\r\ntugas 2 sdh dijelaskan dengan baik dan cukup detail\r\n\r\nKekurangan :\r\n-\r\n\r\nMasukan:\r\npertahankan', 1, '2026-05-05 03:15:49', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (114, 18, 128, 512, '8e1f248252a6a4e6593c88d1ba2ea87b', 'Muhammad Rakha Habibie', '123170108', 'Kelebihan :\r\n- tugas no 1 sudah menjelaskan cukup baik \r\n- tugas 2 cukup baik penjelasannya, ada beberaqpa point yg kurang lengkap nanti dilengkapi lg yaa\r\n\r\nKekurangan :\r\n\r\nMasukan:\r\n- tingkatkan lagi yaa de belajarnya, goodjob ! :))', 1, '2026-05-05 03:18:10', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (115, 18, 115, 392, '272059b9f3c0ab68b0e63976eed298b0', 'Laela Safitri', '123170079', 'Kelebihan :\r\ndiagnosis tepat\r\nKekurangan :\r\n1. dasar diagnosis tidak lengkap\r\n2. tepat namun tidak lengkap, tau etiologinya namun reaksinya jalan nya tidak tau mengapa sampai terjadi\r\nMasukan:\r\ndasar diagnosis itu dimulai dari anamnesis, PF,PF<PP--> jelaskan dengan spesifik', 1, '2026-05-05 03:18:18', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (116, 18, 113, 374, 'dcbdffdbb15f773aa72b2d0956f3b24b', 'Riska Gusteresa Lestari', '123170149', 'Kelebihan : pemahaman materi baik, tugas 1 n 2 baik\r\n\r\nKekurangan : nilai normal pemeriksaan penunjang/lab\r\n\r\nMasukan: pemahaman materi sudah baik tapi nilai normal lab gatau nanti baca lagi ya nilai normal itu penting untuk diagnosis', 1, '2026-05-05 03:19:17', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (117, 18, 126, 493, '8174a6250fad1de8e4e786933c65c7a0', 'Raditia Molana Majid', '123170136', 'Kelebihan :\r\nMahasiswa mampu menentukan diagnosis kerja disertai dengan dasar diagnosis  lengkap \r\nMahasiswa mampu menjelaskan  patomekanisme diagnosis kerja\r\n\r\nKekurangan :\r\n\r\nMasukan:', 1, '2026-05-05 03:19:21', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (118, 18, 116, 401, 'd837ec109bee7dadfb748cf5313aa607', 'Lugina Maeranti Utami', '123170081', 'Kelebihan :\r\n\r\nKekurangan :\r\ntugas no 2 kurang lengkap \r\n\r\nMasukan:', 1, '2026-05-05 03:19:22', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (119, 18, 114, 383, '0cc860c83e80103bf6de95d8237fbaab', 'Reihana Assyfa Rahma', '123170145', 'Kelebihan :\r\nmenuliskan yang dijelaskan di papan tulis\r\nsuara cukup jelas\r\ndiagnosis cukup baik\r\nKekurangan :\r\npatofisiologi cukup baik namun manifestasi klinis hanya menjelaskan ikterik saja\r\nMasukan:\r\nsecara keseluruhan cukup baik', 1, '2026-05-05 03:19:24', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (120, 18, 112, 365, 'fbd890717933de328f4c1cc628b40b55', 'Rizki Akbar Prayoga', '123170153', 'Feedback:\r\nSoal no. 1. diagnosis serta dasar diagnosis sudah tepat\r\n              2. sudah menjelaskan patofisiologi terjadinya kasus tersebut dihubungkan dengan faktor resiko dan manifestasi klinis dengan tepat, namun kurang lengkap\r\n\r\n Tetap semangat belajar!', 1, '2026-05-05 03:19:26', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (121, 18, 124, 475, '3d6511adc69af86c2445720e3c15afb1', 'Krisna Maulana', '123170078', 'Kelebihan :\r\n\r\nKekurangan :\r\ntugas 1 : kurang menjelaskan penegakan diagnosis pada penunjang, Hb menurun dan rhesus positif \r\ntugas 2 : manifestasi klinis kurang menyebutkan anemia \r\n\r\nMasukan:', 1, '2026-05-05 03:19:33', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (122, 18, 127, 502, 'f6e3ec4d258338d64db56cb3e59f07bb', 'Maya Fahira Handayani', '123170088', 'Kelebihan :\r\n\r\nKekurangan :\r\npenjelasan patomekanisme masih belum lengkap\r\n\r\nMasukan:\r\nbanyak belajar dan baca lagi ya\r\nsemangat selalu', 1, '2026-05-05 03:19:36', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (123, 18, 123, 467, 'dd40bd03e8b587871a7e58a1da1721cd', 'Rozaanah Aliya Prawoto', '123170154', 'Kelebihan :\r\ntugas 1 \r\ncukup baik\r\n\r\nKekurangan :\r\ntugas 2\r\npenjelasan patomekanisme yang dijelaskan kurang tepat. golongan darah nya beda, ibu punya antiboidi a dan b terus antibodi nya ngapain? apa yang hemolisis? lalu menyebabkan apa hemolisis nya? penjelasannya harus tepat dan lengkap ya\r\n\r\nMasukan:\r\n- baca dan belajar lagi yang baik ya', 1, '2026-05-05 03:19:37', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (124, 18, 119, 429, '5e9a17260fa277dd60341f8b593798cd', 'Muhamad Daffaa An-najwan', '123170095', 'Kelebihan :jjawaban baik dan lengkap\r\nKekurangan :\r\n\r\nMasukan:', 1, '2026-05-05 03:19:50', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (125, 18, 120, 438, '93ef08667ef521faab563e5212266a6d', 'Siti Sopiyani', '123170167', 'Kelebihan :Sudah memulai dengan percaya diri\r\n\r\nKekurangan : \r\n1. Penjelasan ada yang tidak tepat, tdk lengkap dan tidak sistematis. \r\n2. Interpretasi data beberapa keliru. HR 140x/menit : normal???, RR : 45x/menit : normal???\r\n3. Penjelasan patomekanisme belum tepat dan belum sistematis. \r\n\r\nMasukan:Belajar lagi ya Siti', 1, '2026-05-05 03:20:03', '2026-05-06 07:05:11');
