INSERT INTO `ofeedbacks` VALUES (129, 18, 112, 366, '8945ec9d6440ce8a0d9f1408d3eee1e0', 'Sabilly Herlambang', '123170155', 'Feedback:\r\nSoal no. 1.  sudah mampu menjelaskan mekanisme secara tepat, namun kurang lengkap\r\n              2. sudah mampu menjelaskan tatalaksana secara tepat, namun kurang lengkap\r\n\r\n Tetap semangat belajar!', 1, '2026-05-05 03:34:41', '2026-05-06 07:05:11');
