INSERT INTO `ofeedbacks` VALUES (132, 18, 127, 503, '707af764ac06086137b7a228e6f2d14a', 'Riverza Marviansyah', '123170150', 'Kelebihan :\r\n\r\nKekurangan :\r\npenjelasan untuk tatalaksana nya masih belum lengkap\r\n\r\nMasukan:\r\nbanyak belajar dan baca lagi ya\r\ndifahami soalnya baik2\r\nsemangat selalu', 1, '2026-05-05 03:35:02', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (133, 18, 113, 375, 'e649756b6ef4c230ec8314383e52bd00', 'Riyana Wulan Miranti', '123170151', 'Kelebihan :\r\n\r\nKekurangan : tugas 1  kurang tepat, tugas 2 tidak lengkap poin penting tidak disebutkan\r\n\r\nMasukan: etika diperhatikan, jelaskan sesuai dg soalnya gak perlu jelasin hal2 lain yg tidak diminta disoal', 1, '2026-05-05 03:35:02', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (134, 18, 119, 430, '973192e38dc34139ddd6fce62371a2ad', 'Tri Nur Anisa', '123170177', 'Kelebihan :\r\nmrkanisme cukup baik, namun belum lengkap\r\n\r\nKekurangan :\r\ndosis mgso4 nya tidak tepat, gram ya bukan mg\r\n\r\nMasukan:', 1, '2026-05-05 03:35:03', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (135, 18, 121, 449, '4ec46a0d215aa02d0caffe8c5b6a4652', 'Nur Rizkya Anggraini', '123170128', 'Kelebihan :\r\n- Penentuan diagnosis Pre elampsia berat dengan dasar diagnosis\r\n\r\nKekurangan :\r\n- Menjelaskan mekanisme pada manifestasi klinis spt nyeri kepala, mual\r\n- Menjelaskan tatalaksana: nifedipine, metildopa, pct sebagai antinyeri\r\n\r\nMasukan:\r\n- Menjelaskan mekanisme kelainan pada kasus, bukan hanya dikaitkan dengan manifestasi klinis. Diawali patomekanisme pada kehamilan diawali gangguan remodeling arteri spiralis yang menyebabkan perfusi plasenta tidak adekuat dan berujung pada hipoksia plasenta, dst. \r\n- Tatalaksana dijabarkan dan dijelaskan dari Stabilisasi awal, Pencegahan kejang, Terapi antihipertensi yang diberikan beserta dosis dan indikasinya', 1, '2026-05-05 03:35:05', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (136, 18, 126, 494, '2befbd7b6f10414cb299138e776f9673', 'Rasti Ambar Nurfadilah', '123170144', 'Kelebihan :\r\n\r\n\r\nKekurangan :\r\nMahasiswa menjelaskan mekanismetidak lengkap dan tidak sistematis\r\nMahasiswa belum mampu menjelaskan tatalaksana secara tepat dan lengkap.\r\n\r\nMasukan:', 1, '2026-05-05 03:35:06', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (137, 18, 116, 402, 'cc08bc38abdb155ef03639a697b9aeac', 'M. Hibban Raiisa Abdurrosyiid Ardifansyah', '123170083', 'Kelebihan :\r\n\r\nKekurangan :\r\ntugas no 2 tdk lengkap: identifikasi dulu permasalahan pasien scr keseluruhan .\r\n\r\nMasukan:', 1, '2026-05-05 03:35:10', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (138, 18, 115, 393, '2b1908565b790b38196c9e3f7dd925cc', 'Syaima Najiha Kurniawati', '123170171', 'Kelebihan :\r\n\r\nKekurangan :\r\n1. tidak dapat menjelaskan mekanisme\r\n2. tatalkasana harus mengena ini adalah kasus kegawatdaruratan jadi tatalksanakan harus spesifik bukan hanya manifestasi klinisnya saja\r\nMasukan:', 1, '2026-05-05 03:35:18', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (139, 18, 124, 476, 'e08bf52d29a47ecfe722b9cc5e4d3ca3', 'Nizar Athaillah Rophaaisyi', '123170124', 'Kelebihan :\r\n\r\nKekurangan :\r\npenjelasan mengenai mekanisme tidak tepat \r\npenjelasan mengenai tatalaksana tidak tepat \r\n\r\nMasukan:', 1, '2026-05-05 03:35:24', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (140, 18, 122, 458, '1ffcfce07e04d3ce340cf1785efd5626', 'Raihanah Jinan Ulya Ramadhani', '123170140', 'Kelebihan :\r\n\r\n\r\nKekurangan :\r\nbedakan mekanisme dan penegakan diagnosis\r\ntugas 1 kurang detail\r\n\r\nMasukan:\r\nbelajar lagi ya de leboh detail dan sistematis', 1, '2026-05-05 03:35:24', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (141, 18, 128, 513, '0d0501e5b63fea31a12a73433ce725fd', 'Nasywa Rizkia Nurrachmy', '123170116', 'Kelebihan :\r\n\r\nKekurangan :\r\n- tugas no. 1 dibaca lagi yaaa de, pahami kasusnya dengan baik. pasien dlm kondisi apa??\r\n- tugas no. 2 juga berhubungan dengan kondisi di tugas 1 jd baca lagi dgn teliti kasusnya !!\r\n\r\nMasukan:\r\n- lebih teliti lagi untuk membaca kasus nya, pahami dgn baik maksud tugasnya!!\r\n- semangat belajar lg yaaa de !! :))', 1, '2026-05-05 03:35:34', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (142, 18, 120, 439, '7d95760ec96a06b315687ad2c0ed7e77', 'Salma Mumtaz', '123170161', 'Kelebihan :Sudah memulai dengan percaya diri\r\n\r\nKekurangan : \r\n1. Penjelasan ada yang kurang detail.\r\n2. Tatalaksana belum lengkap, tidak sistematis dan menyeluruh, peserta masih hanya menyampaikan obat2an saja. Tatalaksana itu jelas, apa yang akan kita lakukan terhadap pasien tersebut, rawat jalan atau rawat inapkah? Jika rawat inap, dirawat di mana? Apa saja yang harus dikondisikan?? Apa yg di follow up? INTINYA HARUS LENGKAP. Bukan cuma OBAT!!!\r\n\r\nMasukan:Belajar lagi ya Salma.', 1, '2026-05-05 03:35:38', '2026-05-06 07:05:11');
