INSERT INTO `ofeedbacks` VALUES (150, 18, 122, 459, '3aeebd2349c05eab9c176bf286803d57', 'Syafana Delviana Pritama Syahrani', '123170170', 'Kelebihan :\r\ntugas 1 dan 2 sudah dijelaskan dgn cukup baik\r\n\r\nKekurangan :\r\ntugas no 1 masih bisa sedikit lebih detail\r\n\r\nMasukan:\r\nPertahankan ya de', 1, '2026-05-05 03:50:35', '2026-05-06 07:05:11');
