INSERT INTO `ofeedbacks` VALUES (157, 18, 121, 450, '7b028a27d933eb64a4577f9d681388de', 'Prabu Anom Pramudinto', '123170132', 'Kelebihan :\r\n\r\nKekurangan :\r\n- Menjelaskan menyebutkan gejala dan tanda pada kasus seperti mual muntah, perut begah, payudara bengkak, BAK >>, test pack (+) namun tidak menjelaskan dengan detail dan lengkap untuk mekanismenya\r\n- Peningkatan hormon estrogen dan progesteron - sehingga dinding endometrium tidak meluruh\r\n- Menjelaskan fertilisasi dari proses sperma masuk hingga perkembangan ekto, meso dan endoderm\r\n\r\nMasukan:\r\n- Menjelaskan masing-masing mekanisme munculnya gejala dan tanda: Pengaruh hormon kehamilan, Perubahan organ target, Manifestasi Klinis (tanda tidak pasti dan tanda pasti kehamilan)\r\n- Proses fertilisasi sebaiknya dijelaskan dari proses Ovulasi hingga Fusi pronuclei', 1, '2026-05-05 03:50:55', '2026-05-06 07:05:11');
