INSERT INTO `ofeedbacks` VALUES (159, 18, 120, 440, 'dbb2d494cbcfd6472a250060fbc0a02d', 'Nabil Febriansyah', '123170113', 'Kelebihan :Sudah memulai dengan percaya diri\r\n\r\nKekurangan : \r\n1. Penjelasan sebagian tidak tepat, tidak lengkap dan tidak sistematis. \r\n2. Pastikan menjelaskan hal yang memang ditanyakan.\r\n\r\nMasukan:Biasakan menuliskan hal2 penting yang akan dijelaskan terlebih dahulu. Belajar lagi ya Nabil...', 1, '2026-05-05 03:51:16', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (160, 18, 127, 504, 'a2470f2e3741691e7af897243ef8547f', 'Riyardi Jaya Bimantoro', '123170152', 'Kelebihan :\r\npenjelasan untuk tugas 1 cukup\r\n\r\nKekurangan :\r\npenejlasan fertilisasi masih sedikit lagi lengkap\r\n\r\nMasukan:\r\nbanyak belajar dan baca lagi ya\r\nsemangat selalu', 1, '2026-05-05 03:51:21', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (161, 18, 113, 376, '7498615126a1ec1f0cf1fc987bcd5b38', 'Muhammad Daffa Ashshiddiq', '123170103', 'Kelebihan :pemahaman materi  baik\r\n\r\nKekurangan :nama2 prosesnya dan tanda pasti kehamilan\r\n\r\nMasukan: sudah cukup baik, pemahaman materi bagus penjelasan lengkap tapi nanti belajar lagi nama2 prosesnya dan tanda pasti kehamilan dan tanda tidak pasti kehamilan', 1, '2026-05-05 03:52:56', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (162, 18, 127, 505, 'acc586130217b347d5204c3afcef26d4', 'Shafa Alya Salsabila', '123170164', 'Kelebihan :\r\n\r\nKekurangan :\r\ndiagnosisnya dan dasar diagnosisnya masih belum tepat \r\nupaya pencegahan berkaitan dengan diagnosis utamanya sehingga masih belum tepat dan lengkap\r\n\r\nMasukan:\r\nbanyak belajar dan baca lagi ya\r\ndifahami soalnya baik2\r\nsemangat selalu', 1, '2026-05-05 04:06:16', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (163, 18, 118, 422, 'f95ea94a4c4294b63706dfe5887b19fa', 'Nizar Rheivani Ramadhina Supriadi', '123170125', 'Kelebihan :\r\n\r\nKekurangan : tugs 1 diagnosis tidak tepat baca lagi ya tugas 2 blm lengkap pencegahan itu kan bs dari ibu, bayi, pasangan suami istri yang baru menikah, komunitas, dll\r\n\r\nMasukan:', 1, '2026-05-05 04:06:18', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (164, 18, 128, 515, '5a945f7ddc7c4022126f751fd92a347e', 'Sigmund Sheehane Divandra', '123170166', 'Kelebihan :\r\n- tugas 1 dn 2 menjelaskan dgn cukup baik \r\n\r\nKekurangan :\r\n- lengkapi lagi yg masih kurang utnuk pencegahannya \r\n\r\nMasukan:\r\n- tingkatkan lg yaa belajarnya, semangatt !! :))', 1, '2026-05-05 04:06:27', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (165, 18, 120, 441, '605581b9cbe24db5f033d2bc8f7bd306', 'Najmi Ashfilia Azzahro', '123170115', 'Kelebihan :Sudah memulai dengan percaya diri\r\n\r\nKekurangan : \r\n1. Penjelasan tidak tepat, tdk lengkap dan kurang sistematis.\r\n2. Peserta masih ragu2 terkait diagnosis kasus. \r\n3. Penjelasan pencegahan kurang lengkap. \r\n\r\nMasukan:Belajar lagi ya Najmi', 1, '2026-05-05 04:06:33', '2026-05-06 07:05:11');
INSERT INTO `ofeedbacks` VALUES (166, 17, 106, 131, 'c772b889b2fd61238246dfda95817109', 'Nazril Tsaqif Assyamil', '123170119', 'Feedback\r\nSoal No. 1. Diagnosis belum tepat\r\n               2. Sudah menjelaskan patofisiologi dihubungkan dengan manifestasi klinis, namun belum tepat dan lengkap\r\n\r\nTetap semangat belajar!', 1, '2026-05-06 01:32:23', '2026-05-06 07:12:08');
INSERT INTO `ofeedbacks` VALUES (167, 17, 92, 1, '606579477d7e764fe4902e533765ee02', 'Sri Tanjung Mayang Arum', '124170156', 'Kelebihan :-\r\n\r\nKekurangan :\r\nTugas 1: mahasiswa tidak mampu menjawab tugas  dengan tepat\r\nTugas 2: mahasiswa tidak mampu menjawab tugas  dengan tepat \r\n\r\nMasukan:\r\nBelajar lagi mengenai kasus dengan detail dan analisis kasus lebih dalam lagi agar jawaban tepat!\r\nJangan ragu-ragu dan bingung yaaa!', 1, '2026-05-06 01:32:23', '2026-05-06 07:12:08');
INSERT INTO `ofeedbacks` VALUES (168, 17, 110, 167, '860834e35b70e8ba18982dffc237832b', 'Galuh Pareza Firdaus', '122170065', 'Kelebihan :\r\n\r\nKekurangan :\r\nbaca lebih teliti ya de soalnya..\r\nnomor 1, jawabannya masih salah.. ekg tidak normal, gambaran apa itu??\r\nnomor 2, saat nomor 1 salah, patof yg dijelaskan juga salah (bukan dx nya)\r\n\r\nMasukan:\r\nsemangat ya dek belajarnya', 1, '2026-05-06 01:32:24', '2026-05-06 07:12:08');
INSERT INTO `ofeedbacks` VALUES (169, 17, 98, 58, '077e31049fbe8ad2e2d77d02b8825a74', 'Muhammad Hanif Izzul Haq', '123170105', 'Kelebihan :\r\n\r\nKekurangan :\r\ntugas 1 : diagnosis tidak tepat, dasar diagnosis tidak terjawab\r\ntugas 2 : tidak terjawab\r\n\r\nMasukan:\r\nbelajar lagi ya ...', 1, '2026-05-06 01:32:27', '2026-05-06 07:12:08');
INSERT INTO `ofeedbacks` VALUES (170, 17, 101, 85, 'e65fc51ad93fe764548552889cdc40bf', 'Zakaria Nadhom Adzkiya', '123170192', 'Kelebihan :\r\n\r\nKekurangan :\r\n1. diagnosis salah sehingga dasar dx tidak sesuai\r\n2.diagnosis salah sehingga patof tidak sesuai\r\nMasukan:', 1, '2026-05-06 01:32:28', '2026-05-06 07:12:08');
INSERT INTO `ofeedbacks` VALUES (171, 17, 100, 76, '60ce217292202614c5113be907cd6511', 'Putri Nabila', '123170134', 'Kelebihan :\r\n\r\nKekurangan :\r\n- tugas 1 dan 2 tidak tepat yaaa dee \r\n\r\nMasukan:\r\n- belajar lagii yaaa de!!\r\n- baca skenario kasus dgn teliti lagi dan pahami dg baik !!', 1, '2026-05-06 01:32:29', '2026-05-06 07:12:08');
INSERT INTO `ofeedbacks` VALUES (172, 17, 94, 20, 'a98a08ca209852b0f26ee5b8c84b61ac', 'Salsa Asyriyah', '124170142', 'Kelebihan : berusaha menghubungkan patofisiologi dengan manifestasi klinis.\r\n\r\nKekurangan : \r\n- diagnosis tidak tepat, tidak sesuai dengan dasar diagnosis yang disebutkan.\r\n- patofisiologi yang dijelaskan tidak tepat, dan kurang terkait dengan manifestasi klinis yang dijelaskan.\r\n\r\nMasukan: perhatikan tanda dan gejala, baru menentukan diagnosis yang tepat. Namun, pada waktu menjelaskan dimulai dengan diagnosis dan dilanjutkan data pendukung,', 1, '2026-05-06 01:32:31', '2026-05-06 07:12:08');
INSERT INTO `ofeedbacks` VALUES (173, 17, 97, 48, '8a4074c74a2c7eeb5174ef3c45f5ca01', 'Khalid Ibnu Thoriq', '123170077', 'Kelebihan :\r\n\r\nKekurangan :\r\ntugas 1\r\ndiagnosis nya tidak tepat, dasar diaggnosis juga kurang sesuai jadinya\r\n\r\ntugas 2\r\npatofisiologi yang dijelaskan tidak sesuai ya, berbeda dengan yang ada di skenario kasus, belajar lagi yang baik ya. \r\n\r\nMasukan:\r\n- skenario nya coba dibaca pelan-pelan ya, dibaca dengan teliti\r\n- belajar lagi yang baik untuk ujiannya ya', 1, '2026-05-06 01:32:32', '2026-05-06 07:12:08');
INSERT INTO `ofeedbacks` VALUES (174, 17, 105, 122, '435526edbd44b310e378ea681ab2649e', 'Muhammad Rafie Aulia', '122170123', 'Kelebihan :\r\n\r\nKekurangan : Diagnosis tidak tepat, dasar diagnosis tidak lengkap. \r\nPatofisiologi tidak relevan krn diagnosis tidak tepat\r\nMasukan:\r\nbelajar lagi', 1, '2026-05-06 01:32:37', '2026-05-06 07:12:08');
INSERT INTO `ofeedbacks` VALUES (175, 17, 95, 29, 'd85ca0c522c0364b270e76af7101375a', 'Hawa Salsah Billah', '122170081', 'Kelebihan :\r\n\r\nKekurangan : mahasiswa tidak dapat menentukan diagnosis dan dasar diagnosis yang tepat, tidak dapat menjelaskan patofisiologi\r\n\r\nMasukan: belajar lagi ya de, teliti baca soal', 1, '2026-05-06 01:32:37', '2026-05-06 07:12:08');
INSERT INTO `ofeedbacks` VALUES (176, 17, 109, 160, 'b7f836a57d1626d5e8a34e9b46c34edd', 'Alifvia Syifa Nur Maisaan Budy', '124170010', 'Kelebihan :\r\nPembawaan yang tenang \r\n\r\n\r\nKekurangan :\r\nTugas 1 : masih belum tepat\r\n\r\nTugas 2: masih belum tepat\r\n\r\nMasukan:\r\nBelajar lagi\r\nBaca baik-baik kasusnya dan pahami', 1, '2026-05-06 01:32:39', '2026-05-06 07:12:08');
INSERT INTO `ofeedbacks` VALUES (177, 17, 99, 67, 'cbb6c4e4a2bf8f8fed187c97250108db', 'Aura Keyza Salsabila', '123170024', 'Kelebihan :\r\n\r\nKekurangan :\r\ndx tidak tepat\r\npatfis belum mampu menjelaskan, patfisnya tidak tepat semua karena dxnya tidak tepat\r\n\r\nMasukan:\r\nbelajar lagi cara menentukan dx dasarnya apa', 1, '2026-05-06 01:32:44', '2026-05-06 07:12:08');
INSERT INTO `ofeedbacks` VALUES (178, 17, 102, 95, 'f9ab7b2058ea089b645f792661982aa5', 'Fajar Dermawan', '123170045', 'Kelebihan : sudah tenang dan mencoba menjawab\r\n\r\nKekurangan : tugas 1 tidak tepat pelajari kembali skenarionya lihat PF nya dengan teliti, karena diagnosis pada tuga 1 tidak tepat sehingga patomekanismenya pd tugas 2 pun tidak tepat. Patomekanisme gagal jantung pun yang dijelaskan tidak tepat contoh takipneu kok terjadi karena aliran balik?\r\n\r\nMasukan: belajar teori plus media pembelajaran yang lain seperti youtube atau atlas anatomi agar bisa tervisualisasi', 1, '2026-05-06 01:32:44', '2026-05-06 07:12:08');
INSERT INTO `ofeedbacks` VALUES (179, 17, 111, 176, '4e779f0cd9ece0077698429b188e9832', 'Syifa Dhia Khairunnisa', '123170174', 'Kelebihan :\r\n\r\nKekurangan :\r\ndiagnosis dan dasar diagnosis masih kurang tepat\r\npatofisiologi manifestasi klinis masih belum tepat dan lengkap sesuai dengan diagnosis nya\r\n\r\nMasukan:\r\ndibaca selalu baik2 soalnya yaa\r\nbanyak belajar dan baca selalu ya\r\nsemangat terus', 1, '2026-05-06 01:32:47', '2026-05-06 07:12:08');
INSERT INTO `ofeedbacks` VALUES (180, 17, 104, 113, '959feda815772cdc33199bb251fc41f4', 'Darus Phindutur', '123170030', 'Kelebihan :\r\n\r\nKekurangan :\r\n- penegakan diagnosis kurang tepat\r\n- dasar diagnosa tidak sesuai\r\n- Patfis tidak menjelaskan ke arah manifestasi klinisnya\r\n\r\nMasukan:\r\n- Melihatnya ke penguji yaa, bukan ke papan tulis\r\n- pelajari lagi penegakkan dx\r\n- Perhatikan cara presentasi, masih terlihat bingung\r\n- Semangat belajar lagi ya', 1, '2026-05-06 01:32:51', '2026-05-06 07:12:08');
INSERT INTO `ofeedbacks` VALUES (181, 17, 107, 140, '7d570857bcce1a41f6d1bef030e0d906', 'Dwi Fajar Indriani', '123170035', 'Kelebihan :\r\n- sudah PD dalam menjelaskan walau jawabannya belum tepat. \r\n\r\nKekurangan :\r\n- Diagnosis tidak benar. sehingga dasar diagnosis tidak tepat. \r\n- patofisiologi tidak tepat karena diagnosis kamu salah. \r\n\r\nMasukan:\r\n- baca soal dengan teliti dan perlahan ya.\r\n- pahami maksud setiap kalimat di kasus agar kamu paham maksud kasus ini mengrah kemana. \r\n- belajar lagi ya.', 1, '2026-05-06 01:32:51', '2026-05-06 07:12:08');
INSERT INTO `ofeedbacks` VALUES (182, 17, 103, 105, '60bbf49de5d7b05fff9f70f184db23fe', 'Hammett Kahfi Fergie Rajiv Afghani', '122170076', 'Kelebihan :\r\n\r\nKekurangan :\r\ndiagnosis tidak tepat\r\njawaban no 1 dan 2 tidak tepat\r\n\r\nMasukan:\r\nbelajar lagi', 1, '2026-05-06 01:32:57', '2026-05-06 07:12:08');
