INSERT INTO `ofeedbacks` VALUES (189, 17, 99, 68, '20f8c6129d32e6abc5b4085e32a5a074', 'Anggi Ayu Febriyanti', '123170020', 'Kelebihan :\r\n\r\nKekurangan :\r\npatfis tidak lengkap karena dx utama tidak tepat\r\nmekanisme obat belum mampu menjelaskan\r\n\r\nMasukan:\r\nbelajar lagi menentukan dxnya bagaimana\r\nbelajar cara kerja obat', 1, '2026-05-06 01:48:04', '2026-05-06 07:12:08');
