INSERT INTO `ofeedbacks` VALUES (193, 17, 95, 30, '0ad35bd5b184d8a9867ea5b12ac9a496', 'Mochamad Fadli Eka Daryana', '123170091', 'Kelebihan : \r\n\r\nKekurangan : pitting edema terjadi karena darah kurang oksigen? baca lg mekanisme backflow pd gagal jantung kanan. FR tidak tergali yg SESUAI KASUS. mekanisme kerja obat\r\n\r\nMasukan: patofisiologi lengkap mulau dari FR sesuai kasus sehingga bisa menjelaskan yg relevan dgn kasus, mekanisme tatalaksana \r\nbelajar lg', 1, '2026-05-06 01:48:17', '2026-05-06 07:12:08');
