INSERT INTO `ofeedbacks` VALUES (198, 17, 97, 50, '5c9b4433c632061d27c28d67315515a7', 'Sigit Wiranto', '124170150', 'Kelebihan :\r\n\r\nKekurangan :\r\ntugas 1\r\njelaskan patofisiologi yang sesuai dengan kasus, skenario kasus nya dibaca dengan teliti ya, lihat itu penyebab nya apa ya? jelaskan penyebab pada kasus lalu jelaskan sampai timbul manifestasi klinis yang muncul di kasus. penjelasan yang dijelaskan masih belum sesuai dengan yang ada di skenario kasus\r\n\r\ntugas 2\r\nbaelum menajwab\r\n\r\nMasukan:\r\n- skenario kasus nya dibaca dengan baik dan teliti lagi ya\r\n- belajar lagi yang baik ya de', 1, '2026-05-06 01:48:26', '2026-05-06 07:12:08');
INSERT INTO `ofeedbacks` VALUES (199, 17, 102, 96, '33079e781e5a8499eee87409c13b4f68', 'Wirda Rizki Utami Asrori', '123170186', 'Kelebihan :\r\n\r\nKekurangan : tugas 1 perhatikan seksama scenario termasuk PF nya, Riwayat pasien?tentukanm etiologi dan faktr risikonya d scenario untuk dapat menjelaskan patfis nya\r\ntugas 2 mekanisme obat yang diminta pada tugas 2 jd bukan \"untuk menurunkan tekanan darah, untuk mengurangi edema dengan retensi natrium\" tp jelaskan bagaimana obat tersebut bekerja\r\n\r\nMasukan:', 1, '2026-05-06 01:48:27', '2026-05-06 07:12:08');
INSERT INTO `ofeedbacks` VALUES (200, 17, 111, 177, 'ca9e51fb346f0cef46638a6fb1d6cdb3', 'Andini Putri Amelia', '124170014', 'Kelebihan :\r\npenjelasan terkai mekanisme kerja obat sudah cukup\r\n\r\nKekurangan :\r\npenjelasan causa di awal terkait patofisiologi gagal jantung masih belum lengkap\r\n\r\nMasukan:\r\ndibaca selalu baik2 soalnya yaa\r\nbanyak belajar dan baca selalu ya\r\nsemangat terus', 1, '2026-05-06 01:48:28', '2026-05-06 07:12:08');
INSERT INTO `ofeedbacks` VALUES (201, 17, 107, 142, '96f8d008b48ff58769ffb3a08a546e2e', 'Anhe Gustian Syabani', '124170016', 'Kelebihan :\r\n- pemilihan obat sudah tepat \r\nKekurangan :\r\n- patofisiologi masih kurang tepat karena diagnosisnya tidak tepat. kamu hanya menyebutkan gagal jantung tanpa memperhatikan EKGnya padahal hasil EKGnya sangat khas. \r\n- mekanisme kerja obatnya masih kurang penjelasannya, masih banyak yang di lewatkan alur mekanismenya. \r\n\r\nMasukan:\r\n- baca soal dengan perlahan dan teliti ya.\r\n- belajar lagi ya', 1, '2026-05-06 01:48:43', '2026-05-06 07:12:08');
INSERT INTO `ofeedbacks` VALUES (202, 17, 94, 21, 'b9031980322d063f0f6fe2d70bbb0e3b', 'Salwa Syahrianti Fajri', '124170144', 'Kelebihan : mengetahui kondisi klinis pasien\r\n\r\nKekurangan :tidak dapat mengidentifikasi penyebab dari kondisi klinis pasien pada kasus. mahasiswa menjelaskan patomekanisme yang tidak relevan dengan kasus yang disajikan, yang dijelaskan tidak sesuai dengan kasus yang sudah dideskripsikan.\r\nTugas kedua belum dijelaskan.\r\n\r\nMasukan: Fokus dengan kasus yang disajikan', 1, '2026-05-06 01:48:44', '2026-05-06 07:12:08');
INSERT INTO `ofeedbacks` VALUES (203, 17, 93, 12, '2113defd61e84a3c527f267e1f80c123', 'Zahra Adelia', '124170162', 'Kelebihan :\r\n\r\nKekurangan :\r\npatofisiologi tidak tepat\r\nmekanisme obat kurang lengkap\r\n\r\nMasukan:', 1, '2026-05-06 01:48:44', '2026-05-06 07:12:08');
