INSERT INTO `ofeedbacks` VALUES (210, 17, 94, 22, '504440472d25a80a1b655ffc1e45cd58', 'Aliya Vera', '124170011', 'Kelebihan :mengetahui kondisi klinis pasien (hampir benar)\r\n\r\nKekurangan :patomekanisme yang dijelaskan tidak sesuai dengan kasus yang disajikan., manifestasi klinis yang dijelaskan tidak tepat mekanisme timbulnya, tidak sesuai kasua yang diberikan.\r\nnadi 80x per menit --> takikardi?\r\n\r\nTatalaksana tidak tepat.\r\n\r\nMasukan:Pelajari kembali kasus di sistem kardiovaskular ya dek. kondisi klinis dan faktor yang dapat mempengaruhi, agar penjelasan kasus dapat sesuai dengan yang disajikan.', 1, '2026-05-06 02:03:43', '2026-05-06 07:12:08');
