INSERT INTO `ofeedbacks` VALUES (217, 17, 100, 78, '37cbe2d36bede6e7bed082e09993096e', 'Fadel Ahmad Yuza', '122170053', 'Kelebihan :\r\n\r\nKekurangan :\r\n- tidak menjelaskan tugas no. 1, jelaskan tugasnya bukan hanya menyebutkan manifestasi yg sdh ada  dikasus yaa de !!\r\n- tugas 2 tidak tepat \r\n\r\nMasukan:\r\n- baca tugasnya dgn baik, menjelaskan bukan menyebutkan yaa de\r\n- belajar lagi yaaa de ! semangatt!!', 1, '2026-05-06 02:03:48', '2026-05-06 07:12:08');
INSERT INTO `ofeedbacks` VALUES (218, 17, 110, 170, 'bc6684d2eb03173757455a75d3b1caa4', 'Muhammad Husni Sahbani', '124170095', 'Kelebihan :\r\n\r\nKekurangan :\r\nnomor 1, kurang lengkap\r\nnomor 2 kurang lengkap\r\n\r\nMasukan:\r\nbaca lebih teliti lg soal-soalnya, jgn lupa pahami kriteria diagnosis masing2 penyakit', 1, '2026-05-06 02:04:00', '2026-05-06 07:12:08');
INSERT INTO `ofeedbacks` VALUES (219, 17, 92, 3, 'f48114504ff4df2a308ba71fb3cbd3fb', 'Sarah Hamidah', '124170146', 'Kelebihan : \r\nTugas 1: mahasiswa mampu menjawab tugas  dengan tepat namun tidak lengkap dan tidak dijelaskan dari mekanisme awal.\r\n\r\nKekurangan :\r\nTugas 2: mahasiswa mampu menjawab tugas  dengan tepat namun tidak lengkap hanya secara umum saja.\r\n\r\nMasukan:\r\nBelajar lagi mengenai kasus dengan detail dan analisis kasus lebih dalam lagi agar jawaban tepat dan lengkap!', 1, '2026-05-06 02:04:02', '2026-05-06 07:12:08');
