INSERT INTO `ofeedbacks` VALUES (289, 17, 110, 175, '97c0063b3ca5f260516f9f296ecb18d6', 'Rafli Kusuma Ramdhani', '124170127', 'Kelebihan :\r\n\r\nKekurangan :\r\nnomor 1: baik namun kurang lengkap, tidak usah menyebut semua nya, sebutkan saja yg kira2 menunjang/ menjadi dasar diagnosis nya\r\nnomor 2: tidak lengkap, edema tungkai? edema paru? memang ada di lembar soal?\r\n\r\nMasukan:\r\nbaca dengan teliti saat diberikan waktu membaca soal, agar saat menjawab waktunya tepat, tidak baca-baca lg soalnya', 1, '2026-05-06 03:06:13', '2026-05-06 07:12:08');
