INSERT INTO `ofeedbacks` VALUES (291, 17, 92, 7, '8d154827a29d017d210cd0000d16a66e', 'Indah Permata Dewi', '124170062', 'Kelebihan : -\r\n\r\nKekurangan :\r\nTugas 1: mahasiswa tidak mampu menjawab tugas dengan tepat.\r\nTugas 2: mahasiswa tidak mampu menjawab tugas dengan tepat.\r\nMasukan:\r\nBelajar lagi mengenai kasus dengan detail dan analisis kasus lebih dalam lagi agar jawaban tepat dan lengkap!\r\nBelajar lagi cara interpretasi PF dan terutama PP (ekg,rontgen,dll)!\r\nMasih banyak yang perlu dipelajari yaa', 1, '2026-05-06 03:06:14', '2026-05-06 07:12:08');
