INSERT INTO `ofeedbacks` VALUES (332, 17, 92, 9, '5f86284f4ad66efd4202473d02b64775', 'Rahma Nur Amallia', '124170128', 'Kelebihan :\r\nTugas 1: mahasiswa mampu menjawab tugas dengan tepat, namun tidak lengkap.\r\n\r\nKekurangan :\r\nTugas 2: mahasiswa  mampu menjawab tugas dengan tepat namun tidak lengkap.(hanya 2 obat itupun kurang lengkap)\r\n\r\nMasukan:\r\nBelajar lagi mengenai kasus dengan detail dan analisis kasus lebih dalam lagi agar jawaban tepat dan lengkap!\r\nBelajar lagi terkait obat-obatan dengan lengkap!', 1, '2026-05-06 03:37:49', '2026-05-06 07:12:08');
