INSERT INTO `ofeedbacks` VALUES (612, 20, 156, 673, 'f9ab7b2058ea089b645f792661982aa5', 'Fajar Dermawan', '123170045', 'Kelebihan :\r\n\r\nKekurangan :\r\n- Tidak menjelaskan dengan lengkap patofisiologi terjadinya penyakit pada kasus tersebut berdasarkan faktor risiko sampai munculnya manisfestasi klinis pada kasus\r\n- mekanisme kerja obat ISDN, furosemid kurang tepat dan lengkap\r\n\r\nMasukan:\r\n- Pelajari kembali patofisiologi hingga manifestasi klinis\r\n- Pelajari mekanisme kerja obat', 1, '2026-05-08 01:46:35', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (613, 20, 161, 722, '04ea8814bd1fc160668537ff974153c3', 'Huwaidah Uswatun Hasanah', '124170059', 'Kelebihan :\r\n\r\nKekurangan :\r\ndasar diagnosis kurang lengkap yang ekg\r\npatofisiologi kurang lengkap kurang detail\r\n\r\nMasukan:', 1, '2026-05-08 02:00:08', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (614, 20, 150, 619, '032db82894c1c2469cf5ae9884eeabec', 'Muhammad Daffa Al Huda', '124170092', 'Kelebihan :\r\ntugas 1\r\ndiagnosis dan dasar diagnosis cukup\r\n\r\nKekurangan :\r\ntugas 2\r\npenjelasan patfis nya nanti dibaca lagi ya. daro FR yang beberapa itu menyebabkan apa? bagaimana efeknya. jelaskan secara lengkap\r\n\r\nMasukan:\r\n- belajar lagi ya', 1, '2026-05-08 02:00:08', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (615, 20, 157, 682, '8d695c406d1dd8f646a67ea04f9070dc', 'Jingga Aulia Azzahra', '124170071', 'Kelebihan :\r\n\r\nKekurangan :\r\npenejalasan diagnosis dan dasar diagnosis serta patofisiolgi klinis masih belum lengkap \r\n\r\nMasukan:\r\nbanyak belajar lagi dan baca lagi selalu ya\r\nsemangat selalu', 1, '2026-05-08 02:00:09', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (616, 20, 148, 602, '83c682dd89ed83c27ed9aefdd903543b', 'Muhamad Prayoga Satria', '124170086', 'Kelebihan :\r\npembawaan yang tenang\r\n\r\nKekurangan :\r\ntugas 1 :\r\ndata yang di PF masih ada yang belum disebutkan\r\ninterpretasi data yang ada di pemeriksaan penunjang masih kurang tepat\r\n\r\ntugas 2:\r\njelaskan sesuai masalah pasien saja dhe\r\n\r\nMasukan:\r\nbaca baik-baik skenarionya ya,,baca secara detail, cari mana yang menjadi dasar diagnosis atau dengan hasil PF yang abnormal\r\npelajari lagi bagaimana menginterpretasikan hasil PP\r\npatofisiologi disesuaikan dengan masalah kasus saja ya', 1, '2026-05-08 02:00:09', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (617, 20, 156, 676, '7e07a44d013fc37019280c1369b08cd7', 'Reza Hidayat', '124170136', 'Kelebihan :\r\n- Diagnosis: VES (ventrikuler ekstrasistol) \r\n\r\nKekurangan :\r\n- Penjelasan dasar diagnosis tidak lengkap: hanya anamnesis dan EKG\r\n- Patofisiologi kurang lengkap  \r\n\r\nMasukan:\r\n- Biasakan dalam menentukan dasar diagnosis dengan dimulai dari anamnesis, PF hingga pem penunjang\r\n- Patofisiologi sebaiknya dijelaskan dari awal dengan faktor resiko dan etiologi', 1, '2026-05-08 02:00:10', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (618, 20, 159, 702, 'f207f2502a9625e2ff4daadb642af838', 'Seren Widia Renaldi', '123170163', 'Kelebihan :\r\n\r\nKekurangan :\r\ndasar dx: pada anamnesis jgn lupa lihat RPS, RPD, RPK, dan RPSos\r\nPF jantung: pelajari lagi mana yg normal dan tidak, ictu cordis kuat angkat apakah tidak normal? auskultasi vesikuler apakah tdk normal?\r\nEkg: ada peningkatan gelombang P? normalnya brpa tinggi dan lebar gelombang P?\r\npatfis: \"cafein membuat jantung berdebar\",iya kenapa bisa begitu? mekanisme nya bgmana?\r\n\r\nMasukan:\r\nsemangat belajarnya dek', 1, '2026-05-08 02:00:10', '2026-05-09 01:36:25');
