INSERT INTO `ofeedbacks` VALUES (648, 20, 150, 623, '9b9d75d00f582ae1743b38d9b35c2af4', 'Noer Fathimah Azzahra', '124170118', 'Kelebihan :\r\n\r\nKekurangan :\r\ntugas 1\r\nbelum menjelaskan ya\r\n\r\ntugas 2\r\ntatalaksana pada kasus kira kira apa ya? coba dibaca kasusnya pelan pelan, kan sudah ada guidline nya di GINA dibaca lagi ya, indikasi nya apa? obat sediaan dosis nya? cara pemberiannya?\r\n\r\nMasukan:\r\n- belajar lagi yang baik ya de', 1, '2026-05-08 02:31:38', '2026-05-09 01:36:25');
