INSERT INTO `ofeedbacks` VALUES (650, 20, 159, 704, '7d570857bcce1a41f6d1bef030e0d906', 'Dwi Fajar Indriani', '123170035', 'Kelebihan :\r\n\r\nKekurangan :\r\nnomor 1: jangan lupa ini alergi ya, apa yg dominan pd alergi?\r\nnomor 2: bronkus nya terobstruksi oleh apa? yg gak normal saat inspirasi? SABA meringankan gejala apa? keluhan terus menerus yg mana? kerja obatnya dimana?\r\n\r\nMasukan:\r\npelajari lagi ya patof dihubungkan dgn manifest klinis nya', 1, '2026-05-08 02:31:40', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (651, 20, 156, 678, '33079e781e5a8499eee87409c13b4f68', 'Wirda Rizki Utami Asrori', '123170186', 'Kelebihan :\r\n\r\nKekurangan :\r\n- Kurangnya menjelaskan patofisiologi munculnya manifestasi klinis\r\n- Penjelasan bukan dari wheezing shg pertukaran oksigen jadi terganggu (?)\r\n- Tatalaksana inhaler (?)\r\n\r\nMasukan:\r\n- Biasakan dalam menjelaskan patofisiologi diawali dari faktor resiko maupun etiologi - Aktivasi sel mast (tersensitisasi IgE) - degranulasi - pelepasan mediator kimia Bronkokonstriksi + edema mukosa + peningkatan mukus - hingga muncul manifestasi klinis\r\n- Baca dan pelajari kembali terkait penyakit Asma', 1, '2026-05-08 02:31:42', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (652, 20, 158, 694, 'e7589a3f3ae7d2c274d4e31803f55751', 'Muhammad Rayhan Alwi', '124170097', 'Kelebihan :\r\nTugas 1\r\n\r\nKekurangan :\r\nTugas 2: bner 3 tepat dari point 5 tepat untuk tatalaksana awal pasien dikasus\r\nMasukan:\r\nCukup baik, namun kedepan jangan sampai remedial lagi', 1, '2026-05-08 02:31:50', '2026-05-09 01:36:25');
