INSERT INTO `ofeedbacks` VALUES (655, 20, 159, 705, 'b9792007a9a4a5bd70ab4eb0e5ec8bbd', 'Ineu Anisa', '124170065', 'Kelebihan :\r\n\r\nKekurangan :\r\nnomor 1: pelajari lagi pemeriksaan fisik yg normal pd jantung.\r\ndasar diagnosis tidak lengkap, yg menjadi \"dasar\" belum disebutkan dgn tepat\r\nnomor 2: \"depolarisasi lebih cepat\", jadi takikardia dong, apakah sesuai dgn diagnosisnya?\r\n\r\nMasukan:', 1, '2026-05-08 02:47:05', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (656, 20, 157, 685, '959feda815772cdc33199bb251fc41f4', 'Darus Phindutur', '123170030', 'Kelebihan :\r\n\r\nKekurangan :\r\npenjelasan diagnosis dan patofisiologi cukup namun banyak baca kembali ya teori terkait AV block ini\r\n\r\nMasukan:\r\nbanyak belajar lagi\r\nbaca lagi\r\nsemangat selaluuu', 1, '2026-05-08 02:47:05', '2026-05-09 01:36:25');
