INSERT INTO `ofeedbacks` VALUES (659, 20, 160, 715, '201007f3253d07e554a0e589d624b264', 'Rian Firdaus', '124170137', 'Kelebihan :\r\n\r\nKekurangan :\r\n- tidak bisa menentukan derajat av blok\r\n- belum bisa membaca EKG\r\n- patofisiologi belum lengkap, penjelasan tidak ada benang merah sampai munculnya gejala\r\nMasukan:', 1, '2026-05-08 02:47:06', '2026-05-09 01:36:25');
