INSERT INTO `ofeedbacks` VALUES (661, 20, 158, 695, '46f782ca0b6437c7c4993c7a90cc48af', 'Naila Lathifah', '124170105', 'Kelebihan :\r\n-\r\nKekurangan :\r\nTugas 1 : diagnsosis tidak tepat\r\nTugas 2: patofisologi tidak tepat\r\nMasukan: belajar lagi', 1, '2026-05-08 02:47:08', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (662, 20, 148, 605, '8d154827a29d017d210cd0000d16a66e', 'Indah Permata Dewi', '124170062', 'Kelebihan :\r\npembawaan yang tenang\r\n\r\nKekurangan :\r\ntugas 1:\r\ndiagnosis belum tepat\r\n\r\ntugas 2:\r\njelaksanlah mulai dari FR atau penyebabnya, tetapi diagnosis masih belum tepat\r\n\r\n\r\n\r\nMasukan:\r\nbaca baik-baik kasusnya, tidak hanya menyebutkan semua yang tertulis di skenario, cukup sampaikan apa yang menjadi dasar diagnosis,,\r\nintegrasikan data dari anam-pf dan pp untuk kamu bisa menentukan diagnosis', 1, '2026-05-08 02:47:08', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (663, 20, 149, 613, 'b9031980322d063f0f6fe2d70bbb0e3b', 'Salwa Syahrianti Fajri', '124170144', 'Kelebihan :\r\n\r\nKekurangan : dasar diagnosis kurang lengkap, diagnosis tepat namun penentuan derajatnya kurang tepat, patodfisiologi cukup namun penjelansannya agak diulang2 intinya sama. \r\n\r\nMasukan:', 1, '2026-05-08 02:47:15', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (664, 20, 151, 632, 'b69b63e9303c3a52da1e19390c7c91b3', 'Zalfa Zahira Fildzah', '124170166', 'Kelebihan :\r\n\r\nKekurangan : salah diagnosisnya kenapa efusi?untuk petunjuk utama atau gold standar penegakan diagnosis bisa lihat EKG nya, interpretasi TTV dan penunjang masih tidak tepat\r\n\r\nMasukan:', 1, '2026-05-08 02:47:15', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (665, 20, 156, 679, 'c24b624e993f98bfe9ffc92b0aa63396', 'Daffa Ramadhani Susanto', '124170030', 'Kelebihan :\r\n- Diagnosis : AV Block\r\n- Penentuan dasar diagnosis walaupun kurang lengkap\r\n\r\nKekurangan :\r\n- Diagnosis : AV Block Derajat 3 penentuan derajat kurang tepat\r\n- Penentuan dasar diagnosis tidak lengkap\r\n- Patofisiologi tidak lengkap\r\n\r\nMasukan:\r\n- Pelajari kembali teori dari penyakit AV block\r\n- Biasakan dalam penentuan dasar diagnosis diawali dari anamnesis PF hingga Pem penunjang\r\n- Penjelasan patofisiologi diawali etiologi ataupun faktor resiko hingga munculnya manifestasi klinis\r\npatofisiologi penyakit dan manifestasi klinis yang muncul dengan tepat dan lengkap - Riwayat PJK dan konsumsi obat - Perlambatan konduksi nodus AV - Waktu hantaran impuls dari atrium --> Ventrikel memanjang - Semua impuls tetap diteruskan ke ventrikel - Irama sinus regular - Manifestasi Klinis', 1, '2026-05-08 02:47:25', '2026-05-09 01:36:25');
