INSERT INTO `ofeedbacks` VALUES (688, 20, 157, 687, 'b00dd01d5c6105f8487ab7fe9aa78f16', 'Aura Putri Hermawan', '124170022', 'Kelebihan :\r\npenjelaasan patof dan penatalaksanaan cukup namun banyak belajar lagi ya\r\n\r\nKekurangan :\r\n\r\nMasukan:\r\nbanyak belajar dan baca lagi\r\nsemangat selalu', 1, '2026-05-08 03:18:29', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (689, 20, 149, 615, '7f16a722cd5a44435c6d67b75e9f9660', 'Firli Nazwa Amaliah', '124170052', 'Kelebihan :\r\n\r\nKekurangan : penjelasan tepat namun tidak lengkap\r\n\r\ntatalaksana tidak tepat obat dan dosis, hanya 1 yang benar\r\nMasukan:', 1, '2026-05-08 03:18:31', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (690, 20, 148, 607, 'adf67e1658339a3f390ab63b3210eb62', 'Ulfa Ni\'matul Hidayah', '124170158', 'Kelebihan :\r\npembawaan yang tenang\r\n\r\nKekurangan :\r\ntugas 1\r\ndiagnosis belum tepat \r\ndiagnosisnya berubah ubah,,makanya dibaca baik-baik dhe,,bukan tebak-tebakan dari kasus yang sudah dikeluarkan kemarin,,\r\ndi skenario tidak ada manifestasi klinis yang kamu sebutkan lho,,,darimana ituuuu\r\n\r\ntugas 2\r\nkarena diagnosis belum tepat, jadi tatalaksana belum tepat.\r\n\r\nMasukan:\r\nBaca dan pahami kasusnya baik-baik\r\nBelajarlah dengan benar\r\nDiagnosis pasien itu bukan tebak-tebakan ya,,tetapi ada dasar diagnosisnya yang sudah ada di skenario\r\nIntegrasikan informasi yang kamu dapatkan dari anamnesis, PF dan pemeriksaan penunjang kemudian sesuaikan dengan teori yang pernah kamu pelajari', 1, '2026-05-08 03:18:36', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (691, 20, 161, 727, '860834e35b70e8ba18982dffc237832b', 'Galuh Pareza Firdaus', '122170065', 'Kelebihan :\r\n\r\nKekurangan :\r\npatofisiologi tidak tepat karena diagnosis tdk tepat\r\ntatalaksana kuarng tepat\r\n\r\nMasukan:', 1, '2026-05-08 03:18:38', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (692, 20, 153, 651, '407e6241512e399cf16e0584e4d8db78', 'Ahmad Hakim Fadillah', '124170005', 'Kelebihan : Sudah memulai dengan PD\r\n\r\nKekurangan : FR hipertensi kronis lebih dominan dibanding merokok, sehingga hipertensi yang lebih perlu dijelaskan untuk kasus ini. \r\n\r\nMasukan: Belajar lagi ya Hakim...', 1, '2026-05-08 03:18:52', '2026-05-09 01:36:25');
