INSERT INTO `ofeedbacks` VALUES (694, 20, 153, 652, '077e31049fbe8ad2e2d77d02b8825a74', 'Muhammad Hanif Izzul Haq', '123170105', 'Kelebihan : Sdh memulai dengan PD.\r\n\r\nKekurangan : Belajar lagi apa itu efusi, pneumothorax dll. Keluhan pasien batuk darah yang banyak, coba dihubungkan secara logis dengan RPD. \r\n\r\nMasukan: Harus banyak belajar dengan sistematis dan logis ya Hanif.', 1, '2026-05-08 03:33:57', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (695, 20, 154, 661, '372468e0c35f5d3d577ea3fc54eac404', 'Sahya Andria Putri', '123170159', 'Kelebihan : Diagnosis cukup benar\r\n\r\nKekurangan : dasar diagnosis sedikit kurang lengkap, patofisiologi sedikit kurang sesuai\r\n\r\nMasukan: pelajari detail dasar diagnosis dan patofisiologi', 1, '2026-05-08 03:33:58', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (696, 20, 159, 708, '0973b9cdf7d992f4481feb6a91a91a45', 'Zakiyah Nurul Ilmi', '124170165', 'Kelebihan :\r\n\r\nKekurangan :\r\nnomor 1: diagnosis kurang tepat, lalu dasar diagnosisnya apa, tidak disebutkan. dasar diagnosis itu dilihat mulai dari anamnesis (RPS, RPD, R{K, RPSos), pf, dn p.penunjang.\r\nnomor 2: karena nomor 1 tidak tepat dx nya, maka patof nya juga akan berpengaruh. kalaupun diagnosis nya seperti yg disebutkan, patof yg dijelaskan sangat superfisial\r\n\r\nMasukan:', 1, '2026-05-08 03:33:58', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (697, 20, 155, 670, '57d43ff21735bb63b7e5f2b153c07c51', 'Kaisa Nur Khoiriyah', '124170072', 'Kelebihan :\r\n\r\nKekurangan :\r\ntugas no 1 diagnosis tdk lengkap dan tepat\r\npenjelasan tugas no 2 tdk lengkap dan tepat \r\n\r\nMasukan:', 1, '2026-05-08 03:33:59', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (698, 20, 160, 718, 'b7f836a57d1626d5e8a34e9b46c34edd', 'Alifvia Syifa Nur Maisaan Budy', '124170010', 'Kelebihan :\r\n\r\nKekurangan :\r\n- volume batuk darahnya tidak diperhatikan sehingga diagnosis kurang lengkap\r\nMasukan:', 1, '2026-05-08 03:33:59', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (699, 20, 158, 698, '395d0733bec7f792bd472fdb98b262cd', 'Naufal Ramadhan Gianindra', '123170117', 'Kelebihan :\r\n-\r\nKekurangan :\r\nTugas 1:diagnosis tepat, dasar diagnosis yang sesuai tidak lengkap\r\nTugas 2: patofisiologi  tepat namun tidak lengkap  \r\nMasukan:\r\ncukup baik, namun masih dapat ditingkatkan lagi', 1, '2026-05-08 03:34:01', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (700, 20, 161, 728, 'f8fd8d48f09ca384afc64e15444d8d9e', 'Muhamad Rizal Azkiya', '124170087', 'Kelebihan :\r\n\r\nKekurangan :\r\ndiagnosis salah pengucapan kayaknya ya, dasar diagnosis kurang lengkap\r\npatofisiologi kurang sistematis kurang detail\r\n\r\nMasukan:', 1, '2026-05-08 03:34:05', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (701, 20, 152, 643, 'f00b7bdfb55c0433830dc0f9ad4c04da', 'Peni Mutiasari', '124170120', 'Kelebihan :\r\n\r\nKekurangan : tugas 1 dan 2 terjawab namun belum lengkap \r\n\r\nMasukan: belajar yang rajin', 1, '2026-05-08 03:35:03', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (702, 20, 157, 689, 'e2bb483fd178ce867bff6e3cc0313139', 'Sandra Naila Divi Wijaya', '124170145', 'Kelebihan :\r\n\r\nKekurangan :\r\npenjelasan diagnosis sudah cukup namun ini kan lebih dari 400 cc jadi masif\r\npenjelasan patofisiologi masih belum lengkap\r\n\r\nMasukan:\r\nbanyak belajar dan baca lagi ya dek\r\nsemangat selaluu', 1, '2026-05-08 03:36:35', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (703, 20, 158, 699, 'e260cbafac1dd4c3fe164785d38d3ace', 'Zafira Nada Azahra', '124170161', 'Kelebihan :\r\n-\r\nKekurangan :\r\nTugas 1:diagnosis tepat dasar diagnosis yang sesuai tidak lengkap loncat langsung ke rontgen\r\nTugas 2: patofisiologi tidak dapat menjelaskan dengan tepat  dan lengkap  \r\nMasukan:\r\nbelajar lagi', 1, '2026-05-08 03:47:23', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (704, 20, 159, 709, 'e5f0ff37fcd5a945631cf3cbfe4fe470', 'Nasywa Nadia Kamal', '124170109', 'Kelebihan :\r\n\r\nKekurangan :\r\nnomor 1: pelajari lagi yg noral normal dalam pf yaa.\r\npojok2 di rontgen??\r\ndiagnosis nya tidak lengkap\r\nnomor 2: \"oksigen masuk tidak bisa dikeluarkan lalu menyebabkan penumpukan cairan\"?\r\nendotel rusak?\r\ndarah dari ventrikel kanan disebarkan ke aorta, aorta yg mana ya?? ini dasar banget dek, coba baca lagi\r\nbadan lemas: tubuh mghasilkan asam?\r\n\r\nMasukan:\r\nbelajar lagi ya dek, semangaaat', 1, '2026-05-08 03:49:36', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (705, 20, 160, 719, 'acb82c5ae8321c488929dd5a1723a9e0', 'Hasan Syadili', '124170053', 'Kelebihan :\r\n\r\nKekurangan :\r\n- belum mampu membaca rontgen\r\n- patofisiolgi belum terbentuk benang merah sampai munculnya gejala\r\nMasukan:', 1, '2026-05-08 03:49:37', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (706, 20, 161, 729, '97c0063b3ca5f260516f9f296ecb18d6', 'Rafli Kusuma Ramdhani', '124170127', 'Kelebihan :\r\n\r\nKekurangan :\r\ndasar diagnosis kurang lengkap\r\npatofisiologi tidak tepat\r\n\r\nMasukan:\r\nbaca lagi dan pahami, efusi, emboli, edema dll', 1, '2026-05-08 03:49:38', '2026-05-09 01:36:25');
INSERT INTO `ofeedbacks` VALUES (707, 21, 162, 730, '66f918b85ca4d73e29b3ab08ad9aff07', 'Andini Yuanita Putri', '124170015', 'Kekurangan :\r\nTugas 1 : \r\nPenjelasan tidak spesifik menjawab soal yang diminta, hanya menjelaskan secara superficial. \r\nJelaskan juga fungsi spesifik dr pons dan medulla oblongata lainnya\r\nTugas 2:\r\nMenjawab namun tidak jawaban tidak sesuai dengan yang diminta oleh kasus\r\n\r\nSaran :\r\nPerhatikan Kembali soal2 yang diminta oleh kasus. Mekanisme dengan Pengaturan apakah sama ?', 1, '2026-05-08 06:39:19', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (708, 21, 169, 794, '62c142c63fa1bfca82d5c4192d43d89e', 'Siti Alfiyah Nur Rahmani', '125170135', 'Feedback\r\nTugas 1: sudah tepat, lengkap, dan sistematis\r\nTugas 2: sudah tepat, namun tidak lengkap\r\n\r\nTetap semangat belajar!', 1, '2026-05-08 06:41:38', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (709, 21, 163, 739, '4355e047b256dfe53fecc7620b1ec020', 'Jalu Sekti Puspito Yunus Dahlan', '125170053', 'Kelebihan :\r\nsudah mengetahui pusat pengaturan pernapasan \r\n\r\nKekurangan :\r\ntugas pertama, penjelasan mengenai pengaturan pernafasan involunteer kurang lengkap. \r\nbelum menjelaskan pust pernafasan ada MO dan Pons, fungsi masaing2nya apa\r\nlalu belum menjelaskan pusat pernafasan di MO ada DRG dan VRG, jalur impuls sarafnya bagaimana? aktivasi otot pernapasannya? mekanisme inspirasi dan ekspirasinya bagaimana?\r\ntugas kedua kurang lengkap, belum menjelaskan peningkatan hormone epinefrin dan refleks hering-breuer\r\n\r\nMasukan:\r\nbelajar lagi sehingga penjelasan lebih tepat dan lengkap', 1, '2026-05-08 06:41:45', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (710, 21, 165, 755, '6ee9fbf5e287d71d73d8d8d2963b7c04', 'Raras Ing Tasnim', '125170113', 'Kelebihan :\r\n\r\nKekurangan :\r\ntidak dijelaskan bagaimana pengaturan pernafasannya, hanya menyebutkan pons dan medula oblongata\r\n2 faktor non-kimiawi yg benar sudah disebutkan, tapi penjelasannya tidak tepat.\r\n\r\nMasukan:\r\nmohon dibaca dengan baik pertanyaan nya, jika \"jelaskan\" maka jelaskan bagaimana pengaturan pernafasannya, bukan hanya menyebutkan pusat pengaturan pernafasan nya.', 1, '2026-05-08 06:41:45', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (711, 21, 168, 784, '754f295d3903bff2d06fab74553d8114', 'Nuraini Siti Maryam', '125170109', 'Kelebihan :\r\npemahaman sudah cukup baik, konsepnya cukup paham\r\nKekurangan :\r\nArah penjelasan bingung, kurang memahami maksud soal\r\nMasukan:\r\nFokus saat membaca soal dan coba lebih kritis pada saat PBL', 1, '2026-05-08 06:41:47', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (712, 21, 167, 775, '4d660528b592ae885792570121e45f2b', 'Galang ramadhan', '125170037', 'Kelebihan :\r\n\r\nKekurangan :\r\n- penjelasan tugas no. 1 kurang tepat yaa de!\r\n- penjelasan tugas no. 2 tidak tepat jugaa yaa\r\n\r\nMasukan:\r\n- baca tugas dan pahami dgn baik yaa mekanisme nya \r\n- belajar lg rajin lagiii yaaa de!', 1, '2026-05-08 06:41:49', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (713, 21, 178, 824, 'ba65a8fd431c7e98014a216ff086901f', 'ALICO AKBAR SUPRIYADI', '125170006', 'Kelebihan :\r\n\r\nKekurangan :\r\ntugas 1 : penjelasan kurang lengkap, penjelasannya sudah benar tapi masih kurang sistematis. harus menjelaskan dari pusat pernafasan sampai aktivasi otot pernapasannya bagaimana\r\ntugas 2 : hanya dapat menjelaskan 2 faktor secara tepat\r\n\r\nMasukan:\r\nbelajar lagi ya ...', 1, '2026-05-08 06:41:49', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (714, 21, 170, 804, 'd3d853608107fa14e61b22e7d4ef394f', 'Difa Shofiyyurohman Harsono', '123170033', 'Kelebihan :\r\n\r\nKekurangan :\r\n\r\nMasukan:cukup tepat', 1, '2026-05-08 06:41:56', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (715, 21, 171, 814, '8b6738fd097896f077d822e53ceb1503', 'Muhamad Azwar Firdaus Sidiq', '125170074', 'Kelebihan :\r\n- tugas no.2 sudah menyebutkan salah satu faktor non kimiawi\r\n\r\nKekurangan :\r\n- tugas no.1 kurang lengkap. sesuaikan jawaban(pengaturan pernafasan yang terjadi) dengan kasus\r\n- tugas no.2 kurang lengkap. faktor yang disebutkan hanya 1, penjelasannya juga kurang tepat\r\n\r\nMasukan:\r\n- lebih konsentrasi lagi ya\r\n- semangat belajar lagi', 1, '2026-05-08 06:41:56', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (716, 21, 166, 765, 'a8cc2d79fa9728e1251b1f4ae9bd99d6', 'Azka Rayi Dwi Herudianti', '125170015', 'Kelebihan : mahasiswa mampu menjelaskan mekanisme pernafasan dengan baik\r\n\r\nKekurangan : penjelasan faktor non kimiawi kurang lengkap\r\n\r\nMasukan: belajar lagi', 1, '2026-05-08 06:42:05', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (717, 21, 164, 747, '2e862acc69b2d46040cea51d92ab9d2a', 'Agnia Rahma Alita', '125170003', 'Kelebihan :\r\n\r\nKekurangan : yg dijelasin \"pusat pernapasan ada di pons. lalu pneumotaksis akan dibantu oleh kemoreseptor untuk mengirimkan sinyal ke otak untuk inspirasi. otak --> M. intercostalis interna dan diafragma. \r\napneustik : pernapasan scr sadar.\" udh yang dijelasin. \r\nlalu lanjut jelasin no 2. tidak tepat, tidak sesuai dengan tugas yang diminta \r\n\r\nMasukan:\r\nbelajar de', 1, '2026-05-08 06:42:05', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (718, 21, 170, 805, 'bd688e04e894f31d71708d5bf1b9ba49', 'Mochamad Andika Heldiansyah', '125170070', 'Kelebihan :\r\n\r\nKekurangan :\r\n\r\nMasukan:cukup tepat', 1, '2026-05-08 06:56:30', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (719, 21, 162, 731, '8d2d628a8d513ceb1c0623d8bd859b31', 'Moch Syaamil Muntahalkamal', '125170069', 'Kelebihan :\r\nMencoba menjawab Tugas 1 dan 2\r\n\r\nKekurangan :\r\nTugas 1 : Simpatis dan parasimpati termasuk kontrol apa ? Pelajari lagi ya \r\nTugas 2 : Kaitkan langsung dgn Tahanan Perifernya bukan hanya viskositasnya saja\r\n\r\nMasukan:\r\nPerhatikan Kembali soal2 yang diminta oleh kasus ya, jgn lupa kaitkan dengan kasusnya', 1, '2026-05-08 06:57:17', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (720, 21, 167, 776, '287eabd390a898c45005ff51e1257824', 'Mohammad Deny Setyawan Atmaja', '125170071', 'Kelebihan :\r\n\r\nKekurangan :\r\n- tugas no. 1 : jadi apa penjelasannya ?? mengapa bisa terjadi demikian ?\r\n- tugas no. 2 penjelasan kurang tepat, bukan hanya menyebutkan tp duhubungkan dgn mekanisme di tugas no. 1 nya\r\n\r\nMasukan:\r\n- baca tugas dgn teliti !! , dan sesuaikan dgn kasusnya spt apaa?\r\n- belajar lagiiiii !!', 1, '2026-05-08 06:57:17', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (721, 21, 178, 825, '3b7249d5e2555aeed4cab04d282ba2f1', 'Muhammad Nawad Taqiyuddin', '125170088', 'Kelebihan :\r\n\r\nKekurangan :\r\ntugas 1 : tepat tetapi penjelasan kurang lengkap, bisa lebih sistematis lagi ya\r\ntugas 2 : tepat tetapi penjelasan terkait pengaruhkanya ke tahanan perifer kurang lengkap\r\n\r\nMasukan:\r\nbelajar lagi ya ...', 1, '2026-05-08 06:57:18', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (722, 21, 169, 795, 'a724eabf3892371e79e7852c390a8f8f', 'Tsabita Aurel Azarina', '125170144', 'Feedback\r\nTugas 1: menjelaskan mekanisme tahanan perifer pada kasus dengan tepat, tapi belum lengkap\r\nTugas 2: menjelaskan komponen darah dengan tepat, tapi tidak lengkap\r\n\r\nTetap semangat belajar!', 1, '2026-05-08 06:57:18', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (723, 21, 163, 740, 'ad847df69b0696585722d09f438b9f77', 'Diva Nabila Putri', '125170027', 'Kelebihan :\r\nsudah mengetahui faktor-faktor yang mempengaruhi mekanisme tahanan perifer\r\n\r\nKekurangan :\r\ntugas pertama, penjelasan mengenai mekanisme tahanan perifer yang terjadi pada kasus kurang tepat dan lengkap. tidak menjelaskan kontrol iontrinsik dan ekstrinsiknya.  \r\ntugas kedua tidak menjelaskan dampaknya terhadap viskositas dan tahanan perifer, hanya menyebutkan komponen dan fungsinya --> tidak sesuai yang diminta pada tugas. \r\n\r\nMasukan:\r\nbelajar lagi sehingga penjelasan lebih tepat dan lengkap', 1, '2026-05-08 06:57:19', '2026-05-09 01:35:07');
