INSERT INTO `ofeedbacks` VALUES (725, 21, 165, 756, '826dd3b868daa8919adce62b25d33f4d', 'Arum Kasturi', '125170011', 'Kelebihan :\r\n\r\nKekurangan :\r\nmekanisme tahanan perifer kurang tepat\r\npenjelasan mengenai hemoglobin tidak tepat\r\neritrosit dan plasma sdh disebutkan namun tidak menyertakan pengaruh terhadap mekanis=me tahanan perifernya seperti apa\r\nMasukan:\r\nbedakan tahanan perifer dengan aliran balik vena ya, kalo aliran balik vena itu di kasus lain, mohon jangan di hafal ya de tp dipahami', 1, '2026-05-08 06:57:44', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (726, 21, 164, 748, '1eef4148eace4e8b7e6eaef1a4501285', 'M Luthfi Syahid', '125170065', 'Kelebihan :\r\n\r\nKekurangan :\r\nno. 1 Menjelaskan tahanan perifer dipengaruhi Cardiac Output --> tek darah \r\nno.2 komponen sel darah merah --> melakukan aktifitas lari irngan, otot membutuhkan oksigen di bantu oleh sel darah merah. \r\nplasma menjaga tekanan osmotik dan juga volume sirkulasi. \r\n\r\nMasukan:\r\nyang dijelaskan tidak sesuai dengan tugas yang diminta.', 1, '2026-05-08 06:57:46', '2026-05-09 01:35:07');
