INSERT INTO `ofeedbacks` VALUES (728, 21, 167, 777, 'e4a9fd2f2226d0d0038b9e66e5172ee5', 'Nazneen Amanda Nirmala Devi', '125170105', 'Kelebihan :\r\n\r\nKekurangan :\r\n- tugas no. 1 itu menjelaskan mekanisme nya bukan hanya disebutkan saja yaa de!\r\n- tugas 2 tidak tepat !, malah lupa :(\r\n\r\nMasukan:\r\n- lebih ditingkatkan belajarnya !! \r\n- pahami tugas yg diberikan. lebih teliti lagi!!', 1, '2026-05-08 07:08:07', '2026-05-09 01:35:07');
