INSERT INTO `ofeedbacks` VALUES (730, 21, 162, 732, 'f976e11e4b0b8234cd35b1fe853195d8', 'Namira Syifa Azahra', '122170130', 'Kelebihan :\r\nmencoba menjawab\r\nKekurangan :\r\nTugas 1 : Pelajari lg apa yang dimaksud Pernafasan, Ventilasi, Respirasi terlebih dahulu ya\r\nTugas 2 :Baca kembali soalnya ya, komponennya yang diminta jgn lupa perannya juga\r\nMasukan:\r\nPahami kembali soal yang diminta, karena beda kata bisa menunjukan beda maksud dan tugasnya', 1, '2026-05-08 07:11:29', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (731, 21, 164, 749, '9eec2376d9db0e669b48d8f08b57d675', 'MUHAMMAD MUBDI NUR ESA', '125170087', 'Kelebihan :\r\n\r\nKekurangan : mahasiswa menjelaskan : \r\nno. 1 manusia setiap hari harus bernapas, inspirasi mambawa tekanan masing2 molekul yang menekan paru2 -->  okesigen akan berpindah ke pemb darah karna di paru banyak oksigen, kemudian --> berdifusi ke yang akan menjadi energi untuk  sel sel --> akan menjadi karbondioksida --> akan dikembalikan ke paru2 menuju jantung. ventilasi pernapasan ada di tengah batang otak. dibagi mjd pern volunter dan involunter. \r\ntugas no 2, sama sekali tidak tepat \r\nMasukan:\r\n menjelaskan panjang lebar tapi ga sesuai dengan jawaban yang diminta pada tugas no 1 maupun no 2', 1, '2026-05-08 07:12:58', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (732, 21, 169, 796, '934be6867774c145d6ed5237d3c6b50b', 'Marzell Richard Alfredo', '125170066', 'Feedback\r\nTugas 1: menjelaskan mekanisme pengaturan pernapasan dengan tepat, tapi tidak lengkap\r\nTugas 2: menjelaskan komponen keseimbangan asam basa dan perannya dengan tepat, tapi tidak lengkap\r\n\r\nTetap semangat belajar!', 1, '2026-05-08 07:13:03', '2026-05-09 01:35:07');
