INSERT INTO `ofeedbacks` VALUES (740, 21, 162, 733, 'ae50f4771475b5c7f2bd6e7f81230166', 'Azzahra Nur Amalia', '124170026', 'Kelebihan :\r\nMencoba menjawab\r\nKekurangan :\r\nTugas 1 : Jalur internodal dan bundel Bachmann serta Crus Dextrum dan crus sinistrum tertinggal\r\nTugas 2 :  Agen Kronotropik dan Inotropik terbalik, Kronotropik belum dijelaskan. Agennya belum disertakan\r\nMasukan:\r\nBelajar lg yaaaa :)', 1, '2026-05-08 07:28:26', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (741, 21, 167, 778, '792f34720963d89d285579dd804918a5', 'Muhamad Naufal Dzaky Suryanto', '125170077', 'Kelebihan :\r\n\r\nKekurangan :\r\n- tugas no. 1 : menjelaskan nya tidak tepat ! tugas yg disediakan dan apa yg km jelaskan tidak sesuai yaa de\r\n- tugas 2 ??\r\n\r\nMasukan:\r\n- lebih ditingkatkan belajarnya !!\r\n- perhatikan time management km menjawab soalnya ! jgn terlalu lama diam.', 1, '2026-05-08 07:28:32', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (742, 21, 178, 827, 'ddc5e8698e4975735ad9de7e4199b1ed', 'Arlisa Nabila Larasati', '125170010', 'Kelebihan :\r\n\r\nKekurangan :\r\ntugas 1 : kurang lengkap. dari SA node sebelum ke AV node melalui apa dulu (yg fungsinya menghantarkan impuls dari SA ke atrium kiri dan kanan)???\r\ntugas 2 : tidak menyebutkan contoh zatnya dengan lengkap\r\n\r\nMasukan:\r\nbelajar lagi ya ...', 1, '2026-05-08 07:28:34', '2026-05-09 01:35:07');
