INSERT INTO `ofeedbacks` VALUES (744, 21, 163, 742, '53e20f678a35a7608e622e139db6f231', 'Muhammad Rayhan Avicenna', '125170089', 'Kelebihan :\r\n\r\nKekurangan :\r\ntugas pertama, penjelasan mengenai system konduksi jantung kurang menjelaskan jalur internodal dan bundel Bachmann sblm ke nodus AV. dan kurang menjelaskan crus dextrum dan sinistrum sblm ke serabut purkinje. \r\n\r\ntugas kedua, penjelasan mengenai agen inotropic kurang tepat, contoh agennya blm disebutkan \r\n\r\nMasukan:\r\nbelajar lagi sehingga penjelasan lebih tepat dan lengkap', 1, '2026-05-08 07:28:38', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (745, 21, 164, 750, 'dd483e3a5998ea8bea8c36fc8f3de2b4', 'Seni Umaya Maharani', '125170129', 'Kelebihan :\r\n\r\nKekurangan :\r\ntugas no 1 : baru menyebutkan SA node saja, langsung ke serabut purkinje. belum sistematis dan belum lengkap ini\r\ntugas no 2 : contoh zat nya ketuker2 kurang tepat \r\nMasukan:\r\nbelajar lagi atuh ya', 1, '2026-05-08 07:28:47', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (746, 21, 165, 758, '6bd4bcf6b63074f94c72a50f07845ded', 'Safira Galuh Putri', '125170121', 'Kelebihan :\r\nno 1 lengkap\r\nNo 2 dijawab cukup baik \r\nKekurangan :\r\n\r\nMasukan:\r\nmasih tertukar2 yang mana kronotropik dan inotropik', 1, '2026-05-08 07:28:52', '2026-05-09 01:35:07');
