INSERT INTO `ofeedbacks` VALUES (748, 21, 171, 817, '5fecd1ac5b1cceec4e65e17f9ecad29b', 'Fuji Rahayu', '125170036', 'Kelebihan :\r\n\r\nKekurangan :\r\n- tugas no. 1: penjelasan mengenai tahanan perifer kurang tepat\r\n- tugas no. 2: penjelasan mengenai komponen darah yang mempengaruhi mekanisme tahanan perifer masih kurang lengkap dan kurang tepat\r\n\r\nMasukan:\r\n- fokus dan konsentrasi\r\n- semangat belajar lagi ya', 1, '2026-05-08 07:29:49', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (749, 21, 166, 769, 'a259211c0282c00b5d2a0a73412d85dd', 'Tambun Joel Cressendo Nainggolan', '125170141', 'Kelebihan : mahasiswa mampu menjelaskan struktur makroskopis jantung dengan baik\r\n\r\nKekurangan : pengaturan pompa jantung kurang lengkap\r\n\r\nMasukan: belajar lagi', 1, '2026-05-08 07:41:50', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (750, 21, 171, 818, 'c334ed85cd2048bbeed70eb663cd6564', 'Pandu Adhymahotama', '125170110', 'Kelebihan :\r\n\r\nKekurangan :\r\ntugas no.1 jawaban saudara atas petanyaan mekanisme pengaturan asam basa tdk sesuai\r\ntugas no.2 tidak dapat menyebutkan komponen yang dimaksud\r\n\r\nMasukan:\r\nfokus dan konsentrasi\r\nsemangat belajar lagi ya', 1, '2026-05-08 07:44:12', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (751, 21, 169, 798, '850dbb19219a25c197e2108505767d51', 'Dewi Yohana Budiman', '125170024', 'Feedback\r\nTugas 1: belum menjelaskan mekanisme pengaturan pompa jantung pada kasus dengan tepat (harusnya jelaskan tentang mekanisme intrinsik-> frank sterling dan mekanisme ekstrinsik-> saraf otonom dan pengaturan kimiawi, hormonal\r\nTugas 2: sudah menyebutkan struktur makroskopis ruang dan katup jantung, tapi belum terlalu \"menjelaskan\" secara lengkap struktur makroskopis ruang dan katup jantung\r\n\r\nTetap semangat belajar!', 1, '2026-05-08 07:44:12', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (752, 21, 178, 828, '25efbbcd78385d056926a7bbfe5c8bc4', 'Hevi Salvia', '125170048', 'Kelebihan :\r\n\r\nKekurangan :\r\ntugas 1 : yg ditanyakan adalah mekanisme pengaturan pompa jantunya yaa\r\ntugas 2: tepat tapi tidak lengkap. misal di atrium ada Musculus apa? di katup jantung ada bagian-bagiannya lagi kan? apa saja? harusnya dijelaskan secara lengkap yaa\r\n\r\nMasukan:\r\nbelajar lagi ya ...', 1, '2026-05-08 07:44:19', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (753, 21, 164, 751, 'b5aae8c3debe0f0399b2c10f25f06033', 'YUDA PUTRA PRAWIRA', '125170149', 'Kelebihan :\r\n\r\nKekurangan :\r\nyg kamu jelasin tuh ga sesuai dgn tugas yg diminta de, masa km jelasin pernapasan ? \r\ntugas 2 km jelasin ga lengkap. soal nya tuh diminta menjelaskan bukan menyebutkan. jelasin lengkap dari ruang jantung tuh bagaimana? bukan cuma sebut ruang jantung ada atrium dextra dsb \r\nMasukan:\r\nbelajar lagi deh ya', 1, '2026-05-08 07:44:23', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (754, 21, 165, 759, '2b17a9f683e392004f8307e30f03108d', 'Shofa Wahyu Diniar', '125170133', 'Kelebihan :\r\njawaban no 2 cukup baik\r\n\r\nKekurangan :\r\njawaban no 1 tidak lengkap\r\n\r\nMasukan:', 1, '2026-05-08 07:44:43', '2026-05-09 01:35:07');
