INSERT INTO `ofeedbacks` VALUES (756, 21, 163, 743, '32087b9613eb70e92f42ccd1413c9733', 'SYAHLA AURELIA', '125170139', 'Kelebihan :\r\nsudah mengetahui mekanisme pengaturan pompa jantung dari mekanisme intrinsic (hukum frank starling)\r\n\r\nKekurangan :\r\ntugas pertama, kurang menjelaskan mekanisme pengaturan pompa jantung dari ekstrinsiknya (saraf otonom dan pengaturan kimiawi dan hormonal) \r\npenjelasan mengenai pengaturan dari saraf simpatis dan parasimpatis kurang tepat\r\ntugas kedua, hanya menyebutkan nama ruangan dan katupnya saja tapi tidak menjelaskan bagaimana gambaran struktur makroskopisnya. malah menjelaskan mengenai fungsinya padahal tidak diminta pada tugas.  \r\n\r\nMasukan:\r\nbelajar lagi sehingga penjelasan lebih tepat dan lengkap', 1, '2026-05-08 07:44:48', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (757, 21, 167, 779, 'f648c0878f272c8098f1e4e42c23b91d', 'Nolla Dwi Putri Sulistiani', '125170107', 'Kelebihan :\r\n- tugas 2 cukup baik daan lengkap penjelasannya \r\n\r\nKekurangan :\r\n- tugas no. 1 : kurang tepat :( , baca lagi de tugasnya yaa.. jgn salah memahami soal yaaa \r\nMasukan:\r\n- goodjob, tingkatkan yaaa de :))', 1, '2026-05-08 07:44:57', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (758, 21, 168, 788, 'ca8aceb46069d32ad1577e99b2f8134d', 'Serli Alta Rahma', '125170130', 'Kelebihan :\r\nsudah relevan dengan soal, pemahaman baik\r\nKekurangan :\r\nsangat banyak yang ingin dijelaskan jadi kurang fokus dgn apa yg diminta soal\r\nMasukan:', 1, '2026-05-08 07:45:14', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (759, 21, 162, 735, '5d5809ff15f429260352794f035ed0e2', 'Denova Kiranie Amidjodjo', '125170023', 'Kelebihan :\r\nMencoba menjelaskan\r\nKekurangan :\r\nTugas 2: Jelaskan ada apasaja struktur yang menyusun ruang pada jantung tsb bukan hanya menyebutkan ruangnya saja\r\nTugas 1: mekanisme pengaturan pompa jantung, Mekanisme pengaturan bukan hanya mekanisme pompa jantung\r\nMasukan:\r\n- tidak perlu membacakan soal kepada penguji kembali ya, agar waktu untuk anda menjawab soal lebih efisien\r\n- pahami soal dgn baik ya\r\n- belajar lg :)', 1, '2026-05-08 07:56:55', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (760, 21, 170, 809, '406d5e8b00522d18cab90c1cd2071a35', 'Dimas Subakti', '125170026', 'Kelebihan :\r\n\r\nKekurangan :\r\n\r\nMasukan:cukup tepat', 1, '2026-05-08 07:58:22', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (761, 21, 169, 799, '855a50688732058dfe3cd204af50d5ce', 'Syahira Fajriani Nabila', '125170138', 'Feedback\r\nTugas 1:sudah menjelaskan hubungan bunyi jantung dengan katup jantung dengan tepat dan lengkap\r\nTugas 2: sudah menjelaskan mekanisme siklus jantung dengan tepat dan sistematis, hanya sedikit kurang lengkap\r\n\r\nTetap semangat belajar!', 1, '2026-05-08 07:59:49', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (762, 21, 165, 760, 'a099e0ea86df3a34a57158453c4e6351', 'Salma Raudia Rahman', '125170123', 'Kelebihan :\r\njawaban no 1 lengkap\r\nJawaban no 2 cukup baik \r\n\r\nKekurangan :\r\n\r\nMasukan:', 1, '2026-05-08 07:59:52', '2026-05-09 01:35:07');
INSERT INTO `ofeedbacks` VALUES (763, 21, 163, 744, 'f852b924f6a7abf5e476c3df78616066', 'Khaidar Abdillah Ashidiqie', '125170059', 'Kelebihan :\r\n\r\nKekurangan :\r\ntugas pertama, penjelasan mengenai mekanisme bunyi jantung dihubungkan dengan kasus sudah tepat namun blm menyebutkan akibat adanya turbulensi aliran darah dengan katup \r\ntugas kedua, tidak mampu menjelaskan mekanisme siklus jantung dengan tepat\r\n\r\nMasukan:\r\nbelajar lagi sehingga penjelasan lebih tepat dan lengkap', 1, '2026-05-08 07:59:55', '2026-05-09 01:35:07');
