INSERT INTO `orubriks` VALUES (1, 1, 1, 'Penjelasan pathogenesis dan manifestasi klinis yang muncul', '<p>Mahasiswa tidak mampu<br>menjelaskan pathogenesis penyakit<br>dan manifestasi klinis yang muncul.</p>', '<p>Mahasiswa menjelaskan pathogenesis<br>penyakit dan manifestasi klinis yang<br>muncul dengan tepat</p><ol><li>Lalat simulium (mengandung<br>mikrofilaria)<br></li><li>Larva stadium 3 masuk<br>kedalam jaringa kulit<br></li><li>Cacing betina berada di bawah<br>kulit dan menghasilkan<br>mikrofilaria<br></li><li>Menyebar ke kulit dan mata<br></li><li>Manifestasi klinis (1-2)</li></ol>', '<p>Mahasiswa mampu menjelaskan<br>pathogenesis penyakit dan manifestasi<br>klinis yang muncul dengan tepat</p><ol><li>Lalat simulium (mengandung<br>mikrofilaria)<br></li><li>Larva stadium 3 masuk<br>kedalam jaringa kulit<br></li><li>Cacing betina berada di bawah<br>kulit dan menghasilkan<br>mikrofilaria<br></li><li>Menyebar ke kulit dan mata<br></li><li>Manifestasi klinis (3-4)</li></ol>', '<p>Mahasiswa mampu menjelaskan<br>pathogenesis penyakit dan manifestasi<br>klinis yang muncul dengan tepat dan<br>lengkap</p><ol><li>Lalat simulium (mengandung<br>mikrofilaria)<br></li><li>Larva stadium 3 masuk<br>kedalam jaringa kulit<br></li><li>Cacing betina berada di bawah<br>kulit dan menghasilkan<br>mikrofilaria<br></li><li>Menyebar ke kulit dan mata<br></li><li>Manifestasi klinis (1-2)</li></ol><ul><li><ul><li>Hilangnya kejernihan kornea<br></li><li>Kehilangan pigmen kulit<br>(kulit macan tutul)<br></li><li>Pembesaran KGB</li><li> Eosinophilia<br></li><li>Leukositosis</li></ul></li></ul>', 1, 1, 1, 1, 1, '2025-08-15 10:57:01', '2025-08-15 13:54:33');
INSERT INTO `orubriks` VALUES (2, 1, 2, 'Penjelasan hubungan trias epidemiologi yang sesuai', '<p>Mahasiswa tidak mampu<br>menjelaskan hubungan trias<br>epidemiologi</p>', '<p>Mahasiswa mampu menjelaskan<br>hubungan 1 komponen trias<br>epidemiologi dengan tepat</p>', '<p>Mahasiswa mampu menjelaskan<br>hubungan 2 komponen trias<br>epidemiologi dengan tepat</p>', '<p>Mahasiswa mampu menjelaskan hubungan<br>3 komponen trias epidemiologi dengan<br>tepat dan lengkap.</p><ul><li>Faktor Agent</li><li>Faktor Host</li><li>Faktor Lingkungan</li></ul>', 1, 1, 1, 1, 1, '2025-08-15 10:57:01', '2025-08-15 13:54:33');
