INSERT INTO `orubriks` VALUES (12, 11, 2, 'Penjelasan hubungan trias epidemiologi yang sesuai', '<p>Mahasiswa tidak mampu<br>menjelaskan hubungan trias<br>epidemiologi</p>', '<p>Mahasiswa mampu menjelaskan<br>hubungan 1 komponen trias<br>epidemiologi dengan tepat</p>', '<p>Mahasiswa mampu menjelaskan<br>hubungan 2 komponen trias<br>epidemiologi dengan tepat</p>', '<p>Mahasiswa mampu menjelaskan hubungan<br>3 komponen trias epidemiologi dengan<br>tepat dan lengkap.</p><ul><li>Faktor Agent</li><li>Faktor Host</li><li>Faktor Lingkungan</li></ul>', 1, 1, 1, 1, 1, '2025-08-27 10:15:47', '2025-08-27 10:15:47');
INSERT INTO `orubriks` VALUES (21, 15, 1, 'Penjelasan Patomekanisme', '<p>Mahasiswa tidak  mampu menjelaskan patomekanisme Diagnosis kerja&nbsp;</p>', '<p>Mahasiswa mampu menjelaskan secara <b>tepat</b> patomekanisme diagnosis kerja meliputi : \n</p><p><b>A.	Faktor Risiko (salah satu)\n</b></p><p><b>B.	Patomekanisme (salah satu)\n</b></p><p><br></p>', '<p>Mahasiswa mampu menjelaskan secara <b>tepat</b> patomekanisme diagnosis kerja meliputi :\n</p><p><b>A.	Faktor Risiko \n</b></p><p>-	Asupan lemak berlebih\n</p><p>-	Kurang aktivitas fisik\n</p><p><b>B.	Patomekanisme \n</b></p><p>1)	Asupan lemak berlebih \n</p><p>Penyerapan di usus (intake) dan obesitas visceral &gt; peningkatan sintesis VLDL di hepar &gt; LDL sirkulasi meningkat &gt; kolesterol plasma meningkat &gt; menghambat pembentukan HDL\n</p><p>2)	Kurangnya aktivitas fisik &gt; aktivitas lipoprotein lipase menurun &gt; HDL menurun, trigliserida meningkat\n</p><p><br></p>', '<p>Mahasiswa mampu menjelaskan secara<b> tepat dan lengkap</b> patomekanisme diagnosis kerja, meliputi :\n</p><p><b>A.	Faktor Risiko\n</b></p><p>-	Asupan lemak berlebih\n</p><p>-	Kurang aktivitas fisik\n</p><p><b>B.	Patomekanisme\n</b></p><p>1)	Asupan lemak berlebih \n</p><p>A.	Penyerapan di usus &gt; diangkut sebagai kilomikron ke hepar &gt; peningkatan sintesis VLDL di hepar &gt; LDL di sirkulasi  &gt; kolesterol plasma meningkat &gt; menghambat pembentukan HDL &gt; HDL turun\n</p><p>B.	Obesitas visceral &gt; jaringan lemak visceral banyak &gt; FFA meningkat &gt; peningkatan sintesis VLDL di hepar &gt; LDL di sirkulasi  &gt; kolesterol plasma meningkat &gt; menghambat pembentukan HDL &gt; HDL turun\n</p><p>2)	Kurangnya aktivitas fisik &gt; aktivitas lipoprotein lipase menurun &gt; HDL menurun, trigliserida meningkat\n</p><p><br></p>', 1, 1, 1, 1, 1, '2025-10-31 09:12:31', '2025-10-31 12:33:46');
INSERT INTO `orubriks` VALUES (22, 15, 2, 'Penentuan Tatalaksana Farmakologi', '<p>Mahasiswa tidak  mampu menentukan obat yang tepat</p>', '<p>Mahasiswa mampu menentukan  tatalaksana farmakologi secara <b>tidak lengkap</b>, namun <b>tetap meliputi</b> :\n</p><p>\n</p><p><b>1.	Jenis obat\n</b></p><p><b>2.	Mekanisme kerja obat\n</b></p><p><br></p>', '<p>Mahasiswa mampu menentukan  obat secara <b>tepat</b>, namun <b>tidak lengkap</b> :\n</p><p>\n</p><p>\n</p><p><b>1.	Jenis obat dan dosis\n</b></p><p><b>2.	Mekanisme kerja obat\n</b></p><p>\n</p><p>Penghambatan kompetitif HmGCoA reduktase &gt; penurunan produksi mevalonate \n</p><p>A.	Penurunan sintesis VLDL &gt; Penurunan TG\n</p><p>B.	Peningkatan produksi apoA1 &gt; Peningkatan HDL\n</p><p>C.	Penurunan konsentrasi kolesterol di hepar &gt; penurunan LDL\n</p><p><br></p>', '<p>Mahasiswa mampu menentukan  tatalaksana farmakologi secara <b>tepat dan lengkap</b>, meliputi indikasi dan dosis, yaitu :</p><p><b>1. Jenis obat dan dosis</b></p><p><b>2. Mekanisme kerja obat</b></p><p>\n</p><p>Penghambatan kompetitif HmGCoA reduktase &gt; penurunan produksi mevalonate \n</p><p>A.	Penurunan produksi apolipoprotein B-100 &gt; penurunan sintesis VLDL &gt; Penurunan TG\n</p><p>B.	Peningkatan produksi apoA1 &gt; Peningkatan HDL\n</p><p>C.	Penurunan kolesterol di hepar &gt; peningkatan ekspresi reseptor LDL di hepar &gt; penurunan LDL\n</p><p><br></p>', 1, 1, 1, 1, 1, '2025-10-31 09:12:31', '2025-10-31 12:33:46');
INSERT INTO `orubriks` VALUES (23, 16, 1, 'Penjelasan Patomekanisme', '<p>Mahasiswa tidak&nbsp; mampu menjelaskan patomekanisme diagnosis kerja&nbsp;</p>', 'Mahasiswa mampu menjelaskan patomekanisme diagnosis kerja dari faktor resiko secara tepat namun tidak lengkap<p><br></p>', 'Mahasiswa mampu menjelaskan patomekanisme diagnosis kerja dari faktor resiko secara tepat namun tidak lengkap&nbsp;<br><br>A.&nbsp; &nbsp; Faktor resiko : Obesitas&nbsp;<br>B.&nbsp; &nbsp; Patomekanisme&nbsp;<br>1.&nbsp; &nbsp; Obesity&nbsp;&nbsp;<br>2.&nbsp; &nbsp; Resisten insulin &gt; lipolysis pada jaringan adiposa &gt;&nbsp; asam lemak bebas ke aliran darah&nbsp;<br>3.&nbsp; &nbsp; Masuknya asam lemak bebas ke liver &gt; sintesis TG dan VLDL meningkat &gt; dislipidemia.&nbsp;<br><br>', '<p>Mahasiswa mampu menjelaskan secara tepat, lengkap dan sistematis patomekanisme diagnosis kerja dari faktor resiko :<br>A.&nbsp; &nbsp; Faktor Resiko&nbsp;<br>-&nbsp; &nbsp; Usia&nbsp;<br>-&nbsp; &nbsp; Obesitas&nbsp;<br>-&nbsp; &nbsp; Hipertensi&nbsp;<br><br>B.&nbsp; &nbsp; Patomekanisme&nbsp;<br>1.&nbsp; &nbsp; Obesity &gt; Pro Inflammatory TN-a, IL6, NCV1 &gt; adinopektin&nbsp;<br>2.&nbsp; &nbsp; Resisten insulin &gt; lipolysis pada jaringan adiposa &gt; asam lemak bebas ke aliran darah&nbsp;<br>3.&nbsp; &nbsp; Masuknya asam lemak bebas ke liver &gt; sintesis TG dan VLDL meningkat &gt; dislipidemia.&nbsp;<br><br></p>', 1, 1, 1, 1, 1, '2025-10-31 09:34:23', '2025-10-31 09:52:31');
INSERT INTO `orubriks` VALUES (24, 16, 2, 'Penentuan Tatalaksana Farmakologi', '<p>Mahasiswa tidak&nbsp; mampu menjelaskan tatalaksana farmakologi</p>', 'Mahasiswa mampu menentukan tatalaksana farmakologi dengan tepat dan tidak lengkap meliputi :<br>1.&nbsp; &nbsp; Jenis obat<br>2.&nbsp; &nbsp; &nbsp;mekanisme kerja obat<br><br><p><br></p>', 'Mahasiswa mampu menentukan tatalaksana farmakologi dengan tidak lengkap meliputi:<br><br>A.&nbsp; &nbsp; Jenis obat dan dosis&nbsp;<br>Atorvastatin 1x40mg atau&nbsp;<br>Rosuvastatin 1x20mg&nbsp;<br>B.&nbsp; &nbsp; Mekanisme kerja obat:&nbsp;<br>Penghambatan kompetitif reductase HMG-Coa &gt;<br>1.&nbsp; &nbsp; penurunan sintesis VLDL &gt; penurunan TG&nbsp;&nbsp;<br>2.&nbsp; &nbsp; &nbsp;peningkatan produksi apoA1 &gt; peningkatan HDL<br>3.&nbsp; &nbsp; penurunan konsentrasi kolesterol di hepar &gt;penurunan LDL&nbsp;<br><br>', 'Mahasiswa mampu menentukan tatalaksana farmakologi dengan tepat dan lengkap meliputi:<br><br>A.&nbsp; &nbsp; Jenis obat dan dosis&nbsp;<br>Atorvastatin 1x40mg atau&nbsp;<br>Rosuvastatin 1x20mg&nbsp;<br>B.&nbsp; &nbsp; Mekanisme kerja obat: Penghambatan kompetitif reductase HMG-Coa &gt; penurunan produksi mevalonate :<br>1.&nbsp; &nbsp; penurunan produksi apolipoprotein B-100 &gt; penurunan sintesis VLDL &gt;penurunan TG&nbsp;&nbsp;<br>2.&nbsp; &nbsp; &nbsp;peningkatan produksi apoA1 &gt; peningkatan HDL&nbsp;<br>3.&nbsp; &nbsp; &nbsp;penurunan konsentrasi kolesterol di hepar &gt; peningkatan ekspresi reseptor LCL di hepar &gt; penurunan LDL&nbsp;', 1, 1, 1, 1, 1, '2025-10-31 09:34:23', '2025-10-31 09:52:31');
INSERT INTO `orubriks` VALUES (25, 17, 1, 'Penjelasan Patomekanisme', '<p>Mahasiswa tidak  mampu menjelaskan patomekanisme Diagnosis kerja&nbsp;</p>', '<p>Mahasiswa mampu menjelaskan patomekanisme diagnosis kerja secara <b>tidak lengkap&nbsp;</b></p>', '<p>Mahasiswa mampu menjelaskan secara <b>tepat </b>patomekanisme diagnosis kerja meliputi :\n</p><p>\n</p><p>Dislipidemia &gt; LDL masuk ke pembuluh dinding pembuluh darah &gt; teroksidasi jadi ox-LDL &gt; disfungsi endotel\n</p><p>\n</p><p>Dan salah satu dari A atau B\n</p><p>\n</p><p><br></p>', '<p>Mahasiswa mampu menjelaskan secara <b>tepat dan lengkap</b> patomekanisme diagnosis kerja, meliputi :\n</p><p>Dislipidemia &gt; LDL masuk ke pembuluh dinding pembuluh darah &gt; teroksidasi jadi ox-LDL &gt; disfungsi endotel<br></p><p>A.	Aktivasi RAAS &gt; peningkatan volume darah dan tekanan arteri &amp; tahanan perifer vaskuler meningkat &gt; hipertensi \n</p><p>B.	Peningkatan endothelin-1 &amp; ROS &gt; vasokontriksi meningkat &gt; peningkatan angiotensin II &gt; peningkatan aldosteron +retensi NA &amp; H2O &gt; hipertensi\n</p><p><br></p>', 1, 1, 1, 1, 1, '2025-10-31 09:40:04', '2025-10-31 11:55:49');
INSERT INTO `orubriks` VALUES (26, 17, 2, 'Penentuan Tatalaksana Farmakologi', '<p>Mahasiswa tidak  mampu menentukan tatalaksana farmakologi yang tepat</p>', '<p>Mahasiswa hanya mampu menentukan <b>salah satu golongan obat saja.\n</b></p><p>\n</p><p><br></p>', '<p>Mahasiswa mampu menentukan  tatalaksana farmakologi secara <b>tepat</b>, <b>namun tidak lengkap</b> :\n</p><p>\n</p><p>1.	Kombinasi golongan obat\n</p><p>2.	Mekanisme kerja obat\n</p><p>(mekanisme salah satu obat yang tepat)\n</p><p><br></p>', '<p>Mahasiswa mampu menentukan  tatalaksana farmakologi secara <b>tepat dan lengkap</b>, meliputi :\n</p><p>\n</p><p>1.	Kombinasi golongan obat\n</p><p>2.	Mekanisme kerja obat\n</p><p><br></p>', 1, 1, 1, 1, 1, '2025-10-31 09:40:04', '2025-10-31 11:55:49');
INSERT INTO `orubriks` VALUES (27, 18, 1, 'Penjelasan Patomekanisme', '<p>Mahasiswa tidak&nbsp; mampu menjelaskan patomekanisme Diagnosis kerja&nbsp;</p>', 'Mahasiswa mampu menjelaskan patomekanisme diagnosis kerja dari faktor resiko secara tepat namun tidak lengkap<br><br>A.&nbsp; &nbsp; Faktor resiko (1poin)<br>B.&nbsp; &nbsp; Mekanisme kerja tidak lengkap&nbsp;<br><br><p><br></p>', 'Mahasiswa mampu menjelaskan patomekanisme diagnosis kerja dari faktor resiko secara tepat namun tidak lengkap, meliputi :&nbsp;<br><br>A.&nbsp; &nbsp; Faktor Resiko ( 2 poin )&nbsp;<br>B.&nbsp; &nbsp; Mekanisme kerja :<br>1.&nbsp; &nbsp; Pola makan berlebihan, obesitas, kurang aktivitas yang menyebabkan penumpukan lemak viseral&nbsp;<br>2.&nbsp; &nbsp; Peningkatan FFA dan mediator inflamasi  resistensi insulin<br>3.&nbsp; &nbsp; Resistensi insulin dalam jangka waku lama -&gt; defisiensi insulin&nbsp;<br>4.&nbsp; &nbsp; Defisiensi insulin  Hiperglikemia&nbsp;<br><br><br>', '<p>Mahasiswa mampu menjelaskan secara tepat, lengkap dan sistematis patomekanisme diagnosis kerja dari faktor resiko :<br>A.&nbsp; &nbsp; Faktor Resiko&nbsp;<br>-&nbsp; &nbsp; Obesitas&nbsp;<br>-&nbsp; &nbsp; Pola Makan&nbsp;<br>-&nbsp; &nbsp; Aktivitas&nbsp;<br><br>B.&nbsp; &nbsp; Mekanisme kerja&nbsp;<br>1.&nbsp; &nbsp; Pola makan berlebihan, obesitas, kurang aktivitas yang menyebabkan penumpukan lemak viseral.&nbsp;<br>2.&nbsp; &nbsp; Lemak ini melepaskan adipokin dan asam lemak bebas (FFA) serta mediator inflamasi menjadi resistensi insulin .&nbsp;<br>3.&nbsp; &nbsp; Resistensi insulin dalam jangka waku lama -&gt; defisiensi insulin relative&nbsp;<br>4.&nbsp; &nbsp; Defisiensi insulin relative  Defisit Insulin Absolut  Hiperglikemia&nbsp;<br><br><br></p>', 1, 1, 1, 1, 1, '2025-10-31 09:55:04', '2025-10-31 10:13:45');
INSERT INTO `orubriks` VALUES (28, 18, 2, 'Penentuan Tatalaksana Farmakologi', '<p>Mahasiswa tidak&nbsp; mampu menjelaskan tatalaksana farmakologi&nbsp;</p>', 'Mahasiswa mampu menentukan tatalaksana farmakologi dengan tepat dan tidak lengkap meliputi :<br><br>A.&nbsp; &nbsp; Jenis obat dan dosis&nbsp;<br>Metformin Dosis : 3x500mg&nbsp;<br><br>B.&nbsp; &nbsp; mekanisme kerja obat&nbsp;<br>( 1 poin)<br><br><p><br></p>', 'Mahasiswa mampu menentukan tatalaksana dengan tepat tetapi tidak lengkap meliputi:<br>A. Jenis obat dan dosis&nbsp;<br>Metformin Dosis : 3x500mg&nbsp;<br>B. mekanisme kerja obat&nbsp;<br>(2 poin)<br><br>', 'Mahasiswa mampu menentukan tatalaksana farmakologi dengan tepat dan lengkap meliputi:<br>A.&nbsp; Jenis obat dan dosis&nbsp;<br>Metformin Dosis : 3x500mg&nbsp;<br>B.&nbsp; mekanisme kerja obat<br>1.&nbsp; &nbsp; Menghambat produksi glukosa di hati (glukoneogenesis)<br>2.&nbsp; &nbsp; Meningkatkan sensitivitas insulin di jaringan perifer<br>3.&nbsp; &nbsp; Menurunkan penyerapan glukosa di usus<br><br>', 1, 1, 1, 1, 1, '2025-10-31 09:55:04', '2025-10-31 10:13:45');
INSERT INTO `orubriks` VALUES (29, 19, 1, 'Penentuan Diagnosis', '<p>Mahasiswa tidak mampu menentukan Diagnosis&nbsp;</p>', '<p>Mahasiswa hanya mampu menentukan Diagnosis kerja dengan tepat <b>tanpa disertai dasar diagnosis\n</b></p><p>\n</p><p><b>Diagnosis : Hipotiroid ec GAKY\n</b></p><p>\n</p><p><br></p>', '<p>Mahasiswa mampu menentukan Diagnosis kerja yang <b>tepat</b> dengan Dasar diagnosis, meliputi :\n</p><p>\n</p><p><b>Diagnosis : Hipotiroid ec GAKY\n</b></p><p>\n</p><p><b>A.	Anamnesis\n</b></p><p><b>B.	Pemeriksaan Fisik\n</b></p><p><b>C.	Pemeriksaan Penunjang\n</b></p><p>-	TSH meningkat\n</p><p>-	fT4 menurun\n</p><p>-	iodium urin rendah</p>', '<p>Mahasiswa mampu menentukan diagnosis kerja disertai dengan dasar diagnosis yang <b>tepat</b> <b>dan</b> <b>lengkap</b> meliputi : \n</p><p>\n</p><p><b>Diagnosis : Hipotiroid ec GAKY\n</b></p><p>\n</p><p><b>A.	Anamnesis\n</b></p><p style=\"\">-	Benjolan di leher\n</p><p style=\"\">-	Mudah lelah\n</p><p style=\"\">-	Kulit kering\n</p><p style=\"\">-	Tidak tahan dingin\n</p><p style=\"\">-	Berat badan bertambah\n</p><p><b>B.	Pemeriksaan Fisik\n</b></p><p>-	Bradikardi\n</p><p>-	Teraba massa difus di leher yang ikut bergerak ketika menelan\n</p><p>-	Kulit kering\n</p><p><b>C.	Pemeriksaan Penunjang\n</b></p><p>-	TSH meningkat\n</p><p>-	fT4 menurun\n</p><p>-	iodium urin rendah\n</p><p>-	EKG : Sinus Bradikardi</p>', 1, 1, 1, 1, 1, '2025-10-31 09:58:57', '2025-10-31 11:58:06');
INSERT INTO `orubriks` VALUES (30, 19, 2, 'Penjelasan Patomekanisme', '<p>Mahasiswa tidak  mampu menjelaskan patomekanisme Diagnosis kerja&nbsp;</p>', '<p>Mahasiswa mampu menjelaskan secara <b>tepat</b> patomekanisme diagnosis kerja dihubungkan dengan:\n</p><p><b>A.	Etiologi : Defisiensi iodine\n</b></p><p><b>B.	Penurunan sekresi  T4 dan T3 dari kelenjar tiroid\n</b></p><p><b>C.	Manifestasi Klinis</b> <b>(1-2 poin)\n</b></p><p><br></p>', '<p>Mahasiswa mampu menjelaskan secara <b>tepat</b> patomekanisme diagnosis kerja dihubungkan dengan:\n</p><p><b>A.	Etiologi : Defisiensi iodine\n</b></p><p><b>B.	Penurunan sekresi  T4 dan T3 dari kelenjar tiroid\n</b></p><p><b>C.	Manifestasi Klinis (3-4 poin)</b></p>', '<p>Mahasiswa mampu menjelaskan secara <b>tepat</b> <b>dan</b> <b>lengkap</b> patomekanisme diagnosis kerja meliputi :\n</p><p><b>A.	Etiologi : Defisiensi iodine\n</b></p><p><b>B.	Penurunan sekresi  T4 dan T3 dari kelenjar tiroid\n</b></p><p><b>C.	Manifestasi Klinis \n</b></p><p>1)	Benjolan di leher \n</p><p>2)	Penurunan BMR (Mudah lelah, kulit kering, tidak tahan dingin, peningkatan BB)\n</p><p>3)	Bradikardi\n</p><p>4)	Peningkatan TSH\n</p><p>5)	Penurunan fT4\n</p><p><br></p>', 1, 1, 1, 1, 1, '2025-10-31 09:58:57', '2025-10-31 11:58:06');
INSERT INTO `orubriks` VALUES (31, 20, 1, 'Penentuan Diagnosis', '<p>Mahasiswa tidak mampu menentukan Diagnosis&nbsp;</p>', '<p>Mahasiswa hanya mampu menentukan Diagnosis kerja dengan tepat tanpa dasar diagnosis</p>', '<p>Mahasiswa mampu menentukan Diagnosis kerja yang tepat namun Dasar diagnosis tidak lengkap, meliputi :<br>A.&nbsp; &nbsp; Diagnosis kerja yang tepat<br>B.&nbsp; &nbsp; Dasar diagnosis yang tidak lengkap meliputi :&nbsp;<br>1.&nbsp; &nbsp; Anamnesis<br>2.&nbsp; &nbsp; Pemeriksaan Fisik<br>3.&nbsp; &nbsp; Pemeriksaan Penunjang<br>(TSH, FT4, FT3, Pemeriksaan histopatologi)&nbsp;<br><br></p>', '<p>Mahasiswa mampu menentukan diagnosis kerja disertai dengan dasar diagnosis yang tepat dan lengkap meliputi :&nbsp;<br>A.&nbsp; &nbsp; Diagnosis kerja yang tepat<br>B.&nbsp; &nbsp; Dasar diagnosis yang lengkap&nbsp;<br>meliputi :&nbsp;<br>1.&nbsp; &nbsp; Anamnesis<br>2.&nbsp; &nbsp; Pemeriksaan Fisik<br>3.&nbsp; &nbsp; Pemeriksaan Penunjang<br>(TSH, FT4, FT3, Pemeriksaan histopatologi, USG, Skintigrafi)&nbsp;</p>', 1, 1, 1, 1, 1, '2025-10-31 10:20:51', '2025-10-31 10:34:11');
INSERT INTO `orubriks` VALUES (32, 20, 2, 'Penjelasan Patomekanisme', '<p>Mahasiswa tidak&nbsp; mampu menjelaskan patomekanisme Diagnosis kerja&nbsp;</p>', '<p>Mahasiswa mampu menjelaskan patomekanisme sesuai dengan Diagnosis kerja dengan tepat meliputi salah satu:<br>A.&nbsp; &nbsp; Patomekanisme<br>B.&nbsp; &nbsp; Manifestasi Klinis 1-3<br><br></p>', '<p>Mahasiswa mampu menjelaskan secara tepat namun tidak lengkap patomekanisme diagnosis kerja dihubungkan dengan:<br>A.&nbsp; &nbsp; Patomekanisme<br>B.&nbsp; &nbsp; Manifestasi Klinis 4-5<br><br></p>', '<p>Mahasiswa mampu menjelaskan secara tepat dan lengkap patomekanisme diagnosis kerja:&nbsp;<br>A.&nbsp; &nbsp; Patomekanisme :&nbsp;<br>1.&nbsp; &nbsp; mutasi gen reseptor TSH (TSHR)<br>2.&nbsp; &nbsp; Sel folikuler tiroid menjadi hiperaktif dan proliferatif secara otonom<br>3.&nbsp; &nbsp; Umpan balik negatif ke hipofisis → penurunan TSH.<br>4.&nbsp; &nbsp; Penurunan TSH menyebabkan jaringan tiroid normal di sekitarnya menjadi inaktif, tapi nodul tetap aktif (“hot nodule”).<br><br>B.&nbsp; &nbsp; Manifestasi Klinis<br>1.&nbsp; &nbsp; Takikardi<br>2.&nbsp; &nbsp; Berat badan turun<br>3.&nbsp; &nbsp; Intoleransi panas<br>4.&nbsp; &nbsp; Berkeringat berlebihan<br>5.&nbsp; &nbsp; Palpitasi&nbsp;<br>6.&nbsp; &nbsp; Tremor&nbsp;<br><br></p>', 1, 1, 1, 1, 1, '2025-10-31 10:20:51', '2025-10-31 10:34:11');
INSERT INTO `orubriks` VALUES (33, 21, 1, 'Penentuan DIagnosis', '<p>Mahasiswa tidak mampu menentukan Diagnosis&nbsp;</p>', '<p>Mahasiswa hanya mampu menentukan Diagnosis kerja dengan tepat <b>tanpa disertai dasar diagnosis.\n</b></p><p>\n</p><p><b>Diagnosis : Anemia hemolitik ec malarial infection\n</b></p><p><b><br></b></p><p><b>Atau</b> anemia hemolitik saja\n</p><p>\n</p><p><br></p>', '<p>Mahasiswa mampu menentukan Diagnosis kerja yang <b>tepat</b> dengan Dasar diagnosis, meliputi :\n</p><p><b>Diagnosis : Anemia hemolitik ec malarial infection\n</b></p><p><b>A.	Anamnesis \n</b></p><p><b>B.	Pemeriksaan Fisik\n</b></p><p>1.	Sklera dan kulit ikterik\n</p><p>2.	Hepatosplenomegali\n</p><p><b>C.	Pemeriksaan Penunjang \n</b></p><p>1.	Anemia normositik normokrom \n</p><p>2.	Peningkatan bilirubin indirek (prehepatik).\n</p><p>3.	Urinalisis tampak urin gelap, hemoglobinuria +\n</p><p>4.	ADT tampak tropozoit muda berbentuk cincin tipis dan gametosit berbentuk sabit.\n</p><p><br></p>', '<p>Mahasiswa mampu menentukan diagnosis kerja disertai dengan dasar diagnosis yang <b>tepat</b> <b>dan</b> <b>lengkap</b> meliputi : \n</p><p><b>Diagnosis : Anemia hemolitik ec malarial infection\n</b></p><p><b>A.	Anamnesis\n</b></p><p>1.	Lemas, pucat yang merupakan gejala klinis anemia. \n</p><p>2.	Demam naik turun, diawali menggigil, lalu berkeringat setelah demam turun  trias malaria\n</p><p>3.	Urin gelap pekat seperti air teh\n</p><p><b>B.	Pemeriksaan fisik\n</b></p><p>1.	Kulit pucat\n</p><p>2.	Konjungtiva pucat\n</p><p>3.	Sklera dan kulit ikterik\n</p><p>4.	Hepatosplenomegali\n</p><p><b>C.	Pemeriksaan penunjang :\n</b></p><p>1.	Anemia normositik normokrom \n</p><p>2.	Retikulosit meningkat \n</p><p>3.	Peningkatan bilirubin indirek (prehepatik).\n</p><p>4.	Urinalisis tampak urin gelap, hemoglobinuria +\n</p><p>5.	ADT tampak tropozoit muda berbentuk cincin tipis dan gametosit berbentuk sabit.\n</p><p><br></p>', 1, 1, 1, 1, 1, '2025-10-31 10:32:01', '2025-10-31 12:03:49');
INSERT INTO `orubriks` VALUES (34, 21, 2, 'Penjelasan Patomekanisme', '<p>Mahasiswa tidak  mampu menjelaskan patomekanisme Diagnosis kerja&nbsp;</p>', '<p>Mahasiswa menjelaskan patomekanisme diagnosis kerja secara tidak lengkap.\n</p><p>\n</p><p>A.	Etiologi : Infeksi plasmodium\n</p><p>B.	Patomekanisme <b>(1 poin)\n</b></p><p>C.	Manifestasi Klinis <b>(1-3 poin)\n</b></p><p><br></p>', '<p>Mahasiswa mampu menjelaskan secara <b>tepat</b> patomekanisme diagnosis kerja dihubungkan dengan:\n</p><p>\n</p><p>A.	Etiologi : Infeksi plasmodium\n</p><p>B.	Patomekanisme <b>(2 poin)\n</b></p><p>C.	Manifestasi Klinis <b>(4-5 poin)\n</b></p><p><br></p>', '<p>Mahasiswa mampu menjelaskan secara <b>tepat</b> <b>dan</b> <b>lengkap</b> patomekanisme diagnosis kerja meliputi :\n</p><p><b>A.	Etiologi : Infeksi plasmodium\n</b></p><p><b>B.	Patomekanisme :\n</b></p><p>1.	Plasmodium berkembang dalam eritrosit &gt; memecah Hb menghasilkan hemozoin &gt; plasmodium matang &gt; eritrosit lisis \n</p><p>2.	Perubahan struktur membran eritrosit di sekitar &gt; rigiditas membran eritrosit menurun &gt; destruksi eritrosit di limpa\n</p><p>3.	Memicu aktivasi sistem imun berlebih &gt; terbentuk antibodi nonspesifik menempel pada eritrosit sehat &gt; destruksi eritrosit oleh makrofag di limpa dan hepar\n</p><p><b>C.	Manifestasi Klinis\n</b></p><p>1.	Lemas, kulit pucat, konjungtiva pucat +/+\n</p><p>2.	Sklera dan kulit ikterik\n</p><p>3.	Hepatosplenomegali\n</p><p>4.	Anemia normositik normokrom\n</p><p>5.	Bilirubin indirek meningkat\n</p><p>6.	Urin gelap (hemoglobinuria)</p>', 1, 1, 1, 1, 1, '2025-10-31 10:32:01', '2025-10-31 12:03:49');
INSERT INTO `orubriks` VALUES (35, 22, 1, 'Penentuan Diagnosis', '<p>Mahasiswa tidak mampu menentukan Diagnosis&nbsp;</p>', '<p>Mahasiswa hanya mampu menentukan Diagnosis kerja dengan tepat tanpa disertai dasar diagnosis</p>', '<p>Mahasiswa mampu menentukan Diagnosis kerja yang tepat dengan Dasar diagnosis tidak lengkap, meliputi :<br>A.&nbsp; &nbsp; Diagnosis kerja yang tepat<br>B.&nbsp; &nbsp; Dasar diagnosis yang lengkap&nbsp;<br>meliputi :&nbsp;<br>1.&nbsp; &nbsp; Anamnesis<br>2.&nbsp; &nbsp; Pemeriksaan Fisik<br>3.&nbsp; &nbsp; Pemeriksaan penunjang (HB, MCV,MCH,MCHC)<br><br><br></p>', 'Mahasiswa mampu menentukan diagnosis kerja disertai dengan dasar diagnosis yang tepat dan lengkap meliputi :&nbsp;<br>A.&nbsp; &nbsp; Diagnosis kerja yang tepat<br>B.&nbsp; &nbsp; Dasar diagnosis yang lengkap&nbsp;<br>meliputi :&nbsp;<br>1.&nbsp; &nbsp; Anamnesis<br>2.&nbsp; &nbsp; Pemeriksaan Fisik<br>3.&nbsp; &nbsp; Pemeriksaan penunjang', 1, 1, 1, 1, 1, '2025-10-31 10:35:15', '2025-10-31 10:44:30');
INSERT INTO `orubriks` VALUES (36, 22, 2, 'Penjelasan Patomekanisme', '<p>Mahasiswa tidak&nbsp; mampu menjelaskan patomekanisme Diagnosis kerja&nbsp;</p>', '<p>Mahasiswa mampu menjelaskan patomekanisme sesuai dengan Diagnosis kerja dengan tepat meliputi:<br>A.&nbsp; &nbsp; Faktor Risiko&nbsp;<br>B.&nbsp; &nbsp; Manifestasi Klinis ( 1-2 poin )<br><br></p>', '<p>Mahasiswa mampu menjelaskan secara tepat namun tidak lengkap patomekanisme diagnosis kerja dihubungkan dengan:<br>A.&nbsp; &nbsp; Faktor Risiko : CKD<br>B.&nbsp; &nbsp; Manifestasi Klinis (3 poin)<br><br></p>', '<p><br>Mahasiswa mampu menjelaskan secara tepat dan lengkap patomekanisme diagnosis kerja dihubungkan dengan:<br><br>A.&nbsp; &nbsp; Faktor Risiko : CKD&nbsp;<br>B.&nbsp; &nbsp; Manifestasi Klinis<br>1.&nbsp; &nbsp; Lemas&nbsp;<br>2.&nbsp; &nbsp; Sesak nafas<br>3.&nbsp; &nbsp; Kaki bengkak<br>4.&nbsp; &nbsp; Hb , MCV, MCH, MCHC&nbsp;</p>', 1, 1, 1, 1, 1, '2025-10-31 10:35:15', '2025-10-31 10:44:30');
INSERT INTO `orubriks` VALUES (37, 23, 1, 'Penentuan Diagnosis', '<p>Mahasiswa tidak mampu menentukan Diagnosis&nbsp;</p>', '<p>Mahasiswa hanya mampu menentukan Diagnosis kerja secara tepat tanpa dasar diagnosis&nbsp;<br><br>Adenocarcinoma prostat&nbsp;<br>Carcinoma prostat&nbsp;<br><br></p>', '<p>Mahasiswa mampu menentukan Diagnosis kerja yang tepat dan Dasar diagnosis yang tidak lengkap.<br><br>A.&nbsp; &nbsp; Diagnosis kerja yang tepat<br>B.&nbsp; &nbsp; Dasar diagnosis yang lengkap meliputi :&nbsp;<br>1.&nbsp; &nbsp; Anamnesis&nbsp;<br>2.&nbsp; &nbsp; Pemeriksaan Fisik<br>3.&nbsp; &nbsp; Pemeriksaan Penunjang&nbsp;<br><br></p>', 'Mahasiswa mampu menentukan diagnosis kerja disertai dengan dasar diagnosis yang tepat dan lengkap meliputi :&nbsp;<br>A.&nbsp; &nbsp; Diagnosis kerja yang tepat<br>B.&nbsp; &nbsp; Dasar diagnosis yang lengkap meliputi :&nbsp;<br>1.&nbsp; &nbsp; Anamnesis&nbsp;<br>2.&nbsp; &nbsp; Pemeriksaan Fisik&nbsp;<br>3.&nbsp; &nbsp; Pemeriksaan Penunjang<br>4.&nbsp; &nbsp; Grading dan staging&nbsp;<br><br>', 1, 1, 1, 1, 1, '2025-10-31 10:45:16', '2025-10-31 14:09:07');
INSERT INTO `orubriks` VALUES (38, 23, 2, 'Penjelasan Patomekanisme', '<p>Mahasiswa tidak&nbsp; mampu menjelaskan patomekanisme hallmarks of cancer&nbsp;</p>', '<p>Mahasiswa mampu menyebutkan secara tepat 1-2 poin patomekanisme hallmarks of cancer&nbsp;<br><br>1.&nbsp; &nbsp; Invasi basemt membran&nbsp;</p>', '<p>Mahasiswa mampu menyebutkan secara tepat, 3 poin patomekanisme patomekanisme hallmarks of cancer&nbsp;<br><br>1.&nbsp; &nbsp; Invasi basemt membran&nbsp;<br>2.&nbsp; &nbsp; Intravasasi ke pembuluh darah&nbsp;<br>3.&nbsp; &nbsp; Ekstravasasi ke pembuluh darah<br><br></p>', '<p>Mahasiswa mampu menyebutkan secara tepat&nbsp; poin patomekanisme patomekanisme hallmarks of cancer<br><br>1.&nbsp; &nbsp; Invasi basemt membran&nbsp;<br>2.&nbsp; &nbsp; Intravasasi ke pembuluh darah&nbsp;<br>3.&nbsp; &nbsp; Ekstravasasi ke pembuluh darah<br>4.&nbsp; &nbsp; Deposit membran&nbsp;<br><br><br></p>', 1, 1, 1, 1, 1, '2025-10-31 10:45:16', '2025-10-31 14:09:07');
INSERT INTO `orubriks` VALUES (39, 24, 1, 'Penegakkan Diagnosis', '<p>Mahasiswa tidak mampu menentukan Diagnosis&nbsp;</p>', '<p>Mahasiswa hanya mampu menentukan Diagnosis kerja dengan tepat <b>tanpa dasar diagnosis\n</b></p><p>\n</p><p><b>Atau \n</b></p><p>\n</p><p><b>Diagnosis kerja tidak lengkap </b>(adenocarcinoma paru)\n</p><p><br></p>', '<p>Mahasiswa mampu menentukan Diagnosis kerja yang<b> tepat </b>dengan<b> Dasar diagnosis yang tidak lengkap, </b>meliputi<b> :\n</b></p><p><b>Diagnosis : Adenocarcinoma paru yang telah bermetastasis ke hepar\n</b></p><p><b>A.	Anamnesis\n</b></p><p>1.	Batuk berdahak bercampur darah\n</p><p>2.	Penurunan berat badan\n</p><p><b>B.	Pemeriksaan Fisik\n</b></p><p>1.	IMT kurang\n</p><p>2.	Thoraks : \n</p><p>-	Fremitus menurun di lapang paru kanan bawah\n</p><p>-	Suara paru dextra redup hingga pekak\n</p><p><b>C.	Pemeriksaan Penunjang\n</b></p><p>1.	Pemeriksaan Rontgen Thorax: bayangan opak padat berukuran 6cm, tidak tampak perbesaran kelenjar getah bening.\n</p><p>2.	Pemeriksaan USG : ditemukan metastasis ke hepar\n</p><p>3.	Pemeriksaan Histopatologi : adenocarcinoma paru\n</p><p>\n</p><p><br></p>', '<p>Mahasiswa mampu menentukan diagnosis kerja disertai dengan dasar diagnosis yang <b>tepat dan lengkap </b>meliputi : \n</p><p><b>Diagnosis : Adenocarcinoma paru yang telah bermetastasis ke hepar\n</b></p><p><b>A.	Anamnesis\n</b></p><p>1.	Batuk berdahak bercampur darah\n</p><p>2.	Sesak napas\n</p><p>3.	Nyeri dada kanan\n</p><p>4.	Penurunan berat badan\n</p><p><b>B.	Pemeriksaan Fisik\n</b></p><p>1.	IMT kurang\n</p><p>2.	Takikardi\n</p><p>3.	Takipneu\n</p><p>4.	Konjungtiva pucat (+/+)\n</p><p>5.	Thoraks : \n</p><p>-	Fremitus menurun di lapang paru kanan bawah\n</p><p>-	Suara paru dextra redup hingga pekak\n</p><p><b>C.	Pemeriksaan Penunjang\n</b></p><p>1.	Pemeriksaan Rontgen Thorax: bayangan opak padat berukuran 6cm, tidak tampak perbesaran kelenjar getah bening\n</p><p>2.	Pemeriksaan USG : ditemukan metastasis ke hepar\n</p><p>3.	Pemeriksaan Histopatologi : adenocarcinoma paru\n</p><p><b>D.	Prinsip Dasar Staging\n</b></p><p>T : terdapat massa di paru sebesar 6cm\n</p><p>N : tidak tampak perbesaran KGB regional\n</p><p>M : mestastasis ke hepar\n</p><p><br></p><p><br></p>', 1, 1, 1, 1, 1, '2025-10-31 10:49:37', '2025-10-31 12:08:12');
INSERT INTO `orubriks` VALUES (40, 24, 2, 'Penjelasan Carcinogenesis', '<p>Mahasiswa tidak mampu menjelaskan carcinogenesis</p>', '<p>Mahasiswa mampu menjelaskan carcinogenesis namun <b>tidak sistematis</b></p>', '<p>Mahasiswa mampu menjelaskan carcinogenesis secara <b>tepat dan sistematis</b> meliputi : \n</p><p>1.	Carcinogenic agent (rokok)\n</p><p>2.	Inisiasi\n</p><p>3.	Promosi\n</p><p><br></p>', '<p>Mahasiswa mampu menjelaskan carcinogenesis secara <b>tepat</b>, <b>lengkap, dan sistematis</b> meliputi : \n</p><p>1.	Carcinogenic agent (rokok)\n</p><p>2.	Inisiasi : terjadi DNA adduct &gt; sel terinisiasi\n</p><p>3.	Promosi : sel terinisiasi &gt; proliferasi berulang &gt; terbentuk preneoplastic clone &gt; malignant clone <b>atau</b> menjelaskan Acquisition Hallmarks of Cancer dan Further Genetic Evolution\n</p><p><br></p>', 1, 1, 1, 1, 1, '2025-10-31 10:49:37', '2025-10-31 12:08:12');
INSERT INTO `orubriks` VALUES (41, 25, 1, 'Penentuan Diagnosis', '<p>Mahasiswa tidak mampu menentukan Diagnosis&nbsp;</p>', '<p>Mahasiswa hanya mampu menentukan Diagnosis kerja dengan tepat <b>tanpa disertai dasar diagnosis.\n</b></p><p><b>\nDiagnosis : Thalassemia mayor</b>&nbsp;</p><p>\n</p><p><b>Atau</b></p><p><b>diagnosis tidak lengkap </b>(Thalassemia)\n</p><p><br></p>', '<p>Mahasiswa mampu menentukan Diagnosis kerja yang <b>tepat </b>dengan Dasar diagnosis, meliputi :\n</p><p><b>\nDiagnosis : Thalassemia mayor&nbsp;</b></p><p><b>A.	Anamnesis \n</b></p><p><b>B.	Pemeriksaan fisik\n</b></p><p>1.	Hepatosplenomegali\n</p><p><b>C.	Pemeriksaan penunjang :\n</b></p><p>1.	Anemia hipokrom mikrositer\n</p><p>2.	HbF dominan : β-Thalassemia Mayor\n</p><p>\n</p><p>\n</p><p>\n</p><p><br></p>', '<p>Mahasiswa mampu menentukan diagnosis kerja disertai dengan dasar diagnosis yang <b>tepat dan lengkap </b>meliputi : \n</p><p><b>Diagnosis : Thalassemia mayor\n</b></p><p><b>A.	Anamnesis\n</b></p><p>1.	Pucat, lemas, cepat lelah \n</p><p>2.	Perut membesar\n</p><p>3.	Riwayat keluhan serupa dan mendapatkan transfusi\n</p><p>4.	Riwayat kakak pasien keluhan serupa (+)\n</p><p>5.	Anak lebih pendek dari teman usianya\n</p><p><b>B.	Pemeriksaan fisik\n</b></p><p>1.	Konjungtiva pucat \n</p><p>2.	Sklera ikterik\n</p><p>3.	Hepatosplenomegali \n</p><p>C.	Pemeriksaan <b>penunjang :\n</b></p><p>1.	Anemia hipokrom mikrositer\n</p><p>2.	Hiperbilirubinemia\n</p><p>3.	SADT : Target cell (+)\n</p><p>4.	HbF dominan : β-Thalassemia Mayor\n</p><p><br></p>', 1, 1, 1, 1, 1, '2025-10-31 11:23:48', '2025-10-31 11:43:40');
INSERT INTO `orubriks` VALUES (42, 25, 2, 'Penjelasan Patomekanisme', '<p>Mahasiswa tidak  mampu menjelaskan patomekanisme Diagnosis kerja&nbsp;</p>', '<p>Mahasiswa mampu menjelaskan patomekanisme diagnosis kerja secara<b> tidak lengkap.</b></p>', '<p>Mahasiswa mampu menjelaskan patomekanisme diagnosis kerja secara <b>tepat</b>, meliputi : \n</p><p><b>A.	Etiologi </b>: Mutasi / delesi pada gen β-globin (kromosom 11)\n</p><p><b>B.	Patomekanisme </b>:\n</p><p>1.	Berkurangnya atau tidak ada rantai β &gt; HbA turun drastis &gt; hipokrom mikrositer\n</p><p>2.	Tubuh mengompensasi dengan meningkatkan pembentukan hemoglobin &gt; HbF dan HbA meningkat (HbF dominan)\n</p><p>3.	Salah satu dari poin 3 atau 4\n</p><p><br></p>', '<p>Mahasiswa mampu menjelaskan patomekanisme diagnosis kerja secara <b>tepat dan lengkap </b>meliputi :\n</p><p><b>A.	Etiologi </b>: Mutasi / delesi pada gen β-globin (kromosom 11)\n</p><p><b>B.	Patomekanisme :\n</b></p><p>1.	Berkurangnya atau tidak ada rantai β &gt; HbA turun drastis &gt; hipokrom mikrositer\n</p><p>2.	Tubuh mengompensasi dengan meningkatkan pembentukan hemoglobin &gt; HbF dan HbA meningkat (HbF dominan)\n</p><p>3.	Rantai α berlebih mengendap di eritrosit membentuk inclusion bodies &gt; lisis eritrosit banyak  dihancurkan lien &gt; splenomegali &gt; heme yg terbentuk diubah jd bilirubin &gt; hiperbilirubinemia &gt; Sklera ikterik\n</p><p>4.	Hematopoiesis meningkat di hepar dan lien &gt; hepatosplenomegali \n</p><p><br></p>', 1, 1, 1, 1, 1, '2025-10-31 11:23:48', '2025-10-31 11:43:40');
INSERT INTO `orubriks` VALUES (43, 26, 1, 'Penjelasan Tumbuh Kembang Fetus', '<p>Mahasiswa tidak mampu menjelaskan tumbuh kembang fetus sesuai usia kehamilan&nbsp;</p>', '<p style=\"line-height: 1;\">Mahasiswa mampu menjelaskan tumbuh kembang fetus sesuai usia kehamilan secara <b>tepat,  1 dari 3 meliputi:\r\n</b></p><p style=\"line-height: 1;\">1.	Berat dan panjang\r\n</p><p style=\"line-height: 1;\">2.	Perkembangan organ\r\n</p><p style=\"line-height: 1;\">3.	Perkembangan fungsi organ\r\n</p><p><br></p>', '<p style=\"line-height: 1;\">Mahasiswa mampu menjelaskan tumbuh kembang fetus sesuai usia kehamilan secara <b>tepat, 2 dari 3 meliputi:\r\n</b></p><p style=\"line-height: 1;\">1.	Berat dan panjang\r\n</p><p style=\"line-height: 1;\">2.	Perkembangan organ\r\n</p><p style=\"line-height: 1;\">3.	Perkembangan fungsi organ\r\n</p><p><br></p>', '<p style=\"line-height: 1;\">Mahasiswa mampu menjelaskan tumbuh kembang fetus sesuai usia kehamilan secara tepat dan lengkap meliputi:\r\n</p><p style=\"line-height: 1;\">1.	Berat dan panjang\r\n</p><p style=\"line-height: 1;\">2.	Perkembangan organ\r\n</p><p style=\"line-height: 1;\">3.	Perkembangan fungsi organ</p>', 1, 1, 1, 1, 1, '2026-04-29 02:26:44', '2026-04-29 03:40:56');
INSERT INTO `orubriks` VALUES (44, 26, 2, 'Penjelasan Sirkulasi Fetomaternal', '<p>Mahasiswa tidak  mampu menjelaskan sirkulasi fetomaternal&nbsp;</p>', '<p style=\"line-height: 1;\">Mahasiswa mampu menjelaskan sirkulasi fetomaternal secara <b>tidak lengkap.</b>\r\n</p><p style=\"line-height: 1;\">\r\n</p><p style=\"line-height: 1;\">Plasenta --&gt; vena umbilikalis (&gt;&gt;O2) --&gt; ductus venosus\r\n</p><p style=\"line-height: 1;\"><br></p>', '<p>Mahasiswa mampu menjelaskan sirkulasi fetomaternal secara<b> tepat, namun tidak lengkap. \r\n</b></p><p>Plasenta --&gt; vena umbilikalis (&gt;&gt;O2) --&gt; ductus venosus --&gt;&nbsp;</p><p><b>Menjelaskan hanya 1 poin dari 2 poin \r\n</b></p><p><br></p>', '<p>Mahasiswa mampu menjelaskan sirkulasi fetomaternal secara tepat, lengkap, dan sistematis.\r\n</p><p>\r\nPlasenta --&gt; vena umbilikalis (&gt;&gt;O2) --&gt; ductus venosus --&gt; &nbsp;</p><p>1.	Atrium dextra --&gt; foramen ovale --&gt; atrium sinistra --&gt; ventrikel sinistra --&gt; aorta --&gt; seluruh tubuh\r\n</p><p>2.	Atrium dextra --&gt; ventrikel dextra --&gt; arteri pulmonalis --&gt; ductus arterious --&gt; aorta --&gt; seluruh tubuh --&gt; arteri hipogastrika --&gt; arteri umbilikalis --&gt; plasenta\r\n</p><p><br></p>', 1, 1, 1, 1, 1, '2026-04-29 02:26:44', '2026-04-29 03:40:56');
INSERT INTO `orubriks` VALUES (45, 27, 1, 'Penjelasan diagnosis dan dasar diagnosis', '<p>Mahasiswa tidak mampu menjelaskan intepretasi dan kesimpulan klinis dengan tepat.</p>', '<p>Mahasiswa mampu menjelaskan intepretasi dan kesimpulan klinis dengan<b> tepat namun tidak lengkap</b></p>', '<p style=\"line-height: 1;\">Mahasiswa mampu menjelaskan intepretasi dan kesimpulan klinis dengan <b>tepat,</b> meliputi :\r\n</p><p style=\"line-height: 1;\">-<b>	Diagnosis </b>: G1P0A0 usia kehamilan 39-40 minggu, janin tunggal hidup intrauterine, dengan Kala I partus lama et causa inersia uteri &nbsp;</p><p style=\"line-height: 1;\">-	<b>Dasar diagnosis lengkap&nbsp;</b></p><p style=\"line-height: 1;\"><br></p>', '<p style=\"line-height: 1;\">Mahasiswa mampu menjelaskan intepretasi dan kesimpulan klinis dengan<b> tepat dan lengkap</b>, meliputi :\r\n</p><p style=\"line-height: 1;\">-	<b>Diagnosis lengkap :</b> G1P0A0 usia kehamilan 39-40 minggu, janin tunggal hidup intrauterine, presentasi kepala, belum masuk PAP dengan Kala I partus lama et causa inersia uteri \r\n</p><p style=\"line-height: 1;\"><b>-	Dasar diagnosis lengkap&nbsp;</b></p>', 1, 1, 1, 1, 1, '2026-04-29 03:42:45', '2026-04-29 03:52:41');
INSERT INTO `orubriks` VALUES (46, 27, 2, 'Penjelasan Cardinal Movement', '<p>Mahasiswa tidak  mampu menjelaskan cardinal movement</p>', 'Mahasiswa mampu menjelaskan cardinal movement secara <b>tidak sistematis</b>', '<p>Mahasiswa mampu menjelaskan cardinal movement secara <b>tepat, sistematis, namun tidak lengkap (4-6 poin)</b></p>', '<p>Mahasiswa mampu menjelaskan cardinal movement secara <b>tepat, lengkap, dan sistematis (minimal 7 poin, meliputi nomor 2-8 di mini notes)</b></p>', 1, 1, 1, 1, 1, '2026-04-29 03:42:45', '2026-04-29 03:52:41');
INSERT INTO `orubriks` VALUES (47, 28, 1, 'Penjelasan Diagnosis dan Dasar Diagnosis', '<p>Mahasiswa tidak mampu menentukan Diagnosis&nbsp;</p>', '<p style=\"line-height: 1;\">Mahasiswa hanya mampu menentukan Diagnosis dengan<b> tepat </b>dengan Dasar diagnosis, meliputi :\r\n</p><p style=\"line-height: 1;\"><b><br></b><b>&nbsp;Diagnosis : Syok hipovolemik et causa ruptur uteri&nbsp;</b></p><p style=\"line-height: 1;\">\r\nA.	Anamnesis&nbsp;</p><p style=\"line-height: 1;\">B.	Pemeriksaan Fisik (1-3 poin)\r\n</p><p><br></p>', '<p style=\"line-height: 1;\">Mahasiswa mampu menentukan Diagnosis yang <b>tepat </b>dengan Dasar diagnosis, meliputi :\r\n</p><p style=\"line-height: 1;\"><b>Diagnosis : Syok hipovolemik et causa ruptur uteri&nbsp;</b></p><p style=\"line-height: 1;\"><b>Dasar Diagnosis : &nbsp;</b></p><p style=\"line-height: 1;\">A.	Anamnesis\r\n</p><p style=\"line-height: 1;\">B.	Pemeriksaan Fisik (4-6 poin)\r\n</p><p><br></p>', '<p style=\"line-height: 1;\">Mahasiswa mampu menentukan diagnosis disertai dengan dasar diagnosis yang<b> tepat dan lengkap meliputi : \r\n</b></p><p style=\"line-height: 1;\"><b>Diagnosis : Syok hipovolemik et causa ruptur uteri\r\n</b></p><p style=\"line-height: 1;\"><b>Dasar Diagnosis :\r\n</b></p><p style=\"line-height: 1;\">A.	Anamnesis\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">1.	Nyeri perut hebat mendadak\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">2.	Lemas, pusing\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">3.	Riwayat penarikan tali pusat kuat\r\n</p><p style=\"line-height: 1;\">B.	Pemeriksaan Fisik\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">1.	Hipotensi\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">2.	Takikardi\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">3.	Akral dingin, pucat\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">4.	Nyeri tekan hebat\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">5.	Distensi abdomen\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">6.	Uterus tidak jelas teraba\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">7.	Perdarahan per vaginam sedikit \r\n</p>', 1, 1, 1, 1, 1, '2026-04-29 03:54:57', '2026-05-05 01:07:30');
INSERT INTO `orubriks` VALUES (48, 28, 2, 'Penjelasan Patomekanisme', '<p>Mahasiswa tidak  mampu menjelaskan patomekanisme terjadinya manifestasi klinis</p>', '<p>Mahasiswa mampu menjelaskan secara tepat patomekanisme terjadinya manifestasi klinis namun <b>tidak lengkap</b></p>', '<p style=\"line-height: 1;\">Mahasiswa mampu menjelaskan secara <b>tepat</b> patomekanisme terjadinya manifestasi klinis dihubungkan dengan:\r\n</p><p style=\"line-height: 1;\">A.	Etiologi : Tarikan kuat tali pusat \r\n</p><p style=\"line-height: 1;\">B.	Robekan dinding uterus → hemoperitoneum → \r\n</p><p style=\"line-height: 1; margin-left: 25px;\">1)	Nyeri hebat\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">2)	Uterus sulit teraba\r\n</p><p style=\"line-height: 1;\">C.	Volume darah ↓ → CO ↓ → → perfusi jaringan ↓ \r\n</p><p style=\"line-height: 1; margin-left: 25px;\">1)	Hipotensi\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">2)	Takikardi\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">3)	Takipneu\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">4)	Akral dingin\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">5)	CRT &gt; 2 detik</p>', '<p style=\"line-height: 1;\">Mahasiswa mampu menjelaskan secara <b>tepat dan lengkap</b> patomekanisme terjadinya manifestasi klinis meliputi :\r\n</p><p style=\"line-height: 1;\">A.	Etiologi : Tarikan kuat tali pusat \r\n</p><p style=\"line-height: 1;\">B.	Robekan dinding uterus → pembuluh darah uteroplasenta robek → hemoperitoneum →\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">1)	 Nyeri hebat\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">2)	Uterus sulit teraba\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">3)	Distensi\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">4)	Darah sedikit di vagina\r\n</p><p style=\"line-height: 1;\">C.	 Volume darah ↓→ venous return ↓ → preload ↓ → CO ↓ → aktivasi simpatis dan RAAS → dekompensasi → perfusi jaringan ↓ →\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">1)	Hipotensi\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">2)	Takikardi\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">3)	Takipneu\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">4)	Akral dingin\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">5)	CRT &gt; 2 detik \r\n</p><p style=\"line-height: 1;\"><br></p>', 1, 1, 1, 1, 1, '2026-04-29 03:54:57', '2026-05-05 01:07:30');
INSERT INTO `orubriks` VALUES (49, 29, 1, 'Penjelasan Patomekanisme Risiko', '<p>Mahasiswa tidak  mampu menjelaskan patomekanisme risiko yang terjadi pada kasus</p>', '<p style=\"line-height: 1;\">&nbsp;Mahasiswa mampu menjelaskan patomekanisme risiko secara tepat, meliputi:\r\n</p><p style=\"line-height: 1;\">1.	Ibu hamil terpapar CMV\r\n</p><p style=\"line-height: 1;\">2.	Viremia → virus menembus barier plasenta dan masuk sirkulasi janin \r\n</p><p style=\"line-height: 1;\">3.	Komplikasi yang muncul <b>(1-2 poin)  \r\n</b></p><p style=\"line-height: 1;\"><br></p>', '<p style=\"line-height: 1;\">Mahasiswa mampu menjelaskan patomekanisme risiko secara tepat, meliputi: \r\n</p><p style=\"line-height: 1;\">1.	Ibu hamil terpapar CMV\r\n</p><p style=\"line-height: 1;\">2.	Viremia → virus menembus barier plasenta dan masuk sirkulasi janin \r\n</p><p style=\"line-height: 1;\">3.	Komplikasi yang muncul <b>(3-4 poin)  \r\n</b></p><p style=\"line-height: 1;\"><br></p>', '<p style=\"line-height: 1;\">Mahasiswa mampu menjelaskan patomekanisme risiko secara tepat, meliputi: \r\n</p><p style=\"line-height: 1;\">1.	Ibu hamil terpapar CMV\r\n</p><p style=\"line-height: 1;\">2.	Viremia → virus menembus barier plasenta dan masuk sirkulasi janin \r\n</p><p style=\"line-height: 1;\">3.	Komplikasi yang muncul <b>(5 poin)  \r\n</b></p><p style=\"line-height: 1; margin-left: 25px;\">1)	Sistem saraf pusat\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">2)	Sistem pendengaran (koklea)\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">3)	Mata \r\n</p><p style=\"line-height: 1; margin-left: 25px;\">4)	Hepar\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">5)	Sistem hematologi</p>', 1, 1, 1, 1, 1, '2026-04-29 04:07:10', '2026-04-29 04:13:50');
INSERT INTO `orubriks` VALUES (50, 29, 2, 'Pemeriksaan Screening', '<p>Mahasiswa tidak\r\n mampu menjelaskan screening bayi baru lahir pada kasus&nbsp;</p><p><br></p>', '<p>Mahasiswa mampu menjelaskan 3\r\n screening bayi baru lahir pada kasus secara tepat dan lengkap  <b>(1-2 poin)&nbsp;</b></p><p><br></p>', '<p>Mahasiswa mampu menjelaskan screening bayi baru lahir pada kasus secara <b>tepat dan lengkap (3-5 poin)</b></p>', '<p>Mahasiswa mampu menjelaskan screening bayi baru lahir pada kasus secara <b>tepat dan lengkap (6 poin)</b></p>', 1, 1, 1, 1, 1, '2026-04-29 04:07:10', '2026-04-29 04:13:50');
INSERT INTO `orubriks` VALUES (51, 30, 1, 'Penentuan Diagnosis', '<p>Mahasiswa tidak mampu menentukan Diagnosis&nbsp;</p>', '<p>Mahasiswa hanya mampu menentukan Diagnosis kerja disertai dasar diagnosis tidak lengkap</p>', '<p style=\"line-height: 1;\">Mahasiswa mampu menentukan Diagnosis kerja dengan tepat disertai Dasar diagnosis yang minimal, meliputi : \r\n</p><p style=\"line-height: 1;\"><b>\r\nDiagnosis kerja : Hepatitis B akut &nbsp;</b></p><p style=\"line-height: 1;\"><b>Dasar Diagnosis :&nbsp;</b></p><p style=\"line-height: 1;\">A.	Anamnesis (Bayi kuning, urin gelap seperti teh) </p><p style=\"line-height: 1;\">B.	Pemeriksaan Fisik (Ikterik) </p><p style=\"line-height: 1;\">C.	Pemeriksaan Penunjang (HbSAg (+))&nbsp;</p><p><br></p>', '<p style=\"line-height: 1;\">Mahasiswa mampu menentukan Diagnosis kerja dengan tepat disertai Dasar diagnosis yang tepat dan lengkap meliputi : \r\n</p><p style=\"line-height: 1;\"><b>Diagnosis kerja : Hepatitis B akut \r\n</b></p><p style=\"line-height: 1;\">A.	Anamnesis\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">1)	Bayi kuning\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">2)	Lemas\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">3)	Menyusu kurang kuat\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">4)	Urin gelap seperti teh\r\n</p><p style=\"line-height: 1;\">B.	Pemeriksaan Fisik\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">1)	Lemas\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">2)	Ikterik\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">3)	Refleks isap lemah\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">4)	Hepatomegali\r\n</p><p style=\"line-height: 1;\">\r\nC.	Pemeriksaan Penunjang&nbsp;</p><p style=\"line-height: 1; margin-left: 25px;\">1)	Hiperbilirubinemia direk\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">2)	SGOT dan SGPT meningkat\r\n</p><p style=\"line-height: 1; margin-left: 25px;\">3)	HbSAg (+)\r\n</p><p style=\"line-height: 1;\"><br></p>', 1, 1, 1, 1, 1, '2026-04-29 04:14:57', '2026-04-29 04:21:11');
INSERT INTO `orubriks` VALUES (52, 30, 2, 'Penjelasan Upaya Pencegahan', '<p>Mahasiswa tidak  mampu menjelaskan upaya pencegahan&nbsp;</p>', '<p>Mahasiswa mampu menjelaskan upaya pencegahan secara tepat namun tidak lengkap\r\n</p><p>\r\n</p><p>\r\n</p><p><br></p>', '<p style=\"line-height: 1;\">Mahasiswa mampu menjelaskan upaya pencegahan secara tepat dan lengkap, meliputi :\r\n</p><p style=\"line-height: 1;\">\r\n</p><p style=\"line-height: 1;\"><b>Masing-masing minimal 2 poin\r\n</b></p><p style=\"line-height: 1;\"><br></p><p style=\"line-height: 1;\">1)	Pencegahan pada ibu\r\n</p><p style=\"line-height: 1;\">2)	Pencegahan pada bayi\r\n</p><p style=\"line-height: 1;\">3)	Pencegahan pada komunitas\r\n</p><p style=\"line-height: 1;\"><br></p>', '<p style=\"line-height: 1;\">Mahasiswa mampu menjelaskan upaya pencegahan secara tepat dan lengkap, meliputi :\r\n</p><p style=\"line-height: 1;\">1)	Pencegahan pada ibu\r\n</p><p style=\"line-height: 1;\">2)	Pencegahan pada bayi\r\n</p><p style=\"line-height: 1;\">3)	Pencegahan pada komunitas\r\n</p><p style=\"line-height: 1;\"><br></p>', 1, 1, 1, 1, 1, '2026-04-29 04:14:57', '2026-04-29 04:21:11');
INSERT INTO `orubriks` VALUES (53, 31, 1, 'Penjelasan mekanisme sistem konduksi jantung pada kasus', '<p>Mahasiswa tidak mampu menjelaskan mekanisme sistem konduksi jantung pada kasus</p>', '<p>Mahasiswa menjelaskan mekanisme sistem konduksi jantung pada kasus <b>dengan tepat namun tidak lengkap dan tidak sistematis.</b></p>', '<p>Mahasiswa mampu menjelaskan mekanisme sistem konduksi jantung pada kasus <b>dengan tepat dan sistematis</b>, meliputi :\r\n</p><p>a.	Nodus SA (Sinoatrial) \r\n</p><p>b.	Nodus AV\r\n (Atrioventrikular) &nbsp;</p><p>c.	Berkas His\r\n</p><p>d.	Crus dextra dan sinistrum\r\n</p><p>e.	Serabut Purkinje\r\n</p>', '<p>Mahasiswa mampu menjelaskan mekanisme sistem konduksi jantung pada kasus dengan<b> tepat, lengkap dan sistematis.</b></p>', 1, 1, 1, 1, 1, '2026-04-29 04:36:02', '2026-05-06 06:03:57');
INSERT INTO `orubriks` VALUES (54, 31, 2, 'Penjelasan   agen kronotropik dan inotropik yang mempengaruhi kontraksi jantung', '<p>Mahasiswa tidak mampu menjelaskan  agen kronotropik dan inotropik yang mempengaruhi kontraksi jantung</p>', '<p>Mahasiswa mampu menjelaskan  agen kronotropik dan inotropik yang mempengaruhi kontraksi jantung <b>dengan tepat dan namun tidak lengkap.</b></p>', '<p>Mahasiswa mampu menjelaskan  agen kronotropik dan inotropik yang mempengaruhi kontraksi jantung <b>secara tepat dan lengkap</b>, meliputi :\r\n</p><p>-	Definisi dari:\r\n</p><p>a.	Inotropik positif \r\n</p><p>b.	Inotropik negatif \r\n</p><p>c.	Kronotropik positif \r\n</p><p>d.	Kronotropik negatif\r\n</p><p>-	Tanpa menyebutkan contoh zat \r\n</p>', '<p>Mahasiswa mampu  menjelaskan  agen kronotropik dan inotropik yang mempengaruhi kontraksi jantung <b>dengan tepat dan lengkap</b>, meliputi:\r\n</p><p>-	Definisi dari:\r\n</p><p>a.	Inotropik positif \r\n</p><p>b.	Inotropik negatif \r\n</p><p>c.	Kronotropik positif</p><p>d. Kronotropik Negatif</p>', 1, 1, 1, 1, 1, '2026-04-29 04:36:02', '2026-05-06 06:03:57');
INSERT INTO `orubriks` VALUES (55, 32, 1, 'Penjelasan mekanisme potensial aksi pada sel kontraktil	 sesuai kasus', '<p>Mahasiswa <b>tidak mampu</b> menjelaskan mekanisme potensial aksi pada sel kontraktil sesuai kasus</p>', '<p>Mahasiswa menjelaskan mekanisme potensial aksi pada sel kontraktil sesuai kasus dengan tepat namun penjelasan <b>tidak lengkap dan tidak sistematis</b>.</p>', '<p>Mahasiswa mampu menjelaskan mekanisme potensial aksi pada sel kontraktil sesuai kasus dengan <b>tepat dan sistematis namun penjelasan potensial aksi tidak lengkap. \r\n</b></p><p>Meliputi : \r\n</p><p><b>1.	Fase 0 : depolarisasi --&gt; Na+ masuk cepat</b></p><p><b>2.	Fase 1 : repolarisasi awal --&gt; K+ mulai keluar</b></p><p><b>3.	Fase 2 : plateu --&gt; Ca2+ masuk dan K+ keluar seimbang</b></p><p><b>4.	Fase 3 : repolarisasi cepat --&gt; Kanal Ca2+ menutup, K+ keluar</b></p><p><b>5.	Fase 4 : istirahat/resting state --&gt; Potensial stabil</b></p>', '<p>Mahasiswa mampu menjelaskan mekanisme potensial aksi pada sel kontraktil sesuai kasus dengan <b>tepat, lengkap dan sistematis.&nbsp;</b></p>', 1, 1, 1, 1, 1, '2026-04-29 04:44:23', '2026-04-29 04:50:40');
INSERT INTO `orubriks` VALUES (56, 32, 2, 'Penjelasan hormon yang meningkatkan sistem konduksi jantung', '<p>Mahasiswa<b> tidak mampu </b>menjelaskan hormon yang meningkatkan sistem konduksi jantung</p>', '<p>Mahasiswa mampu menjelaskan<b> 1 hormon </b>yang meningkatkan sistem konduksi jantung dengan<b> tepat dan lengkap.</b></p>', '<p>Mahasiswa mampu menjelaskan <b>2 hormon </b>yang meningkatkan sistem konduksi jantung dengan <b>tepat dan lengkap.\r\n</b></p><p>Atau \r\n</p><p>Mahasiswa mampu menjelaskan <b>3-4 hormon </b>yang meningkatkan sistem konduksi jantung dengan <b>tepat dan tidak lengkap.\r\n</b></p><p><br></p><p>\r\n</p><p>\r\n</p>', '<p>Mahasiswa mampu menjelaskan <b>3-4 hormon </b>yang meningkatkan sistem konduksi jantung dengan <b>tepat dan lengkap.\r\n</b></p><p><br></p><p>\r\n</p>', 1, 1, 1, 1, 1, '2026-04-29 04:44:23', '2026-04-29 04:50:40');
INSERT INTO `orubriks` VALUES (57, 33, 1, 'Penjelasan Mekanisme tahanan perifer yang terjadi pada kasus', '<p>Mahasiswa<b> tidak mampu </b>menjelaskan Mekanisme tahanan perifer yang terjadi pada kasus</p>', '<p>Mahasiswa menjelaskan Mekanisme tahanan perifer yang terjadi pada kasus dengan<b> tepat namun penjelasan tidak lengkap.</b></p>', '<p>Mahasiswa	mampu menjelaskan Mekanisme tahanan perifer yang terjadi pada kasus dengan <b>tepat dan lengkap</b> :</p><p><b>Jari- jari arteriol dipengaruhi :\r\n</b></p><p><b>-	Kontrol intrinsic (</b>respon miogenik <b>atau </b>perubahan metabolik lokal pada O2<b>)\r\n</b></p><p><b>-	Kontrol ekstrinsik (</b>aktivitas simpatik<b> atau </b>hormon epinefrin/norepinefrin<b>)\r\n</b></p><p><br></p><p>\r\n</p>', '<p>Mahasiswa mampu menjelaskan Mekanisme tahanan perifer yang terjadi pada kasus dengan <b>tepat dan lengkap</b> meliputi :\r\n</p><p><b>Jari- jari arteriol dipengaruhi :\r\n</b></p><p><b>-	Kontrol intrinsic (respon miogenik dan perubahan metabolik lokal pada O2)\r\n</b></p><p><b>-	Kontrol ekstrinsik (aktivitas simpatik dan hormon epinefrin dan norepinefrin)\r\n</b></p><p><br></p>', 1, 1, 1, 1, 1, '2026-04-29 04:52:57', '2026-04-29 04:57:40');
INSERT INTO `orubriks` VALUES (58, 33, 2, 'Penjelasan komponen darah yang mempengaruhi mekanisme tahanan perifer', '<p>Mahasiswa<b> tidak mampu</b> menjelaskan komponen darah yang mempengaruhi mekanisme tahanan perifer.</p>', '<p>Mahasiswa mampu menjelaskan <b>1-2 komponen darah</b> yang mempengaruhi mekanisme tahanan perifer.</p>', '<p>Mahasiswa mampu menjelaskan <b>3-4 komponen</b> darah yang mempengaruhi mekanisme tahanan perifer.</p>', '<p>Mahasiswa mampu menjelaskan <b>5 komponen</b> darah yang mempengaruhi mekanisme tahanan perifer.</p>', 1, 1, 1, 1, 1, '2026-04-29 04:52:57', '2026-04-29 04:57:40');
INSERT INTO `orubriks` VALUES (59, 34, 1, 'Penjelasan hubungan bunyi jantung dengan katup jantung', '<p>Mahasiswa <b>tidak mampu </b>menjelaskan hubungan bunyi jantung dengan katup jantung</p>', '<p>Mahasiswa hanya mampu menjelaskan <b>salah satu hubungan bunyi jantung dengan katup jantung dengan tepat.</b></p>', '<p>Mahasiswa mampu menjelaskan hubungan bunyi jantung dengan katup jantung  dengan<b> tepat dan lengkap.\r\n</b></p><p><b>a.	Bunyi jantung \r\n</b></p><p><b>b.	Katup \r\n</b></p><p><b>Tanpa menyebutan turbulensi aliran darah\r\n</b></p><p><br></p>', '<p>Mahasiswa mampu menjelaskan hubungan bunyi jantung dengan katup jantung  dengan <b>tepat dan lengkap.\r\n</b></p><p><br></p><p>\r\n</p>', 1, 1, 1, 1, 1, '2026-04-29 05:03:46', '2026-04-29 05:06:37');
INSERT INTO `orubriks` VALUES (60, 34, 2, 'Penjelasan mekanisme siklus jantung yang terjadi pada kasus', '<p>Mahasiswa <b>tidak mampu</b> menjelaskan mekanisme siklus jantung yang terjadi pada kasus</p>', '<p>Mahasiswa menjelaskan mekanisme siklus jantung yang terjadi pada kasus dengan <b>tepat namun tidak lengkap.</b></p>', '<p>Mahasiswa mampu menjelaskan mekanisme siklus jantung yang terjadi pada kasus dengan <b>tepat dan sistematis namun penjelasan tidak lengkap</b>. Meliputi : \r\n</p><p><b>1.	Diastole (pengisian ventrikel) : Darah mengalir dari atrium → ventrikel\r\n</b></p><p><b>2.	Atrial sistol: Atrium berkontraksi mendorong darah ke ventrikel\r\n</b></p><p><b>3.	Isovolumetric contraction: Ventrikel mulai kontraksi\r\n</b></p><p><b>4.	Ejection (ejeksi) : Darah keluar ke aorta &amp; arteri pulmonalis\r\n</b></p><p><b>5.	Isovolumetric relaxation : Ventrikel relaksasi\r\n</b></p><p><br></p>', '<p>Mahasiswa mampu menjelaskan mekanisme siklus jantung yang terjadi pada kasus dengan <b>tepat, lengkap dan sistematis.</b></p>', 1, 1, 1, 1, 1, '2026-04-29 05:03:46', '2026-04-29 05:06:37');
INSERT INTO `orubriks` VALUES (61, 35, 1, 'Penjelasan Mekanisme ventilasi paru yang sesuai dengan kasus', '<p>Mahasiswa<b> tidak mampu</b> menjelaskan Mekanisme ventilasi paru yang sesuai dengan kasus</p>', '<p>Mahasiswa menjelaskan Mekanisme ventilasi paru yang sesuai dengan kasus dengan tepat namun penjelasan <b>tidak lengkap dan tidak sistematis.</b></p>', '<p>Mahasiswa	mampu menjelaskan Mekanisme ventilasi paru yang sesuai dengan kasus dengan <b>tepat dan sistematis dengan penjelasan lengkap, meliputi : Inspirasi atau ekspirasi saja</b></p><p>atau \r\n</p><p><b>menjelaskan inspirasi dan ekspirasi namun tidak lengkap \r\n</b></p><p><br></p><p>\r\n</p><p>\r\n</p>', '<p>Mahasiswa mampu menjelaskan Mekanisme ventilasi paru yang sesuai dengan kasus dengan<b> tepat, lengkap dan sistematis.</b></p>', 1, 1, 1, 1, 1, '2026-04-29 05:11:59', '2026-04-29 05:14:24');
INSERT INTO `orubriks` VALUES (62, 35, 2, 'Penjelasan perbedaan struktur mikroskopis bronkus dan bronkiolus respiratorius', '<p>Mahasiswa <b>tidak mampu</b> menjelaskan perbedaan struktur mikroskopis bronkus dan bronkiolus respiratorius</p>', '<p>Mahasiswa	 mampu menjelaskan salah satu perbedaan struktur mikroskopis bronkus dan bronkiolus respiratorius dengan <b>tepat dan lengkap&nbsp;</b></p>', '<p>Mahasiswa mampu menjelaskan perbedaan struktur mikroskopis mikroskopis bronkus dan bronkiolus respiratorius dengan<b> tepat dan lengkap    :    \r\n</b></p><p><b>Minimal menyebutkan perbedaan epitel, lapisan muskularis dan tulang rawan.\r\n</b></p><p><br></p>', '<p>Mahasiswa mampu menjelaskan perbedaan struktur mikroskopis bronkus dan bronkiolus respiratorius dengan<b> tepat dan lengkap&nbsp;</b></p>', 1, 1, 1, 1, 1, '2026-04-29 05:11:59', '2026-04-29 05:14:24');
INSERT INTO `orubriks` VALUES (63, 36, 1, 'Penjelasan  mekanisme aliran balik vena yang terjadi pada kasus', '<p>Mahasiswa tidak mampu menjelaskan  mekanisme aliran balik vena yang terjadi pada kasus&nbsp;</p>', '<p>Mahasiswa menjelaskan mekanisme  mekanisme aliran balik vena yang terjadi pada kasus <b>dengan tepat namun tidak lengkap dan tidak sistematis</b>.</p>', '<p>Mahasiswa mampu menjelaskan  mekanisme aliran balik vena yang terjadi pada kasus dengan tepat dan sistematis :\r\n</p><p>a.	Saat duduk lama : Tidak ada kontraksi otot rangka → <b>muscle pump tidak aktif</b> → ↑ tekanan hidrostatik kapiler → cairan keluar ke interstisial\r\n</p><p>b.	Saat aktivitas : Otot berkontraksi → <b>katup vena mencegah aliran balik</b> → ↑ venous return\r\n</p>', '<p>Mahasiswa mampu menjelaskan  mekanisme aliran balik vena yang terjadi pada kasus <b>dengan tepat, lengkap dan sistematis.</b></p>', 1, 1, 1, 1, 1, '2026-04-29 05:14:01', '2026-04-29 05:24:00');
INSERT INTO `orubriks` VALUES (64, 36, 2, 'Penjelasan    perbedaan struktur mikroskopis arteri besar, arteri sedang dan arteri kecil', '<p>Mahasiswa tidak mampu menjelaskan   perbedaan struktur mikroskopis arteri besar, arteri sedang dan arteri kecil</p>', '<p>Mahasiswa mampu menjelaskan   perbedaan struktur mikroskopis arteri besar, arteri sedang dan arteri kecil <b>dengan tepat dan namun tidak lengkap.</b></p>', '<p>Mahasiswa mampu  perbedaan struktur mikroskopis arteri besar, arteri sedang dan arteri kecil  secara tepat dan lengkap.\r\n</p><p><b>Meliputi : 2 dari 3 lapisan \r\n</b></p>', '<p>Mahasiswa mampu  menjelaskan   perbedaan struktur mikroskopis arteri besar, arteri sedang dan arteri kecil <b>dengan tepat dan lengkap</b>.</p>', 1, 1, 1, 1, 1, '2026-04-29 05:14:01', '2026-04-29 05:24:00');
INSERT INTO `orubriks` VALUES (65, 37, 1, 'Penjelasan mekanisme pengaturan pernafasan', '<p>Mahasiswa <b>tidak mampu</b> menjelaskan mekanisme pengaturan pernafasan&nbsp;</p>', '<p>Mahasiswa menjelaskan mekanisme pengaturan pernafasan dengan <b>tepat namun tidak lengkap.</b></p>', '<p>Mahasiswa mampu menjelaskan mekanisme pengaturan pernafasan dengan tepat dan sistematis namun tidak lengkap.\r\n</p><p><b>a.	Hipoventilasi -&gt; Peningkatan PCO2 -&gt; asidosis \r\n</b></p><p><b>b.	Deteksi oleh kemoreseptor:\r\n</b></p><ul><li><b>Kemoreseptor sentral\r\n</b></li><li><b>Kemoreseptor perifer \r\n</b></li></ul><p><b>c.	Stimulasi pusat respirasi (medula dan pons) -&gt; aktivasi N. Phrenicus dan N. Interkostalis -&gt; Hiperventilasi \r\n</b></p><p><b>d.	Eliminasi CO2 meningkat -&gt; Kompensasi\r\n</b></p><p><br></p>', '<p>Mahasiswa mampu menjelaskan mekanisme pengaturan pernafasan dengan <b>tepat, lengkap dan sistematis.\r\n</b></p><p><br></p><p>\r\n</p>', 1, 1, 1, 1, 1, '2026-04-29 05:19:21', '2026-04-29 05:23:52');
INSERT INTO `orubriks` VALUES (66, 37, 2, 'Penjelasan komponen keseimbangan asam basa dan perannya', '<p>Mahasiswa<b> tidak mampu </b>menjelaskan komponen keseimbangan asam basa dan perannya</p>', '<p>Mahasiswa mampu menjelaskan <b>1 komponen</b> keseimbangan asam basa dan perannya dengan <b>tepat dan lengkap.\r\n</b></p><p>Atau\r\n</p><p><b>Hanya menyebutkan 4 komponen tanpa menjelasan perannya \r\n</b></p><p><br></p><p>\r\n</p><p>\r\n</p><p>\r\n</p>', '<p>Mahasiswa mampu menjelaskan <b>2-3 komponen</b> keseimbangan asam basa dan perannya dengan <b>tepat dan lengkap.</b></p>', '<p>Mahasiswa mampu menjelaskan <b>4 komponen</b> keseimbangan asam basa dan perannya <b>tepat dan lengkap. \r\n</b></p><p><br></p><p>\r\n</p><p>\r\n</p>', 1, 1, 1, 1, 1, '2026-04-29 05:19:21', '2026-04-29 05:23:52');
INSERT INTO `orubriks` VALUES (67, 38, 1, 'Penjelasan mekanisme pengaturan pompa jantung pada kasus', '<p>Mahasiswa tidak mampu menjelaskan   mekanisme pengaturan pompa jantung pada kasus&nbsp;</p>', '<p>Mahasiswa menjelaskan mekanisme   mekanisme pengaturan pompa jantung pada kasus <b>dengan tidak tepat dan tidak lengkap</b>.</p>', '<p>Mahasiswa mampu menjelaskan   mekanisme pengaturan pompa jantung pada kasus <b>dengan tepat namun tidak lengkap</b> :\r\n</p><p>a.	Mekanisme intrinsik \r\n</p><p>-	Frank starling</p><p>b.	Mekanisme ekstrinsik \r\n</p><p>-	Saraf otonom : saraf simpatis meningkatkan denyut jantung, saraf parasimpatis menurunkan denyut jantung\r\n</p><p>-	Pengaturan kimiawi dan hormonal : epinefrin meningkatan denyut jantung\r\n</p><p><br></p>', '<p>Mahasiswa mampu menjelaskan   mekanisme pengaturan pompa jantung pada kasus <b>dengan tepat, lengkap dan sistematis.</b></p>', 1, 1, 1, 1, 1, '2026-04-29 05:36:47', '2026-05-06 03:21:55');
INSERT INTO `orubriks` VALUES (68, 38, 2, 'Penjelasan struktur makroskopis ruang dan katup jantung', '<p>Mahasiswa <b>tidak mampu</b>  struktur makroskopis ruang dan katup jantung.</p>', '<p>Mahasiswa mampu menjelaskan   perbedaan  struktur makroskopis ruang dan katup jantung <b>dengan tepat dan namun tidak lengkap</b>.</p>', '<p>Mahasiswa mampu  menjelaskan struktur makroskopis ruang dan katup jantung  <b>secara tepat dan lengkap</b>, meliputi :\r\n</p><p>- ruang jantung \r\n</p><p>a. atrium dextra dan sinistra = sinus venarum dan M. Pectinati\r\n</p><p>b. ventriculus dextra dan sinistra = terdapat M. Papillaris dan chorda tendinea\r\n</p><p>- katup jantung :\r\n</p><p>a. valva AV dextra / trikuspid terdiri dari 3 cuspis.\r\n</p><p>b. valva AV sinistra / mitral terdiri dari 2 cuspis \r\n</p><p>c. valva Semilunar ( trunci pulmonal dan aorta terdiri dari 3 valvula)\r\n</p>', '<p>Mahasiswa mampu  menjelaskan    struktur makroskopis ruang dan katup jantung <b>dengan tepat dan lengkap.</b></p>', 1, 1, 1, 1, 1, '2026-04-29 05:36:47', '2026-05-06 03:21:55');
INSERT INTO `orubriks` VALUES (69, 39, 1, 'Penjelasan mekanisme pertukaran gas pada kasus', '<p>Mahasiswa <b>tidak mampu</b>  mekanisme pertukaran gas pada kasus.</p>', '<p>Mahasiswa mampu menjelaskan  mekanisme pertukaran gas pada kasus <b>dengan tidak tepat dan tidak sistematis.</b></p>', '<p>Mahasiswa mampu menjelaskan    mekanisme pertukaran gas pada kasus <b>dengan tepat dan sistematis </b>:\r\n</p><p>a.	Kontrol volunter oleh korteks serebri\r\n</p><p>b.	Ventilasi meningkat : &nbsp;↑ volume tidal\r\n</p><p>c.	Pertukaran gas meningkat di alveolus : ↑O2 masuk dan ↓ CO2 keluar\r\n</p><p>d.	Oksigenasi jaringan : ↑ suplai O2 ke jaringan.\r\n</p><p><br></p>', '<p>Mahasiswa mampu menjelaskan mekanisme pertukaran gas pada kasus&nbsp;<b>dengan tepat, lengkap dan sistematis.</b></p>', 1, 1, 1, 1, 1, '2026-04-29 06:28:47', '2026-05-08 06:14:49');
INSERT INTO `orubriks` VALUES (70, 39, 2, 'Penjelasan 3 otot yang berperan dalam proses inspirasi (nama otot dan inervasi)', '<p>Mahasiswa <b>tidak mampu</b>  menjelaskan 3 otot yang berperan dalam proses inspirasi (nama otot dan inervasi)</p>', '<p>Mahasiswa mampu menjelaskan   3 otot yang berperan dalam proses inspirasi (nama otot dan inervasi)\r\n <b>dengan tidak tepat.&nbsp;</b></p>', '<p>Mahasiswa mampu  menjelaskan 3 otot yang berperan dalam proses inspirasi (nama otot dan inervasi) <b>secara tepat,</b> meliputi :\r\n</p><p>Otot inspirasi utama \r\n</p><p>a.	Diaphragma (N. Phrenicus)\r\n</p><p>b.	M. intercostalis externus ( Nn. Intercostales)\r\n</p><p>c.	M. intercostalis intimus ( Nn. Intercostales)\r\n</p><p><br></p>', '<p>Mahasiswa mampu  menjelaskan 3 otot yang berperan dalam proses inspirasi (nama otot dan inervasi) <b>dengan tepat dan lengkap.</b></p>', 1, 1, 1, 1, 1, '2026-04-29 06:28:47', '2026-05-08 06:14:49');
INSERT INTO `orubriks` VALUES (71, 40, 1, 'Penjelasan mekanisme pengaturan pernafasan pada kasus', '<p>Mahasiswa <b>tidak mampu </b>  mekanisme  pengaturan pernafasan pada kasus</p>', '<p>Mahasiswa mampu menjelaskan   mekanisme  pengaturan pernafasan pada kasus <b>dengan tidak tepat dan tidak sistematis.</b></p>', '<p>Mahasiswa mampu menjelaskan mekanisme  pengaturan pernafasan pada kasus <b>dengan tepat dan sistematis</b> :\r\n</p><p>1.	Pusat pengaturan pernapasan\r\n</p><ul><li>Medula oblongata → membentuk ritme dasar napas\r\n</li><li>Pons (PRG) → mengatur transisi inspirasi–ekspirasi (menghaluskan ritme napas)\r\n</li></ul><p>2.	Jalur impuls saraf\r\n</p><ul><li>Impuls dari medula → melalui: n. phrenicus → ke diafragma\r\n</li><li>saraf interkostalis → ke otot interkostal\r\n</li></ul><p>3.	Aktivasi otot pernapasan\r\n</p><ul><li>Diafragma dan Otot interkostal eksternal berkontraksi → terjadi inspirasi\r\n</li><li>Diafragma dan Otot interkostal eksternal berelaksasi → terjadi ekspirasi\r\n</li></ul>', '<p>Mahasiswa mampu menjelaskan  mekanisme  pengaturan pernafasan pada kasus <b>dengan tepat, lengkap dan sistematis.</b></p>', 1, 1, 1, 1, 1, '2026-04-29 06:44:37', '2026-04-29 06:55:43');
INSERT INTO `orubriks` VALUES (72, 40, 2, 'Penjelasan 3 faktor non-kimiawi yang secara langsung berpengaruh pada pernafasan', '<p>Mahasiswa<b> tidak mampu </b> menjelaskan faktor non-kimiawi yang secara langsung berpengaruh pada pernafasan&nbsp;</p>', '<p>Mahasiswa mampu menjelaskan   1 faktor non-kimiawi yang secara langsung berpengaruh pada pernafasan  <b>dengan tepat dan lengkap.</b></p>', '<p>Mahasiswa mampu menjelaskan 2 faktor non-kimiawi yang secara langsung berpengaruh pada pernafasan  <b>dengan tepat dan lengkap.</b></p>', '<p>Mahasiswa mampu  menjelaskan 3 faktor non-kimiawi yang secara langsung berpengaruh pada pernafasan <b>dengan tepat dan lengkap.</b></p>', 1, 1, 1, 1, 1, '2026-04-29 06:44:37', '2026-04-29 06:55:43');
INSERT INTO `orubriks` VALUES (73, 41, 1, 'Penjelasan patofisiologi munculnya manifestasi klinis', '<p>Mahasiswa tidak mampu menjelaskan  patofisiologi munculnya manifestasi klinis&nbsp;</p>', '<p>Mahasiswa menjelaskan   patofisiologi munculnya manifestasi klinis dengan tepat namun tidak lengkap</p>', '<p>Mahasiswa mampu menjelaskan  patofisiologi munculnya manifestasi klinis dengan tepat namun tidak lengkap\r\n</p><p>1.	Demam rematik\r\n</p><p>2.	Vegetasi katup jantung  Kerusakan katup jantung (stenosis mitral) \r\n</p><p>3.	Dilatasi atrium kiri \r\n</p><p>4.	EDV menurun  Cardiac Output Menurun\r\n</p><p>5.	Forward failure\r\n</p><p>6.	Backward failure\r\n</p><p>7.	Manifestasi \r\n</p><p><br></p>', '<p>Mahasiswa mampu menjelaskan  patofisiologi munculnya manifestasi klinis dengan tepat dan lengkap:\r\n</p><p>1.	Demam rematik\r\n</p><p>2.	Vegetasi katup jantung  Kerusakan katup jantung (stenosis mitral) \r\n</p><p>3.	Tekanan LA meningkat  Dilatasi atrium kiri LV menerima darah lebih sedikit\r\n</p><p>4.	EDV menurun  Cardiac Output Menurun\r\n</p><p>5.	Forward failure\r\n</p><p>6.	Backward failure\r\n</p><p>7.	Manifestasi\r\n</p><p>-	Orthopneu \r\n</p><p>-	PND\r\n</p><p>-	Opening Snaop\r\n</p><p>-	JVP meningkat\r\n</p><p>-	Edema tungkai\r\n</p><p>-	Cardiomegaly \r\n</p><p><br></p>', 1, 1, 1, 1, 1, '2026-04-30 03:35:55', '2026-04-30 03:50:29');
INSERT INTO `orubriks` VALUES (74, 41, 2, 'Penjelasan Mekanisme kerja obat', '<p>Mahasiswa tidak mampu menjelaskan Mekanisme kerja obat</p>', '<p>Mahasiswa mampu menjelaskan  Mekanisme kerja obat lini pertama dengan tepat salah satu obat yang diberikan</p>', '<p>Mahasiswa mampu menjelaskan  Mekanisme kerja obat dengan tepat tetapi tapi tidak lengkap hanya 2 dari 3 obat yang diberikan.&nbsp;</p>', '<p>Mahasiswa mampu menjelaskan  Mekanisme kerja obat dengan tepat dan lengkap.\r\n</p><p>-	Furosemide \r\n</p><p>-	ARNI\r\n</p><p>-	Bisoprolol\r\n</p><p><br></p>', 1, 1, 1, 1, 1, '2026-04-30 03:35:55', '2026-04-30 03:50:29');
INSERT INTO `orubriks` VALUES (75, 42, 1, 'Penjelasan diagnosis dan dasar diagnosis', '<p>Mahasiswa mampu menentukan :\r\n</p><p>-	Diagnosis kerja yang tepat tanpa disertai dasar diagnosis\r\n</p><p><br></p>', '<p>Mahasiswa mampu menentukan :\r\n</p><p>-	Diagnosis kerja yang tepat\r\n</p><p>-	Dasar diagnosis yang tidak lengkap\r\n</p><p><br></p>', '<p>Mahasiswa mampu menentukan :\r\n</p><p>-	Diagnosis kerja yang tepat\r\n</p><p>-	Dasar diagnosis yang lengkap meliputi :\r\n</p><p>a.	Anamnesis : RPS dan RPsos (1 FR)\r\n</p><p>b.	Pemeriksaan Fisik : Pemeriksaan nadi\r\n</p><p>c.	Pemeriksaan penunjang (EKG)\r\n</p><p><br></p>', '<p>Mahasiswa mampu menentukan :\r\n</p><p>-	Diagnosis kerja yang tepat\r\n</p><p>-	Dasar diagnosis yang lengkap meliputi :\r\n</p><p>a.	Anamnesis : RPS dan RPSos\r\n</p><p>b.	Pemeriksaan Fisik\r\n</p><p>c.	Pemeriksaan Penunjang</p>', 1, 1, 1, 1, 1, '2026-04-30 03:59:06', '2026-04-30 06:19:50');
INSERT INTO `orubriks` VALUES (76, 42, 2, 'Penjelasan patofisiologi manifestasi klinis yang muncul', '<p>Mahasiswa tidak mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul</p>', '<p>Mahasiswa mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul dengan tepat namun tidak lengkap</p>', '<p>Mahasiswa mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul dengan tepat dan lengkap\r\n</p><p>1.	Stres atau Konsumsi caffeine\r\n</p><p>2.	Aktivasi saraf simpatis\r\n</p><p>3.	Ca 2+ masuk ke sel miokard semakin banyak\r\n</p><p>4.	Terjadi afterdepolarization\r\n</p><p>5.	Denyut premature (VES)\r\n</p><p>6.	Manifestasi Klinis\r\n</p><p>-	Jantung berdebar, loncat/ berhenti sebentar\r\n</p><p>-	Pusing\r\n</p><p>-	QRS lebar, tidak ada P dan prematur\r\n</p><p><br></p>', '<p>Mahasiswa mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul dengan tepat dan lengkap\r\n</p><p>1.	Stres dan Konsumsi caffeine\r\n</p><p>2.	Aktivasi saraf simpatis\r\n</p><p>3.	Aktivasi reseptor b1 di jantung\r\n</p><p>4.	Peningkatan cAMP\r\n</p><p>5.	Ca 2+ masuk ke sel miokard samkin banyak\r\n</p><p>6.	Terjadi afterdepolarization\r\n</p><p>7.	Denyut premature (VES)\r\n</p><p>8.	Manifestasi Klinis\r\n</p><p>-	Jantung berdebar, loncat/ berhenti sebentar\r\n</p><p>-	Pusing\r\n</p><p>-	QRS lebar, tidak ada P dan prematur\r\n</p><p><br></p>', 1, 1, 1, 1, 1, '2026-04-30 03:59:06', '2026-04-30 06:19:50');
INSERT INTO `orubriks` VALUES (77, 43, 1, 'Penjelasan patofisiologi manifestasi klinis yang muncul', '<p>Mahasiswa tidak mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul</p>', '<p>-	Mahasiswa mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul dengan tepat namun tidak lengkap</p>', '<p>Mahasiswa mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul dengan tepat dan lengkap\r\n</p><p>1.	Riwayat alergi (th2 sudah aktif\r\n</p><p>2.	Trigger (olahraga)\r\n</p><p>3.	Aktivasi sel mast (tersensitisasi IgE)  degranulasi\r\n</p><p>4.	Melepas mediator kimia\r\n</p><p>5.	Bronkokonstriksi + edema mukosa + peningkatan mukus\r\n</p><p>6.	Manifestasi Klinis&nbsp;</p>', '<p>Mahasiswa mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul dengan tepat dan lengkap\r\n</p><p>1.	Riwayat alergi (th2 sudah aktif\r\n</p><p>2.	Trigger (olahraga) \r\n</p><p>3.	Peningkatan laju pernapasan\r\n</p><p>4.	Peningkatan osmolaritas cairan permukaan saluran napas\r\n</p><p>5.	Aktivasi sel mast (tersensitisasi IgE)  degranulasi\r\n</p><p>6.	Melepas mediator kimia\r\n</p><p>7.	Bronkokonstriksi + edema mukosa + peningkatan mukus\r\n</p><p>8.	Manifestasi Klinis :\r\n</p><p>-	Sesak nafas\r\n</p><p>-	Retraksi\r\n</p><p>-	Wheezing \r\n</p><p>-	Eosinophilia \r\n</p><p>-	Penurunan spirometri</p>', 1, 1, 1, 1, 1, '2026-04-30 06:23:40', '2026-05-04 02:18:22');
INSERT INTO `orubriks` VALUES (78, 43, 2, 'Penjelasan Penatalaksanaan awal', '<p>Mahasiswa tidak mampu menjelaskan tatalaksana awal</p>', '<p>Mahasiswa mampu menjelaskan  tatalaksana awal dengan tepat\r\n</p><p>1.	Tepat indikasi\r\n</p><p>2.	Tepat obat</p>', '<p>Mahasiswa mampu menjelaskan  tatalaksana awal dengan tepat \r\n</p><p>1.	Tepat indikasi\r\n</p><p>2.	Tepat obat\r\n</p><p>3.	Tepat dosis</p>', '<p>Mahasiswa mampu menjelaskan  tatalaksana awal dengan tepat dan lengkap\r\n</p><p>1.	Tepat indikasi : eksaserbasi ringan-sedang \r\n</p><p>2.	Tepat obat : Salbutamol dan Prednison\r\n</p><p>3.	Tepat sediaan : inhalasi dan tablet\r\n</p><p>4.	Tepat dosis : Salbutamol 2,5 mg dan prednisone 45 mg\r\n</p><p>5.	Tepat cara pemberian : inhalasi dan per oral\r\n</p><p><br></p>', 1, 1, 1, 1, 1, '2026-04-30 06:23:40', '2026-05-04 02:18:22');
INSERT INTO `orubriks` VALUES (81, 45, 1, 'Penjelasan mekanisme', '<p>Mahasiswa tidak mampu menjelaskan mekanisme munculnya tanda dan gejala</p>', '<p>Mahasiswa mampu menjelaskan mekanisme munculnya tanda dan gejala secara tidak tepat, meliputi :<br>1)Pengaruh hormon kehamilan<br>2)Perubahan organ target<br>3)Manifestasi Klinis (1-3 poin)&nbsp;</p>', '<p>Mahasiswa mampu menjelaskan mekanisme munculnya tanda dan gejala secara tepat, meliputi :<br>1)Pengaruh hormon kehamilan<br>2)Perubahan organ target<br>3)Manifestasi Klinis (4-6poin)&nbsp;</p>', '<p>Mahasiswa mampu menjelaskan mekanisme munculnya tanda dan gejala secara tepat dan lengkap, meliputi :<br><br>1)Pengaruh hormon kehamilan<br>2)Perubahan organ target<br>3)Manifestasi Klinis (7 poin) Tanda tidak pasti kehamilan<br>-Mual dan muntah<br>-Perut begah<br>-Payudara mengencang<br>-Sering buang air kecil<br>- Amenore<br>Tanda pasti kehamilan :<br>-Test kehamilan (+)<br>USG : didapatkan gestational sac dengan ukuran 13 mm.</p>', 1, 1, 1, 1, 1, '2026-05-04 01:36:06', '2026-05-04 01:56:50');
INSERT INTO `orubriks` VALUES (82, 45, 2, 'Penjelasan proses fertilisasi', '<p>Mahasiswa tidak mampu menjelaskan proses fertilisasi&nbsp;</p>', '<p>Mahasiswa mampu menjelaskan proses fertilisasi secara tidak tepat/ tidak lengkap, dan atau tidak sistematis</p>', '<p>Mahasiswa mampu menjelaskan proses fertilisasi secara tepat, sistematis, namun tidak lengkap.<br>1.Ovulasi&nbsp;<br>2.Perjalanan sperma&nbsp;<br>3.Penetrasi&nbsp;<br>4.Fusi sel&nbsp;</p>', '<p>Mahasiswa mampu menjelaskan proses fertilisasi secara tepat, lengkap, dan sistematis, meliputi :<br>1.Ovulasi&nbsp;<br>2.Perjalanan sperma&nbsp;<br>3.Penetrasi<br>4.Fusi sel</p><p>5.Fusi pronuclei&nbsp;</p>', 1, 1, 1, 1, 1, '2026-05-04 01:36:06', '2026-05-04 01:56:50');
INSERT INTO `orubriks` VALUES (83, 46, 1, 'Penjelasan mekanisme', '<p>Mahasiswa tidak mampu menjelaskan mekanisme yang menginduksi proses pada kasus tersebut</p>', '<p>Mahasiswa mampu menjelaskan mekanisme yang menginduksi secara tepat, meliputi salah satu poin.&nbsp;</p>', '<p>Mahasiswa mampu menjelaskan mekanisme yang menginduksi secara tepat, meliputi (2-3 poin )</p>', '<p>Mahasiswa mampu menjelaskan mekanisme yang menginduksi secara tepat dan lengkap, meliputi :<br>1.Penurunan fungsi plasenta&nbsp;&nbsp;<br>2.Tekanan pada ganglion servik menjadi stimulasi&nbsp;<br>3.Iskemik otot uterus&nbsp;<br>Peningkatan stress pd maternal maupun fetal mempengaruhi hormon menjadi pencetus untuk proses persalinan</p>', 1, 1, 1, 1, 1, '2026-05-04 01:58:31', '2026-05-04 02:18:44');
INSERT INTO `orubriks` VALUES (84, 46, 2, 'Penjelasan komponen partograf', '<p>Mahasiswa tidak mampu menjelaskan penjelasan komponen partograf</p>', '<p>Mahasiswa mampu menjelaskan komponen partograf secara tepat namun tidak lengkap, meliputi 1-2 poin.</p>', '<p>Mahasiswa mampu menjelaskan komponen partograf secara tepat dan lengkap, meliputi<br>1.Kondisi janin ( Salah satu )<br>2.Kemajuan persalinan ( Salah satu)&nbsp;<br>Kondisi ibu ( Salah satu )</p>', '<p>Mahasiswa mampu menjelaskan komponen partograf secara tepat dan lengkap, meliputi :<br><br>1.Kondisi janin ( DJJ, Air ketuban, molase )<br>2.Kemajuan persalinan ( Pembukaan serviks, penurunan kepala janin, His )<br>Kondisi Ibu ( Nadi, tekanan darah, suhu, produksi urin)</p>', 1, 1, 1, 1, 1, '2026-05-04 01:58:31', '2026-05-04 02:18:44');
INSERT INTO `orubriks` VALUES (85, 47, 1, 'Penjelasan diagnosis dan dasar diagnosis', '<p>Mahasiswa mampu menentukan :\r\n</p><p>-	Diagnosis kerja yang tepat tanpa disertai dasar diagnosis\r\n</p><p><br></p>', '<p>Mahasiswa mampu menentukan :\r\n</p><p>-	Diagnosis kerja yang tepat\r\n</p><p>-	Dasar diagnosis yang tidak lengkap\r\n</p><p><br></p>', '<p>Mahasiswa mampu menentukan :\r\n</p><p>-	Diagnosis kerja yang tepat\r\n</p><p>-	Dasar diagnosis yang lengkap meliputi :\r\n</p><p>a.	Anamnesis : RPS, RPD\r\n</p><p>b.	Pemeriksaan Fisik : TTV, PF Toraks\r\n</p><p>c.	Pemeriksaan penunjang : EKG\r\n</p><p><br></p>', '<p>Mahasiswa mampu menentukan :\r\n</p><p>-	Diagnosis kerja yang tepat\r\n</p><p>-	Dasar diagnosis yang lengkap meliputi :\r\n</p><p>a.	Anamnesis \r\n</p><p>b.	Pemeriksaan Fisik\r\n</p><p>c.	Pemeriksaan Penunjang</p>', 1, 1, 1, 1, 1, '2026-05-04 02:19:28', '2026-05-04 03:00:32');
INSERT INTO `orubriks` VALUES (86, 47, 2, 'Penjelasan patofisiologi manifestasi klinis yang muncul', '<p>Mahasiswa tidak mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul</p>', '<p>Mahasiswa mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul dengan tepat namun tidak lengkap</p>', '<p>Mahasiswa mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul dengan tepat dan lengkap\r\n</p><p>1.	Thrombosis vena dalam\r\n</p><p>2.	Trombus lepas\r\n</p><p>3.	Masuk sirkulasi vena\r\n</p><p>4.	Terjadi emboli paru\r\n</p><p>5.	Manifestasi Klinis</p>', '<p>Mahasiswa mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul dengan tepat dan lengkap\r\n</p><p>1.	Thrombosis vena dalam\r\n</p><p>2.	Dipicu triad virchow\r\n</p><p>3.	Trombus lepas\r\n</p><p>4.	Masuk sirkulasi vena\r\n</p><p>5.	Terjadi emboli paru\r\n</p><p>6.	Manifestasi Klinis\r\n</p><p>-	Dyspneu\r\n</p><p>-	Nyeri dada pleuritik\r\n</p><p>-	Hipotensi \r\n</p><p>-	Takikardi\r\n</p><p>-	Retraksi intercostal\r\n</p><p>-	Fremitus taktil hemotoraks dextra meningkat\r\n</p><p>-	EKG : S1Q3T3 pattern</p>', 1, 1, 1, 1, 1, '2026-05-04 02:19:28', '2026-05-04 03:00:32');
INSERT INTO `orubriks` VALUES (87, 48, 1, 'Penjelasan mekanisme', '<p>Mahasiswa tidak mampu menjelaskan mekanisme&nbsp;</p>', '<p>Mahasiswa mampu menjelaskan mekanisme secara tepat namun tidak lengkap, meliputi salah satu poin&nbsp;</p>', '<p>Mahasiswa mampu menjelaskan mekanisme secara tepat namun tidak lengkap, meliputi : (2-3 poin)</p>', '<p>Mahasiswa mampu menjelaskan mekanisme secara tepat dan lengkap, meliputi :<br>1.&nbsp; &nbsp; Hipoksia plasenta&nbsp;<br>2.&nbsp; &nbsp; Disfungsi endotel&nbsp;<br>3.&nbsp; &nbsp; Vasokontriksi, peningkatan permeabilitas kapiler serta aktivasi sistem koagulasi menimbulkan gangguan organ&nbsp;<br>4.&nbsp; &nbsp; Terjadi mobilisasi cairan dari ruang ekstravaskular ke intravaskular yang meningkatkan volume sirkulasi<br><br></p>', 1, 1, 1, 1, 1, '2026-05-04 02:47:53', '2026-05-04 03:00:50');
INSERT INTO `orubriks` VALUES (88, 48, 2, 'Penjelasan tatalaksana', '<p>Mahasiswa tidak mampu menjelaskan penjelasan tatalaksana</p>', '<p>Mahasiswa mampu menjelaskan tatalaksana secara tepat dan tidak lengkap.</p>', '<p>Mahasiswa mampu menjelaskan tatalaksana secara tepat dan lengkap, meliputi :<br>1.&nbsp; &nbsp; Stabilisasi awal ( Rawat inap, monitoring TTV dan output urine )<br>2.&nbsp; &nbsp; Pencegahan kejang (MgSO4 loading dose 4-6 gram IV, maintenance 1-2 gram/jam IV)<br><br></p>', '<p>Mahasiswa mampu menjelaskan tatalaksana secara tepat dan lengkap, meliputi :<br><br>1.&nbsp; &nbsp; Stabilisasi awal ( Rawat inap, monitoring TTV dan output urine )<br>2.&nbsp; &nbsp; Pencegahan kejang (MgSO4 loading dose 4-6 gram IV, maintenance 1-2 gram/jam IV)<br>3.&nbsp; &nbsp; Terapi anti hipertensi ( nifedipin atau labetalol )&nbsp;<br><br></p>', 1, 1, 1, 1, 1, '2026-05-04 02:47:53', '2026-05-04 03:00:50');
INSERT INTO `orubriks` VALUES (89, 49, 1, 'Penjelasan patomekanisme risiko yang terjadi pada bayi', '<p>Mahasiswa tidak mampu menjelaskan patomekanisme risiko yang terjadi pada bayi</p>', '<p>Mahasiswa mampu menjelaskan patomekanisme risiko secara<b> tepat namun tidak lengkap,</b> meliputi <b>salah satu :\r\n</b></p><p>1.	Etiologi\r\n</p><p>2.	Faktor Risiko\r\n</p><p><br></p>', '<p>Mahasiswa mampu menjelaskan patomekanisme risiko secara <b>tepat namun tidak lengkap</b> meliputi:\r\n</p><p>1.	Etiologi\r\n</p><p>2.	Faktor Risiko\r\n</p><p>3.	Patomekanisme\r\n</p><p>Makan sayuran kurang dicuci bersih --&gt; dimakan oleh ibu --&gt; menembus barrier plasenta --&gt; bayi terinfeksi\r\n</p><p><br></p>', '<p>Mahasiswa mampu menjelaskan patomekanisme risiko <b>secara tepat dan lengkap </b>meliputi:\r\n</p><p>1.	Etiologi\r\n</p><p>2.	Faktor Risiko\r\n</p><p>3.	Patomekanisme\r\n</p><p>Makan sayuran kurang dicuci bersih --&gt; dimakan oleh ibu --&gt; berkembang biak sebagai takizoit di dalam tubuh --&gt; menyebar melalui alirah darah atau limfa ibu --&gt; menembus barrier plasenta\r\n --&gt; masuk sirkulasi janin --&gt; janin mengalami kerusakan organ dan struktur --&gt; makrosefal, demam&nbsp;</p><p><br></p>', 1, 1, 1, 1, 1, '2026-05-04 02:50:18', '2026-05-04 02:58:42');
INSERT INTO `orubriks` VALUES (90, 49, 2, 'Penjelasan screening bayi baru lahir pada kasus', '<p>Mahasiswa tidak mampu menjelaskan screening bayi baru lahir pada kasus</p>', '<p>Mahasiswa mampu menjelaskan\r\n <b>1 screening</b> bayi baru lahir pada kasus secara tepat dan lengkap&nbsp;</p><p><br></p>', '<p>Mahasiswa mampu menjelaskan <b>2 screening</b> bayi baru lahir pada kasus secara tepat dan lengkap</p>', '<p>Mahasiswa mampu menjelaskan 3 screening bayi baru lahir pada kasus <b>secara tepat dan lengkap</b></p>', 1, 1, 1, 1, 1, '2026-05-04 02:50:18', '2026-05-04 02:58:42');
INSERT INTO `orubriks` VALUES (91, 50, 1, 'Penjelasan diagnosis dan dasar diagnosis', '<p>Mahasiswa mampu menentukan :\r\n</p><p>-	Diagnosis kerja yang tepat tanpa disertai dasar diagnosis\r\n</p><p><br></p>', '<p>Mahasiswa mampu menentukan :\r\n</p><p>-	Diagnosis kerja yang tepat\r\n</p><p>-	Dasar diagnosis yang tidak lengkap \r\n</p><p><br></p>', '<p>Mahasiswa mampu menentukan :\r\n</p><p>-	Diagnosis kerja yang tepat\r\n</p><p>-	Dasar diagnosis yang lengkap meliputi :\r\n</p><p>a.	Anamnesis : RPS, RPD\r\n</p><p>b.	Pemeriksaan fisik : TTV, PF Toraks\r\n</p><p>c.	Pemeriksaan penunjang : Sputum, Rontgen\r\n</p><p><br></p>', '<p>Mahasiswa mampu menentukan :\r\n</p><p>-	Diagnosis kerja yang tepat\r\n</p><p>-	Dasar diagnosis yang lengkap meliputi :\r\n</p><p>a.	Anamnesis\r\n</p><p>b.	Pemeriksaan Fisik\r\n</p><p>c.	Pemeriksaan Penunjang</p>', 1, 1, 1, 1, 1, '2026-05-04 03:03:53', '2026-05-04 03:10:56');
INSERT INTO `orubriks` VALUES (92, 50, 2, 'Penjelasan patofisiologi manifestasi klinis yang muncul', '<p>Mahasiswa tidak mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul</p>', '<p>Mahasiswa mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul dengan tepat namun tidak lengkap</p>', '<p>Mahasiswa mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul dengan tepat dan lengkap\r\n</p><p>1.	Infeksi tuberculosis\r\n</p><p>2.	Pengobatan tidak tuntas\r\n</p><p>3.	Replikasi bakteri  inflamasi kronik\r\n</p><p>4.	Granuloma mengalami nekrosis\r\n</p><p>5.	Destruksi jaringan \r\n</p><p>6.	Dindin pembuluh darah rapuh\r\n</p><p>7.	Manifestasi Klinis</p>', '<p>Mahasiswa mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul dengan tepat dan lengkap\r\n</p><p>1.	Infeksi tuberculosis\r\n</p><p>2.	Aktivasi Th1  terbentuk granuloma\r\n</p><p>3.	Pengobatan tidak tuntas\r\n</p><p>4.	Replikasi bakteri  inflamasi kronik\r\n</p><p>5.	Granuloma mengalami nekrosis\r\n</p><p>6.	Terbentuk kavitas paru di apeks\r\n</p><p>7.	Destruksi jaringan \r\n</p><p>8.	Dindin pembuluh darah rapuh\r\n</p><p>9.	Manifestasi Klinis\r\n</p><p>-	Hemaptoe masif\r\n</p><p>-	Demam subfebris\r\n</p><p>-	Sesak napas\r\n</p><p>-	Penurunan berat badan\r\n</p><p>-	Takikardi\r\n</p><p>-	Takipneu\r\n</p><p>-	Retraksi\r\n</p><p>-	Conjungtiva pucat</p>', 1, 1, 1, 1, 1, '2026-05-04 03:03:53', '2026-05-04 03:10:56');
INSERT INTO `orubriks` VALUES (93, 51, 1, 'Penjelasan patomekanisme risiko', '<p>Mahasiswa tidak mampu menjelaskan patomekanisme risiko yang terjadi pada kasus</p>', '<p>Mahasiswa mampu menjelaskan patomekanisme risiko secara tepat, meliputi:<br>1.&nbsp; &nbsp; Ketuban pecah dini<br>2.&nbsp; &nbsp; Komplikasi yang muncul<br>(1 poin)<br><br></p>', '<p>Mahasiswa mampu menjelaskan patomekanisme risiko secara tepat, meliputi:<br>1.&nbsp; &nbsp; Ketuban pecah dini<br>2.&nbsp; &nbsp; Komplikasi yang muncul<br>(2-3 poin)<br><br></p>', '<p>Mahasiswa mampu menjelaskan patomekanisme risiko secara tepat, meliputi:<br>1.&nbsp; &nbsp; Ketuban pecah dini<br>2.&nbsp; &nbsp; Komplikasi yang muncul (4 poin)<br>1)&nbsp; &nbsp; Sepsis neonatal<br>2)&nbsp; &nbsp; Pneumonia kongenital<br>3)&nbsp; &nbsp; Infeksi pada otak<br>4)&nbsp; &nbsp; Perinatal death<br><br></p>', 1, 1, 1, 1, 1, '2026-05-04 03:08:02', '2026-05-04 03:14:43');
INSERT INTO `orubriks` VALUES (94, 51, 2, 'Penjelasan kriteria yang termasuk bayi risiko tinggi', '<p>Mahasiswa tidak mampu menjelaskan kriteria yang termasuk bayi risiko tinggi</p>', '<p>Mahasiswa mampu menjelaskan 1-4 kriteria yang termasuk bayi risiko tinggi secara tepat namun tidak lengkap</p>', '<p>Mahasiswa mampu menjelaskan 5-8 kriteria yang termasuk bayi risiko tinggi secara tepat dan lengkap</p>', '<p>Mahasiswa mampu menjelaskan seluruh poin kriteria yang termasuk bayi risiko tinggi secara tepat dan lengkap.<br>1)&nbsp; &nbsp; Lahir masa gestasi &gt;42 minggu<br>2)&nbsp; &nbsp; BB lahir &gt;4000 gram<br>3)&nbsp; &nbsp; Bayi kecil untuk umur kehamilan<br>4)&nbsp; &nbsp; APGAR score 0-3 pada menit pertama<br>5)&nbsp; &nbsp; Lahir dengan penyakit infeksi<br>6)&nbsp; &nbsp; Riwayat penyakit ibu selama kehamilan<br>7)&nbsp; &nbsp; Ketuban pecah dini<br>8)&nbsp; &nbsp; Gemelli<br>9)&nbsp; &nbsp; Lahir SC atau dengan komplikasi persalinan<br><br></p>', 1, 1, 1, 1, 1, '2026-05-04 03:08:02', '2026-05-04 03:14:43');
INSERT INTO `orubriks` VALUES (95, 52, 1, 'Penentuan diagnosis', '<p>Mahasiswa tidak mampu menentukan Diagnosis&nbsp;</p>', '<p>Mahasiswa hanya mampu menentukan Diagnosis kerja dengan tepat tanpa disertai dasar diagnosis<br><br>Diagnosis : Inkompatibilitas ABO<br>Dasar Diagnosis tidak lengkap&nbsp;<br><br></p>', '<p>Mahasiswa mampu menentukan Diagnosis kerja yang tepat dengan Dasar diagnosis, meliputi :<br>Diagnosis : Inkompatibilitas ABO<br>Dasar Diagnosis:<br>A.&nbsp; &nbsp; Anamnesis<br>B.&nbsp; &nbsp; Pemeriksaan Fisik<br>C.&nbsp; &nbsp; Pemeriksaan penunjang (bilirubin total dan indirect meningkat dan golongan darah )&nbsp;<br><br></p>', '<p>Mahasiswa mampu menentukan diagnosis kerja disertai dengan dasar diagnosis yang tepat dan lengkap meliputi :&nbsp;<br>Diagnosis : Inkompatibilitas ABO<br>Dasar Diagnosis :&nbsp;<br>a.&nbsp; &nbsp; Anamnesis :&nbsp;<br>-&nbsp; &nbsp; Ikterus muncul &lt;24–48 jam),&nbsp;<br>-&nbsp; &nbsp; bayi tampak lemas&nbsp;<br>-&nbsp; &nbsp; &nbsp;reflek isap menurun,&nbsp;<br>b.&nbsp; &nbsp; Pemeriksaan fisik :&nbsp;<br>-&nbsp; &nbsp; Sklera ikterik&nbsp;<br>-&nbsp; &nbsp; Wajah Ikterik&nbsp;<br>-&nbsp; &nbsp; Kulit dada dan abdomen ikterik&nbsp;<br>c.&nbsp; &nbsp; Pemeriksaan penunjang :&nbsp;<br>-&nbsp; &nbsp; bilirubin total dan indirect meningkat<br>-&nbsp; &nbsp; ibu golongan darah O&nbsp;<br>-&nbsp; &nbsp; bayi golongan darah A&nbsp;<br>-&nbsp; &nbsp; Rhesus positif&nbsp;<br>-&nbsp; &nbsp; Hb : 9 kesan anemia<br><br></p>', 1, 1, 1, 1, 1, '2026-05-04 03:30:47', '2026-05-04 03:43:48');
INSERT INTO `orubriks` VALUES (96, 52, 2, 'Penjelasan Patomekanisme', '<p>Mahasiswa tidak&nbsp; mampu menjelaskan patomekanisme diagnosis kerja&nbsp;</p>', '<p>Mahasiswa mampu menjelaskan secara tepat patomekanisme diagnosis kerja dengan tidak lengkap</p>', '<p>Mahasiswa mampu menjelaskan secara tepat patomekanisme diagnosis kerja dihubungkan dengan:<br>a.&nbsp; &nbsp; Faktor resiko&nbsp;<br>b.&nbsp; &nbsp; Transfer antibody plasenta&nbsp;<br>c.&nbsp; &nbsp; Terjadi reaksi antigen dan antibody&nbsp;<br><br></p>', '<p>a.&nbsp; &nbsp; Faktor Risiko : Ibu golongan darah O memiliki antibody igG A dan anti B<br>b.&nbsp; &nbsp; Transfer antibody melalui plasenta : Antibodi IgG menembus plasenta dan menyerang eritrsosit janin yang memiliki antigen A/B&nbsp; masuk ke sirkulasi janin&nbsp;<br>c.&nbsp; &nbsp; Reaksi antigen – antibody : antibody ibu akan mengikat antigen A atau B pada sel darah merah janin.&nbsp;<br>d.&nbsp; &nbsp; Terjadi hemolisis eritrosit janin : terjadi penghancuran sel darah merah janin di limpa ini menyebabkan peningkatan bilirubin&nbsp;<br>e.&nbsp; &nbsp; Manifestasi klinik&nbsp; :<br>-&nbsp; &nbsp; Ikterik&nbsp;<br>-&nbsp; &nbsp; Anemia ringan&nbsp;<br><br></p>', 1, 1, 1, 1, 1, '2026-05-04 03:30:47', '2026-05-04 03:43:48');
INSERT INTO `orubriks` VALUES (97, 53, 1, 'Penjelasan patofisiologi munculnya manifestasi klinis', '<p>Mahasiswa tidak mampu menjelaskan  patofisiologi munculnya manifestasi klinis&nbsp;</p>', '<p>Mahasiswa menjelaskan   patofisiologi munculnya manifestasi klinis dengan tepat namun tidak lengkap&nbsp;</p>', '<p>Mahasiswa mampu menjelaskan  patofisiologi munculnya manifestasi klinis dengan tepat \r\n</p><p>1.	Riwayat Hipertensi\r\n</p><p>2.	Penghentian obat beta blocker\r\n</p><p>3.	aktivasi sistem RAA\r\n</p><p>4.	cedera vascular\r\n</p><p>5.	Manifestasi klinis \r\n</p><p><br></p>', '<p>Mahasiswa mampu menjelaskan  patofisiologi munculnya manifestasi klinis dengan tepat dan lengkap\r\n</p><p>1.	Riwayat Hipertensi\r\n</p><p>2.	Penghentian obat beta blocker\r\n</p><p>3.	gangguan autoregulasi\r\n</p><p>4.	aktivasi sistem RAA\r\n</p><p>5.	cedera vascular\r\n</p><p>6.	Manifestasi klinis\r\n</p><p>-	Nyeri kepala\r\n</p><p>-	Penglihatan kabur\r\n</p><p>-	Kreatinin meningkat\r\n</p><p>-	Ro toraks : cardiomegali\r\n</p><p><br></p>', 1, 1, 1, 1, 1, '2026-05-04 03:31:56', '2026-05-04 03:41:27');
INSERT INTO `orubriks` VALUES (98, 53, 2, 'Penjelasan Penatalaksanaan awal', '<p>Mahasiswa tidak mampu menjelaskan tatalaksana awal</p>', '<p>Mahasiswa mampu menjelaskan  tatalaksana awal dengan tepat\r\n</p><p>1.	Tepat indikasi\r\n</p><p>2.	Tepat obat</p>', '<p>Mahasiswa mampu menjelaskan  tatalaksana awal dengan tepat \r\n</p><p>1.	Tepat indikasi\r\n</p><p>2.	Tepat obat\r\n</p><p>3.	Tepat dosis</p>', '<p>Mahasiswa mampu menjelaskan  tatalaksana awal dengan tepat dan lengkap\r\n</p><p>1.	Tepat indikasi : penurunan TD 20-25% dari MAP dalam 24 jam \r\n</p><p>2.	Tepat obat : Captopril / Amlodipin / Clonidine\r\n</p><p>3.	Tepat sediaan : tablet\r\n</p><p>4.	Tepat dosis : Captopril 12,5 mg / amlodipine 10 mg / Clonidine 0,2 mg\r\n</p><p>5.	Tepat cara pemberian : per oral</p>', 1, 1, 1, 1, 1, '2026-05-04 03:31:56', '2026-05-04 03:41:27');
INSERT INTO `orubriks` VALUES (99, 54, 1, '1.	Jelaskan patofisiologi terjadinya penyakit pada kasus tersebut berdasarkan faktor risiko sampai munculnya manisfestasi klinis pada kasus!', '<p>Mahasiswa tidak mampu menjelaskan  patofisiologi munculnya manifestasi klinis.</p>', '<p>Mahasiswa menjelaskan   patofisiologi munculnya manifestasi klinis dengan tepat namun tidak lengkap.</p>', '<p>Mahasiswa mampu menjelaskan  patofisiologi munculnya manifestasi klinis dengan tepat namun tidak lengkap\r\n</p><p>1.	FR : ACS (STEMI) \r\n</p><p>2.	Iskemia --&gt; Nekrosis miokard\r\n</p><p>3.	Penurunan kontraktilitas LV\r\n</p><p>4.	Penurunan cardiac output dan stroke volume\r\n</p><p>5.	Mekanisme kompensasi : Aktivasi SNS dan RAAS \r\n</p><p>6.	Retensi cairan\r\n</p><p>7.	Gagal jantung akut \r\n</p><p>8.	Manifestasi klinis&nbsp;</p>', 'Mahasiswa mampu menjelaskan  patofisiologi munculnya manifestasi klinis dengan tepat dan lengkap:\r\n<div>1.	FR : ACS (STEMI) \r\n</div><div>2.	Iskemia --&gt; Nekrosis miokard\r\n</div><div>3.	Penurunan kontraktilitas LV\r\n</div><div>4.	Penurunan cardiac output dan stroke volume\r\n</div><div>5.	Mekanisme kompensasi : Aktivasi SNS dan RAAS\r\n</div><div>6.	Peningkatan LV end diastolic pressure --&gt; Retensi cairan\r\n</div><div>7.	Gagal jantung akut \r\n</div><div>8.	Manifestasi: \r\n</div><div>-	Peningkatan JVP\r\n</div><div>-	S3 gallop\r\n</div><div>-	Tachypnea\r\n</div><div>-	Dyspnea\r\n</div><div>-	Orthopneu</div>', 1, 1, 1, 1, 1, '2026-05-04 03:38:03', '2026-05-04 04:02:11');
INSERT INTO `orubriks` VALUES (100, 54, 2, '2.	Jelaskan mekanisme kerja obat yang diberikan dokter!', '<p>Mahasiswa tidak mampu menjelaskan Mekanisme kerja obat.</p>', '<p>Mahasiswa mampu menjelaskan  Mekanisme kerja obat dengan tepat 1 obat yang diberikan</p>', '<p>Mahasiswa mampu menjelaskan  Mekanisme kerja obat dengan tepat tetapi tapi tidak lengkap hanya 2-3 dari 4 obat yang diberikan.</p>', '<p>Mahasiswa mampu menjelaskan  Mekanisme kerja obat dengan tepat dan lengkap.\r\n</p><p>-	Aspirin\r\n</p><p>-	ISDN\r\n</p><p>-	Clopidogrel\r\n</p><p>-	Furosemide \r\n</p><p><br></p>', 1, 1, 1, 1, 1, '2026-05-04 03:38:03', '2026-05-04 04:02:11');
INSERT INTO `orubriks` VALUES (101, 55, 1, 'Penjelasan mekanisme', '<p>Mahasiswa tidak&nbsp; mampu menjelaskan mekanisme terjadinya breast engorgement</p>', '<p>Mahasiswa mampu menjelaskan secara tepat mekanisme terjadinya breast engorgement dengan tidak lengkap</p>', '<p>Mahasiswa mampu menjelaskan secara tepat mekanisme terjadinya breast engorgement dihubungkan factor resiko dengan:<br><br>Poin b-f<br><br></p>', '<p>Mahasiswa mampu menjelaskan secara tepat dan lengkap mekanisme terjadinya breast engorgement meliputi :<br>a.&nbsp; &nbsp; Produksi ASI meningkat&nbsp;<br>-&nbsp; &nbsp; Hormon prolactin sehingga payudara mulai menghasilkan ASI lebih banyak&nbsp;<br>b.&nbsp; &nbsp; Pengosongan asi tidak optimal (bisa disebabkan oleh frekuensi menyusui kurang, perlekatan bayi tidak baik dan bayi tidak efektif menyusu )&nbsp;<br>c.&nbsp; &nbsp; Terjadi penumpukan ASI : ASI tertahan di alveoli dan ductus laktiferus&nbsp;<br>d.&nbsp; &nbsp; Peningkatan tekanan intraductal : menyebabkan payudara terasa tegang dan nyeri&nbsp;<br>e.&nbsp; &nbsp; Kongesti vascular limfatik : aliran darah dan limfe meningkat menyebabkan edema, payudara keras dan hangat.&nbsp;<br>f.&nbsp; &nbsp; Manifestasi klinis :&nbsp;<br>-&nbsp; &nbsp; Payudara bengkak, keras dan nyeri&nbsp;</p>', 1, 1, 1, 1, 1, '2026-05-04 03:52:16', '2026-05-04 04:08:51');
INSERT INTO `orubriks` VALUES (102, 55, 2, 'Perubahan fisiologis', '<p>Mahasiswa tidak mampu menentukan perubahan fisiologis masa nifas</p>', '<p>Mahasiswa hanya mampu menentukan 1 poin perubahan fisiologis masa nifas&nbsp; secara tepat dan lengkap&nbsp;<br>atau menjelaskan beberapa poin namun tidak lengkap&nbsp;<br><br></p>', '<p>Mahasiswa mampu menentukan perubahan fisiologis masa nifas&nbsp; meliputi :<br><br>2-3 poin&nbsp;<br><br></p>', '<p>Mahasiswa mampu menentukan perubahan fisiologis masa nifas&nbsp; yang tepat dan lengkap meliputi :&nbsp;<br>&nbsp;4-6 poin&nbsp;<br>1.&nbsp; &nbsp; Jalan lahir : Epitel vagina mulai berproliferasi pada 4 sampai 6 minggu<br>2.&nbsp; &nbsp; Tahapan involusi uterus&nbsp;<br>3.&nbsp; &nbsp; Lochia&nbsp;<br>4.&nbsp; &nbsp; Tempat penempelan plasenta&nbsp;<br>5.&nbsp; &nbsp; Traktus urinarius&nbsp;<br>6.&nbsp; &nbsp; Peritoneum dan dinding perut&nbsp;<br><br></p>', 1, 1, 1, 1, 1, '2026-05-04 03:52:16', '2026-05-04 04:08:51');
INSERT INTO `orubriks` VALUES (103, 56, 1, 'Sebutkan diagnosis dan menjelaskan dasar diagnosis pada kasus!', '<p>Mahasiswa mampu menentukan :\r\n</p><p>-	Diagnosis kerja yang tepat tanpa disertai dasar diagnosis</p>', '<p>Mahasiswa mampu menentukan :\r\n</p><p>-	Diagnosis kerja yang tepat\r\n</p><p>-	Dasar diagnosis yang tidak lengkap</p>', '<p>Mahasiswa mampu menentukan :\r\n</p><p>-	Diagnosis kerja yang tepat\r\n</p><p>-	Dasar diagnosis yang lengkap meliputi :\r\n</p><p>a.	Anamnesis : RPS, RPD, Rpsos\r\n</p><p>b.	Pemeriksaan Fisik : Auskultasi jantung \r\n</p><p>c.	Pemeriksaan penunjang : EKG</p>', '<p>Mahasiswa mampu menentukan :\r\n</p><p>-	Diagnosis kerja yang tepat\r\n</p><p>-	Dasar diagnosis yang lengkap meliputi :\r\n</p><p>a.	Anamnesis : Faktor resiko, RPS, RPD, dan RPsos  \r\n</p><p>b.	Pemeriksaan Fisik : tanda vital dan auskultasi \r\n</p><p>c.	Pemeriksaan Penunjang&nbsp;</p>', 1, 1, 1, 1, 1, '2026-05-04 04:08:08', '2026-05-04 04:25:14');
INSERT INTO `orubriks` VALUES (104, 56, 2, 'Jelaskan patofisiologi munculnya manifestasi klinis pada kasus!', '<p>Mahasiswa tidak mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul</p>', '<p>Mahasiswa mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul dengan tepat namun tidak lengkap.</p>', '<p>Mahasiswa mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul dengan tepat dan lengkap\r\n</p><p>1.	FR : Usia, Riw. HT dan merokok\r\n</p><p>2.	Perubahan structural atrium (remodeling : dilatasi, fibrosis)\r\n</p><p>3.	Perubahan elektrikal atrium \r\n</p><p>4.	Focus ektopik (terutama di vena pulmonalis)\r\n</p><p>5.	Aktivitas listrik cepat dan kacau \r\n</p><p>6.	Irama ventrikel tidak teratur \r\n</p><p>7.	Manifestasi Klinis</p>', '<p>Mahasiswa mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul dengan tepat dan lengkap\r\n</p><p>1.	FR : Usia, Riw. HT dan merokok\r\n</p><p>2.	Perubahan structural atrium (remodeling : dilatasi, fibrosis)\r\n</p><p>3.	Perubahan elektrikal atrium \r\n</p><p>4.	Focus ektopik (terutama di vena pulmonalis)\r\n</p><p>5.	Aktivitas listrik cepat dan kacau \r\n</p><p>6.	Impuls acak ke AV node \r\n</p><p>7.	Irama ventrikel tidak teratur \r\n</p><p>8.	Manifestasi Klinis:\r\n</p><p>-	Palpitasi \r\n</p><p>-	Pre-sinkop \r\n</p><p>-	Lemas \r\n</p><p>-	EKG : Atrial fibrilasi</p>', 1, 1, 1, 1, 1, '2026-05-04 04:08:08', '2026-05-04 04:25:14');
INSERT INTO `orubriks` VALUES (105, 57, 1, 'Sebutkan diagnosis dan menjelaskan dasar diagnosis pada kasus!', '<p>Mahasiswa mampu menentukan :\r\n</p><p>-	Diagnosis kerja yang tepat tanpa disertai dasar diagnosis.</p>', '<p>Mahasiswa mampu menentukan :\r\n</p><p>-	Diagnosis kerja yang tepat\r\n</p><p>-	Dasar diagnosis yang lengkap meliputi :\r\n</p><p>a.	Anamnesis</p>', '<p>Mahasiswa mampu menentukan :\r\n</p><p>-	Diagnosis kerja yang tepat\r\n</p><p>-	Dasar diagnosis yang lengkap meliputi :\r\n</p><p>a.	Anamnesis: RPS, RPD, Rpsos\r\n</p><p>b.	Pemeriksaan Fisik : Tanda vital \r\n</p><p>c.	Pemeriksaan penunjang : EKG \r\n</p><p><br></p>', '<p>Mahasiswa mampu menentukan :\r\n</p><p>-	Diagnosis kerja yang tepat\r\n</p><p>-	Dasar diagnosis yang lengkap meliputi :\r\n</p><p>a.	Anamnesis : FR, RPS, RPD, Rpsos\r\n</p><p>b.	Pemeriksaan Fisik : tanda vital, PF jantung\r\n</p><p>c.	Pemeriksaan Penunjang</p>', 1, 1, 1, 1, 1, '2026-05-04 04:40:25', '2026-05-04 05:14:08');
INSERT INTO `orubriks` VALUES (106, 57, 2, 'Jelaskan patofisiologi munculnya manifestasi klinis pada kasus !', '<p>Mahasiswa tidak mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul</p>', '<p>Mahasiswa mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul dengan tepat namun tidak lengkap.</p>', '<p>Mahasiswa mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul dengan tepat dan lengkap\r\n</p><p>1.	Riwayat PJK dan konsumsi obat\r\n</p><p>2.	Perlambatan konduksi di nodus AV \r\n</p><p>3.	Pemanjangan interval PR \r\n</p><p>4.	Semua impuls tetap diteruskan ke ventrikel \r\n</p><p>5.	Irama sinus regular \r\n</p><p>6.	Manifestasi Klinis</p>', '<p>Mahasiswa mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul dengan tepat dan lengkap\r\n</p><p>1.	Riwayat PJK dan konsumsi obat\r\n</p><p>2.	Perlambatan konduksi di nodus AV \r\n</p><p>3.	Waktu hantaran impuls dari atrium --&gt; Ventrikel memanjang\r\n</p><p>4.	Pemanjangan interval PR \r\n</p><p>5.	Semua impuls tetap diteruskan ke ventrikel \r\n</p><p>6.	Irama sinus regular \r\n</p><p>7.	Manifestasi Klinis :\r\n</p><p>-	regular heart rate\r\n</p><p>-	Pre sinkop\r\n</p><p>-	Lemas \r\n</p><p>-	Hipotensi</p>', 1, 1, 1, 1, 1, '2026-05-04 04:40:25', '2026-05-04 05:14:08');
INSERT INTO `orubriks` VALUES (107, 58, 1, 'Jelaskan Patofisiologi munculnya manifestasi klinis pada kasus!', '<p>Mahasiswa tidak mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul</p>', '<p>Mahasiswa mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul dengan tepat namun tidak lengkap.</p>', '<p>Mahasiswa mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul dengan tepat dan lengkap\r\n</p><p>1.	Faktor resiko merokok\r\n</p><p>2.	Pelepasan TLR\r\n</p><p>3.	Aktivasi respon Th 1 dan Th17\r\n</p><p>4.	Memicu sitokin (IL 8+, IL 6), IFN, TNF\r\n</p><p>5.	Penyempitan saluran nafas dan remodeling saluran napas dan remodeling proliferasi fibrotic\r\n</p><p>6.	Manifestasi klinis : (minimal 2 manifestasi)\r\n</p><p><br></p>', '<p>Mahasiswa mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul dengan tepat dan lengkap\r\n</p><p>1.	Faktor resiko merokok\r\n</p><p>2.	Pelepasan TLR\r\n</p><p>3.	Aktivasi respon Th 1 dan Th17\r\n</p><p>4.	Memicu sitokin (IL 8+, IL 6), IFN, TNF\r\n</p><p>5.	Penyempitan saluran nafas dan remodeling saluran napas dan remodeling proliferasi fibrotik\r\n</p><p>6.	Manifestasi klinis :\r\n</p><p>-	Sesak\r\n</p><p>-	Batuk berdahak\r\n</p><p>-	Wheezing \r\n</p><p><br></p>', 1, 1, 1, 1, 1, '2026-05-04 05:20:45', '2026-05-05 01:42:41');
INSERT INTO `orubriks` VALUES (108, 58, 2, 'Jelaskan tatalaksana yang sesuai dengan kasus !', '<p>Mahasiswa tidak mampu menjelaskan tatalaksana</p>', '<p>Mahasiswa mampu menjelaskan tatalaksana dengan tepat\r\n</p><p>1. Tepat indikasi\r\n</p><p>2. Tepat obat\r\n</p><p><br></p>', '<p>Mahasiswa mampu menjelaskan tatalaksana dengan tepat\r\n</p><p>1. Tepat indikasi\r\n</p><p>2. Tepat obat\r\n</p><p>3. Tepat dosis\r\n</p><p><br></p>', '<p>Mahasiswa mampu menjelaskan tatalaksana dengan tepat dan lengkap\r\n</p><p>1. Tepat indikasi : eksaserbasi ringan-sedang\r\n</p><p>2. Tepat obat : Salbutamol dan Prednison\r\n</p><p>3. Tepat sediaan : inhalasi dan tablet\r\n</p><p>4. Tepat dosis : Salbutamol 2,5 mg dan prednisone 45 mg\r\n</p><p>5. Tepat cara pemberian : inhalasi dan per oral\r\n</p><p><br></p>', 1, 1, 1, 1, 1, '2026-05-04 05:20:45', '2026-05-05 01:42:41');
INSERT INTO `orubriks` VALUES (109, 59, 1, 'Diagnosis dan penjelasan dasar diagnosis', '<p>Mahasiswa tidak mampu menentukan Diagnosis kerja dan dasar diagnosis&nbsp;</p><p><br></p>', '<p>Mahasiswa mampu menentukan :\r\n</p><p>-	Diagnosis kerja yang<b> tepat\r\n</b></p><p>-	Dasar diagnosis yang <b>Tidak lengkap \r\n</b></p><p><br></p>', '<p>Mahasiswa mampu menentukan :\r\n</p><p>-	Diagnosis kerja yang <b>tepat\r\n</b></p><p>-	Dasar diagnosis yang lengkap meliputi :\r\n</p><p>a.	Anamnesis : RPS, RPSos\r\n</p><p>b.	Pemeriksaan Fisik : TTV dan PF thorax\r\n</p><p>c.	Pemeriksaan penunjang : Rontgen thorax\r\n</p><p><br></p>', '<p>Mahasiswa mampu menentukan :\r\n</p><p>-	Diagnosis kerja yang tepat\r\n</p><p>-	Dasar diagnosis yang lengkap meliputi :\r\n</p><p>a.	Anamnesis :RPS, RPD, RPK, dan RPsos\r\n</p><p>b.	Pemeriksaan Fisik\r\n</p><p>c.	Pemeriksaan Penunjang</p>', 1, 1, 1, 1, 1, '2026-05-05 01:50:42', '2026-05-06 01:49:57');
INSERT INTO `orubriks` VALUES (110, 59, 2, 'Penjelasan patofisiologi manifestasi klinis yang muncul', '<p>Mahasiswa tidak mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul</p>', '<p>Mahasiswa mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul dengan tepat namun <b>tidak lengkap.</b></p>', '<p>Mahasiswa mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul dengan tepat dan lengkap\r\n</p><p>1.	Riwayat Infeksi\r\n</p><p>2.	Menyebabkan permeabilitas kapiler \r\n</p><p>3.	Perpindahan cairan intrasel ke interstisial</p><p>4. Akumulasi cairan yang berlebihan di rongga pleura  penurunan ekspansi paru\r\n</p><p>5.	Manifestasi klinis \r\n</p><p><br></p>', '<p>Mahasiswa mampu menjelaskan patofisiologi penyakit dan manifestasi klinis yang muncul dengan tepat dan lengkap\r\n</p><p>1.	Riwayat Infeksi\r\n</p><p>2.	Menyebabkan permeabilitas kapiler \r\n</p><p>3.	Perpindahan cairan intrasel ke interstisial\r\n</p><p>4.	Peningkatan produksi cairan pleura \r\n</p><p>5.	Akumulasi cairan yang berlebihan di rongga pleura  penurunan ekspansi paru\r\n</p><p>6.	Manifestasi klinis\r\n</p><p>-	Takipneu\r\n</p><p>-	Takikardi\r\n</p><p>-	Penurunan fremitus taktil\r\n</p><p>-	Redup hemithoraks dextra\r\n</p><p>-	Penurunan suara paru ics 4-6 kebawah\r\n</p><p><br></p>', 1, 1, 1, 1, 1, '2026-05-05 01:50:42', '2026-05-06 01:49:57');
INSERT INTO `orubriks` VALUES (111, 60, 1, 'Penjelasan patofisiologi munculnya manifestasi klinis', '<p>Mahasiswa tidak mampu menjelaskan  patofisiologi munculnya manifestasi klinis</p>', '<p>Mahasiswa menjelaskan   patofisiologi munculnya manifestasi klinis dengan tepat namun tidak lengkap.&nbsp;</p>', '<p>Mahasiswa mampu menjelaskan  patofisiologi munculnya manifestasi klinis dengan tepat \r\n</p><p>1.	Riwayat HT kronik\r\n</p><p>2.	Degenerasi lapisan media\r\n</p><p>3.	Robekan intima (intima tear)\r\n</p><p>4.	Terbentuk false lumen \r\n</p><p>5.	Diseksi meluas\r\n</p><p>6.	Iskemia organ/ rupture \r\n</p><p>7.	Manifestasi klinis \r\n</p><p><br></p>', '<p>Mahasiswa mampu menjelaskan  patofisiologi munculnya manifestasi klinis dengan tepat dan lengkap\r\n</p><p>1.	Riwayat HT kronik\r\n</p><p>2.	Degenerasi lapisan media\r\n</p><p>3.	Robekan intima (intima tear)\r\n</p><p>4.	Darah masuk ke dinding aorta\r\n</p><p>5.	Terbentuk false lumen \r\n</p><p>6.	Diseksi meluas\r\n</p><p>7.	Iskemia organ/ rupture \r\n</p><p>8.	Manifestasi klinis\r\n</p><p>-	Nyeri dada hebat\r\n</p><p>-	Keringat dingin \r\n</p><p>-	Gelisah \r\n</p><p>-	Takikardia\r\n</p><p>-	Murmur diastolic</p>', 1, 1, 1, 1, 1, '2026-05-05 03:13:44', '2026-05-05 03:52:36');
INSERT INTO `orubriks` VALUES (112, 60, 2, 'Penjelasan Penatalaksanaan awal', '<p>Mahasiswa tidak mampu menjelaskan tatalaksana awal</p>', '<p>Mahasiswa mampu menjelaskan  tatalaksana awal dengan tepat\r\n</p><p>1.	Tepat indikasi\r\n</p><p>2.	Tepat obat</p>', '<p>Mahasiswa mampu menjelaskan  tatalaksana awal dengan tepat \r\n</p><p>1.	Tepat indikasi\r\n</p><p>2.	Tepat obat\r\n</p><p>3.	Tepat dosis</p>', '<p>Mahasiswa mampu menjelaskan  tatalaksana awal dengan tepat dan lengkap\r\n</p><p>1.	Tepat indikasi : Kontrol tekanan darah, denyut jantung &amp; analgetik \r\n</p><p>2.	Tepat obat : beta bloker dan morfin\r\n</p><p>3.	Tepat dosis : labetalol 100mg, morphin 2 mg \r\n</p><p>4.	Tepat sediaan : ampul\r\n</p><p>5.	Tepat cara pemberian : Labetalol IV dan Morphin IV bolus 5-10 menit</p>', 1, 1, 1, 1, 1, '2026-05-05 03:13:44', '2026-05-05 03:52:36');
