INSERT INTO `ostations` VALUES (178, 21, 11, 'station 11', '34819083152111', 78, 'dr. Rachma Ayu Maulidiany', 11, 12, 0, '2026-05-08 05:31:07', '2026-05-08 09:02:21', NULL);
INSERT INTO `otemplates` VALUES (1, 5, 'percobaan', '1', 'penyakit tropis', '<p><b>Riwayat Penyakit Sekarang</b><br>Seorang laki-laki datang ke poliklinik RS dengan keluhan terdapat benjolan yang seperti menggantung di paha sejak 2 tahun yang lalu. Keluhan benjolan tidak disertai rasa nyeri. Benjolan dirasakan semakin membesar. Keluhan disertai dengan gatal terutama pada malam hari dan kulit menjadi bintik bintik putih di badan. Pasien juga mengeluhkan mata menjadi semakin buram ketika melihat. Keluhan tidak disertai dengan demam, penurunan berat badan, atau penurunan nafsu makan.<br><b>Riwayat Penyakit Dahulu</b><br>- Baru pertama kali mengalami keluhan seperti ini<br>- Riwayat hipertensi disangkal<br>- Riwayat DM disangkal<br><b>Riwayat Peyakit Keluarga</b><br>- Tidak ada keluhan yang sama di keluarga<br>- Riwayat hipertensi dan DM dalam keluarga disangkal<br><b>Riwayat Pribadi Sosial</b><br>- Pasien mengatakan 2 tahun lalu pernah tinggal selama satu tahun di India dan bekerja sebagai petani disana. Tempat tinggal selama bekerja padat penduduk, dan dipinggir sungai, banyak sampah di sekitar tempat tinggal sehingga banyak lalat.<br>- Tempat tinggal pasien sekarang padat penduduk, tidak rawan banjir. Pasien sekarang bekerja sebagai pedagang.<br><b>Pemeriksaan Fisik</b><br>Kesadaran : Composmentis<br>Keadan Umum : tampak sakit sedang<br>Tekanan darah : 120/80 mmHg<br>Suhu : 37,3’C<br>Nadi : 80 x/menit<br>Respirasi : 20 x/menit<br>Mata : konjungtiva pucat -/-, sclera ikterik -/-<br>Visus OS : 1/60<br>Visus OD : 1/60<br>Mulut : sianosis -<br>Leher : pembesaran KGB (-)</p><p><br><u>Thoraks</u><br>- Inspeksi : bentuk dada simetris, otot bantu pernapasan (-), ictus cordis tidak terlihat<br>- Palpasi : nyeri tekan (-), krepitasi (-), ictus cordis teraba regular<br>- Perkusi : sonor seluruh lapang paru, batas jantung dalam batas normal<br>- Auskultasi : vesikuler (+/+), rhonki -/-, wheezing -/- , BJ I-II regular, mur mur (-), gallop (-)</p><p><br><u>Abdomen</u><br>- Inspeksi : distensi (-)<br>- Palpasi : nyeri tekan (-), hepatomegali (-), splenomegali (-)<br>- Perkusi : timpani seluruh lapang abdomen<br>- Auskultasi : Bising Usus 15x/menit</p><p><br>Ekstremitas : akral hangat, CRT &lt; 2 detik</p><p><br><b>Status Lokalis</b></p><p><img style=\"width: 50%;\" src=\"data:image/png;base64,\" data-filename=\"image.png\"><b><br></b><br>Tampak benjolan hiperigmentasi a/r femur dextra, kulit tampak menggantung,<br>permukaan berbenjol, nyeri (-), mobile (-), konsistensi kenyal (+)</p><p><img style=\"width: 50%;\" src=\"data:image/png;base64,\" data-filename=\"image.png\"><br>Tampak gambaran hipopigmentasi (gambaran macan tutul)<br><b>Pemeriksaan Penunjang</b><br>Darah Rutin<br>- Hb : 12 g/dl<br>- Leukosit : 12.000 mm3<br>- Trombosit : 300.000 mm3<br>- Hitung jenis leukosit<br>• Basophil : 0<br>• Eosinophil : 10<br>• Batang : 2<br>• Segmen : 60<br>• Limfosit : 20<br>• Monosit : 8<br>Pemeriksaan Apusan darah didapatkan</p><p><img style=\"width: 50%;\" src=\"data:image/png;base64,\" data-filename=\"image.png\"><br>Terdapat Mikrofilaria, tanpa selubung, cephalic space 1:2 tanpa nukelus terminal<br>Pemeriksaan Serologi<br>Antigen Oncho-27 : (+)</p>', '<p><b><u>Tugas Mahasiswa</u></b><br>1. Jelaskan pathogenesis penyakit dan manifestasi klinik yang muncul pada kasus dihubungkan dengan agent dan vektor!<br>2. Jelaskan hubungan trias epidemiologi yang sesuai dengan kasus!</p>', '<p><br><b>1. Patogenesis penyakit dan manifestasi klinis yang muncul</b></p><p><img style=\"width: 679px;\" src=\"data:image/png;base64,\" data-filename=\"image.png\"><br>Agen penyebabnya adalah Onchocerca volvulus (Filaria volvulus). Hospes definitive parasite ini adalah manusia dan hospes perantaranya adalah lalat Simulium damnosum (black fly). Parasit ini mempunyai daerah penyebaran di Afrika Tengah, Amerika Selatan dan India. Habitat parasite ini di jaringan subkutan dan jaringan limfa.<br></p><p><img style=\"width: 100%;\" src=\"data:image/png;base64,\" data-filename=\"image.png\"><br><br>2. <b>Hubungan trias epidemiologi pada kasus</b><br>Onchocerciass sebagai penyakit menular memiliki unsur segitiga epidemiologi yaitu manusia, lalat hitam sebagai vektor, parasite onchocerca sebagai penyebab penyakit (agent) dan kondisi lingkungan (environment) yang mendukung.<br>- <b>Faktor agen</b> : agen yang berperan pada kasus diatas adalah parasite Onchocerca volvulus yang bertahan hidup / survive dengan memanfaatkan vektor lalat hitam (Genus Simullium). Hal ini dilakukan agar parasite dapat survive berpindah dar satu host ke host lainnya.<br>- <b>Faktor Host</b> : Manusia sebagai hospes definitive dari Onchocerca volvulus.<br>- <b>Faktor lingkungan </b>: pasien pernah tinggal di India dan bekerja sebagai petani, dimana india merupakan salah satu Negara endemis parasite Onchocercha dan tempat tinggal selama bekerja padat penduduk, dan dipinggir sungai, banyak sampah di sekitar tempat tinggal sehingga banyak lalat.</p><p><img style=\"width: 263px;\" src=\"data:image/png;base64,\" data-filename=\"image.png\"><br></p>', '2025-08-15 10:57:01', '2025-08-15 13:46:37');
INSERT INTO `otemplates` VALUES (7, 5, 'Percobaan Soal 2', '2', 'penyakit tropis', '<p><b>Riwayat Penyakit Sekarang</b><br>Seorang laki-laki datang ke poliklinik RS dengan keluhan terdapat benjolan yang seperti menggantung di paha sejak 2 tahun yang lalu. Keluhan benjolan tidak disertai rasa nyeri. Benjolan dirasakan semakin membesar. Keluhan disertai dengan gatal terutama pada malam hari dan kulit menjadi bintik bintik putih di badan. Pasien juga mengeluhkan mata menjadi semakin buram ketika melihat. Keluhan tidak disertai dengan demam, penurunan berat badan, atau penurunan nafsu makan.<br><b>Riwayat Penyakit Dahulu</b><br>- Baru pertama kali mengalami keluhan seperti ini<br>- Riwayat hipertensi disangkal<br>- Riwayat DM disangkal<br><b>Riwayat Peyakit Keluarga</b><br>- Tidak ada keluhan yang sama di keluarga<br>- Riwayat hipertensi dan DM dalam keluarga disangkal<br><b>Riwayat Pribadi Sosial</b><br>- Pasien mengatakan 2 tahun lalu pernah tinggal selama satu tahun di India dan bekerja sebagai petani disana. Tempat tinggal selama bekerja padat penduduk, dan dipinggir sungai, banyak sampah di sekitar tempat tinggal sehingga banyak lalat.<br>- Tempat tinggal pasien sekarang padat penduduk, tidak rawan banjir. Pasien sekarang bekerja sebagai pedagang.<br><b>Pemeriksaan Fisik</b><br>Kesadaran : Composmentis<br>Keadan Umum : tampak sakit sedang<br>Tekanan darah : 120/80 mmHg<br>Suhu : 37,3’C<br>Nadi : 80 x/menit<br>Respirasi : 20 x/menit<br>Mata : konjungtiva pucat -/-, sclera ikterik -/-<br>Visus OS : 1/60<br>Visus OD : 1/60<br>Mulut : sianosis -<br>Leher : pembesaran KGB (-)</p><p><br><u>Thoraks</u><br>- Inspeksi : bentuk dada simetris, otot bantu pernapasan (-), ictus cordis tidak terlihat<br>- Palpasi : nyeri tekan (-), krepitasi (-), ictus cordis teraba regular<br>- Perkusi : sonor seluruh lapang paru, batas jantung dalam batas normal<br>- Auskultasi : vesikuler (+/+), rhonki -/-, wheezing -/- , BJ I-II regular, mur mur (-), gallop (-)</p><p><br><u>Abdomen</u><br>- Inspeksi : distensi (-)<br>- Palpasi : nyeri tekan (-), hepatomegali (-), splenomegali (-)<br>- Perkusi : timpani seluruh lapang abdomen<br>- Auskultasi : Bising Usus 15x/menit</p><p><br>Ekstremitas : akral hangat, CRT &lt; 2 detik</p><p><br><b>Status Lokalis</b></p><p><img style=\"width: 50%;\" src=\"data:image/png;base64,\" data-filename=\"image.png\"><b><br></b><br>Tampak benjolan hiperigmentasi a/r femur dextra, kulit tampak menggantung,<br>permukaan berbenjol, nyeri (-), mobile (-), konsistensi kenyal (+)</p><p><img style=\"width: 50%;\" src=\"data:image/png;base64,\" data-filename=\"image.png\"><br>Tampak gambaran hipopigmentasi (gambaran macan tutul)<br><b>Pemeriksaan Penunjang</b><br>Darah Rutin<br>- Hb : 12 g/dl<br>- Leukosit : 12.000 mm3<br>- Trombosit : 300.000 mm3<br>- Hitung jenis leukosit<br>• Basophil : 0<br>• Eosinophil : 10<br>• Batang : 2<br>• Segmen : 60<br>• Limfosit : 20<br>• Monosit : 8<br>Pemeriksaan Apusan darah didapatkan</p><p><img style=\"width: 50%;\" src=\"data:image/png;base64,\" data-filename=\"image.png\"><br>Terdapat Mikrofilaria, tanpa selubung, cephalic space 1:2 tanpa nukelus terminal<br>Pemeriksaan Serologi<br>Antigen Oncho-27 : (+)</p>', '<p><b><u>Tugas Mahasiswa</u></b><br>1. Jelaskan pathogenesis penyakit dan manifestasi klinik yang muncul pada kasus dihubungkan dengan agent dan vektor!<br>2. Jelaskan hubungan trias epidemiologi yang sesuai dengan kasus!</p>', '<p><br><b>1. Patogenesis penyakit dan manifestasi klinis yang muncul</b></p><p><img style=\"width: 679px;\" src=\"data:image/png;base64,\" data-filename=\"image.png\"><br>Agen penyebabnya adalah Onchocerca volvulus (Filaria volvulus). Hospes definitive parasite ini adalah manusia dan hospes perantaranya adalah lalat Simulium damnosum (black fly). Parasit ini mempunyai daerah penyebaran di Afrika Tengah, Amerika Selatan dan India. Habitat parasite ini di jaringan subkutan dan jaringan limfa.<br></p><p><img style=\"width: 100%;\" src=\"data:image/png;base64,\" data-filename=\"image.png\"><br><br>2. <b>Hubungan trias epidemiologi pada kasus</b><br>Onchocerciass sebagai penyakit menular memiliki unsur segitiga epidemiologi yaitu manusia, lalat hitam sebagai vektor, parasite onchocerca sebagai penyebab penyakit (agent) dan kondisi lingkungan (environment) yang mendukung.<br>- <b>Faktor agen</b> : agen yang berperan pada kasus diatas adalah parasite Onchocerca volvulus yang bertahan hidup / survive dengan memanfaatkan vektor lalat hitam (Genus Simullium). Hal ini dilakukan agar parasite dapat survive berpindah dar satu host ke host lainnya.<br>- <b>Faktor Host</b> : Manusia sebagai hospes definitive dari Onchocerca volvulus.<br>- <b>Faktor lingkungan </b>: pasien pernah tinggal di India dan bekerja sebagai petani, dimana india merupakan salah satu Negara endemis parasite Onchocercha dan tempat tinggal selama bekerja padat penduduk, dan dipinggir sungai, banyak sampah di sekitar tempat tinggal sehingga banyak lalat.</p><p><img style=\"width: 263px;\" src=\"data:image/png;base64,\" data-filename=\"image.png\"><br></p>', '2025-08-27 10:14:53', '2025-08-27 10:16:05');
