INSERT INTO `pbl_bas` VALUES (47, 2, 7, 30, '1', '9', 61, 'Mahasiswa hadir lengkap dan tepat waktu. \r\nmahasiswa sangat kurang belajar dirumahnya sehingga mereka tidak bisa membahas sekenario yang sesuai sasaran belajar padahal tutor sudah mencoba mengarahkan tapi mereka tetap tidak bisa karena kurang membacanya. mahasiswa masih banyak menggunakan bahasa awam dari pada bahasa kedokterannya.', '2026-04-06 09:42:24', '2026-04-06 09:42:24');
INSERT INTO `pbl_bas` VALUES (48, 2, 7, 29, '1', '9', 71, 'KEGIATAN BERJALAN DENGAN LANCAR, NAMUN PEMBAHASAN DAN PENGETAHUAN MAHASISWA TERLALU SUPERFICIAL. \r\nDIHARAPAN UNTUK SELANJUTNYA PERSIAPAN MAHASISWA LEBIH MANTAP LAGI. \r\nADA SATU MAHASISWA ATAS NAMA DANIN MUBARAK TIDAK HADIR', '2026-04-06 09:44:50', '2026-04-06 09:44:50');
