INSERT INTO `pbl_bas` VALUES (66, 2, 7, 30, '2', '8', 10, 'Kelompok mencari referensi dan membuat resume PBL sesuai sasaran belajar yang sudah ditetapkan.\r\nAnggota kelompok sudah mempunyai dasar pengetahuan yang cukup untuk membahas SB.\r\nAnggota kelompok sudah cukup berkontribusi untuk berbagi kepada anggota kelompok yang lain.\r\n\r\nHal-hal yang perlu diperbaiki atau ditingkatkan:\r\nKemampuan anggota kelompok untuk menghubungkan materi-materi yang dibahas.\r\nKemampuan/keterampilan anggota kelompok untuk menjelaskan materi yang  sudah dipelajari.\r\nKemampuan anggota untuk menyimak pendapat yang disampaikan oleh anggota kelompok lain atau yang  disampaiakn oleh tutor.', '2026-04-09 02:43:05', '2026-04-09 02:43:05');
INSERT INTO `pbl_bas` VALUES (67, 2, 7, 23, '2', '9', 76, 'mahasiswa atas nama zhenyfa zharfa tidak hadir tanpa keterangan. \r\ndiskusi berjalan lancar', '2026-04-09 02:44:16', '2026-04-09 02:44:16');
INSERT INTO `pbl_bas` VALUES (68, 2, 7, 25, '2', '10', 6, 'pertemuan ke2 sudah lebih baik dari pertemuan pertama. setiap anggota lebih baik dalam partisipasi diskusi. sasaran belajar terbahas. mahasiswa memberikan respons yang baik dalam diskusi.', '2026-04-09 02:50:57', '2026-04-09 02:50:57');
INSERT INTO `pbl_bas` VALUES (69, 2, 7, 31, '2', '9', 70, '- diskusi berjalan lancar\r\n- satu mahasiswa atas nama muhamad azwar tidak berpendapat, banyak menguap tidak menghargao jalannya diskusi', '2026-04-09 02:51:51', '2026-04-09 02:51:51');
